window.QUESTION_BANK = {"meta":{"total":405,"counts":{"past_exam":200,"unit_practice":185,"authored":20},"generated":"淨零碳題庫 v1（考古題解析由模型依教材撰寫）"},"questions":[{"id":"PE-1151-L11-01","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"某跨國企業集團主要從事資產管理與投資業務，近期規劃依循 SBTi 設定減碳目標。經盤查後發現，其直接營運排放（Scope1）與用電排放（Scope2）占比極低，大部分排放來自投資組合之被投資公司。依據SBTi 相關指引，該企業在設定減碳策略時，應優先強化下列何者？","options":{"A":"提升辦公室能源效率以降低範疇一排放","B":"採購再生能源以降低範疇二排放","C":"管理投融資組合之排放以降低範疇三排放","D":"汰換運輸設備以降低直接排放"},"answer":"C","explanation":"本題企業為資產管理與投資業，直接營運（範疇一）與用電（範疇二）排放極低，主要排放集中於投資組合之被投資公司，屬價值鏈之範疇三投融資排放。依SBTi精神，減碳目標應優先處理占比最大、最具影響力的排放源，故應強化投融資組合排放管理以降低範疇三，選C；A、B、D僅涉及占比極低的範疇一、二，減碳效益有限。","idx":0},{"id":"PE-1151-L11-02","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"為達成將全球升溫控制於 1.5°C 內之目標，於 COP28 之「全球盤點（Global Stocktake）」決議中，明確提出至 2030 年全球再生能源裝置容量之量化目標。下列何者為該目標？","options":{"A":"提升至現有的 2倍","B":"提升至現有的 3倍","C":"提升至現有的 5倍","D":"提升至現有的 10倍"},"answer":"B","explanation":"依COP28全球盤點（Global Stocktake）決議，為守住1.5°C目標，提出2030年全球再生能源裝置容量較現況提升至三倍（並將能源效率改善速度加倍），故選B。教材COP28章節著重損失與損害基金，對再生能源三倍目標著墨有限，本題依公認之COP28決議判定。","idx":1},{"id":"PE-1151-L11-03","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"下列哪項制度是巴黎協定下的重要市場機制？","options":{"A":"清潔發展機制（Clean Development Mechanism, CDM）","B":"聯合履行（Joint Implementation, JI）","C":"國際排放交易（International Emissions Trading, IET）","D":"第六條碳市場機制（Article 6 Carbon Market Mechanisms）"},"answer":"D","explanation":"清潔發展機制(CDM)、聯合履行(JI)與國際排放交易(IET)均為《京都議定書》建立的彈性減量機制，並非巴黎協定。巴黎協定下的市場機制規範於第六條，COP29並通過其運作規則，故屬巴黎協定重要市場機制者為第六條碳市場機制，選D。","idx":2},{"id":"PE-1151-L11-04","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"關於2023年於杜拜舉行的 COP28，在最終決議中，締約方對化石燃料於能源系統中的未來發展達成何種共識？","options":{"A":"立即停止所有化石燃料的投資","B":"在2030年前全面淘汰石油與天然氣","C":"在能源系統中轉型脫離化石燃料","D":"僅針對燃煤進行限制，不涉及石油與天然氣"},"answer":"C","explanation":"COP28最終決議就能源系統達成「轉型脫離化石燃料（transition away from fossil fuels）」之共識，為聯合國氣候大會決議首次明文觸及化石燃料轉型，選C。並非立即停止所有投資(A)、2030前全面淘汰石油天然氣(B)或僅限制燃煤(D)等更強或更窄之表述。","idx":3},{"id":"PE-1151-L11-05","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於RE100，下列敘述何者不正確？","options":{"A":"RE100促使企業使用再生能源，所接受的再生能源包含風力、太陽能、地熱、水力、生質能、核能等 6種","B":"再生能源價格波動相較化石燃料小，並有逐漸下降的趨勢，加入 RE100可分散未來能源短缺的風險，並控制生產成本","C":"目前全球許多企業響應並承諾於 2050年前使用100％再生能源電力","D":"RE100認證可使企業接軌國際大廠，形成淨零碳排供應鏈，使企業合作關係更緊密"},"answer":"A","explanation":"依教材，RE100所接受之再生能源依溫室氣體盤查議定書定義，包含風力、太陽能、地熱、生質能、水力、綠氫等，明確「不包含核能」，故A將核能列入並稱6種之敘述不正確，為應選答案。B、C、D關於價格趨勢、2050年前承諾100%綠電及接軌供應鏈之敘述均符合RE100精神。","idx":4},{"id":"PE-1151-L11-06","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"根據經濟部（2024）能源統計手冊，我國 2024年發電結構中占比最高為哪一種發電方式？","options":{"A":"燃煤","B":"燃氣","C":"再生能源","D":"核能"},"answer":"B","explanation":"依題旨之能源統計，我國近年發電結構以燃氣占比最高，與政府「增氣減煤」能源轉型方向一致（2030年規劃燃氣約50%），故選B。燃煤占比次之，再生能源與核能占比相對較低。","idx":5},{"id":"PE-1151-L11-07","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"根據經濟部（2024）能源統計手冊，臺灣能源供應高度依賴進口，其能源自給率約落在哪一區間？","options":{"A":"1～3%","B":"4～7%","C":"8～12%","D":"13%以上"},"answer":"B","explanation":"臺灣能源高度依賴進口，自產能源有限，能源自給率長期偏低，約落在個位數百分比區間，依題意符合4～7%，選B。此反映我國推動再生能源與能源轉型以強化能源安全之背景。教材未列具體數值，係依題旨能源統計判定。","idx":6},{"id":"PE-1151-L11-08","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"丹娜絲風災暴露臺灣電網的韌性問題，關於分散式電源（如太陽光電）在電網中斷時未能發揮功能的原因，下列何者正確？","options":{"A":"颱風導致大型火力電廠受損，無法滿載發電","B":"光電場因設備位於戶外，普遍受強風直接損壞","C":"光電案場多與大電網系統相連，電網中斷時會啟動保護機制自動斷電","D":"臺灣儲能系統已足夠，但缺乏發電設備"},"answer":"C","explanation":"分散式太陽光電案場多以併網方式與大電網相連，當電網因風災中斷時，為保護設備與人員安全並避免孤島運轉，逆變器等會啟動保護機制自動斷電，故電網中斷時無法持續供電，選C。並非火力電廠受損(A)、設備普遍被強風直接損壞(B)或儲能已足夠(D)。","idx":7},{"id":"PE-1151-L11-09","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"臺灣水資源面臨豐枯差異日趨明顯的挑戰。根據水資源調適政策中，由「需求面」檢討管理以促進水資源使用效益的策略，下列何者不屬於其規劃內容？","options":{"A":"參考聯合國推動之水足跡概念，推動標示產品耗水量，減少高耗水產品之消費","B":"建立合理公平之用水轉移機制，並考慮由不缺水國家輸入高耗水產品，以降低國內水資源消耗","C":"推廣精密灌溉技術，並獎勵利用雨水灌溉之農業，以減少灌溉用水之消耗","D":"藉由科技造水，如海水淡化與廢汙水回收工程等，以提升備援供水能力"},"answer":"D","explanation":"題目問水資源「需求面」管理策略，旨在抑低或調整用水需求以提升使用效益。A標示耗水量、B用水轉移與輸入高耗水產品、C精密灌溉與雨水利用，均屬需求面管理。D海水淡化與廢汙水回收屬「供給面」增加備援水源之作法，非需求面，故選D。","idx":8},{"id":"PE-1151-L11-10","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"根據經濟部二次能源轉型政策，臺灣規劃在 2030年的電力結構目標中，燃氣發電、再生能源與燃煤發電的占比分別為何？","options":{"A":"燃氣50%、再生能源 30%、燃煤 20%","B":"燃氣42%、燃煤39%、再生能源 12%","C":"燃氣40%、再生能源 40%、燃煤 20%","D":"燃氣60%、再生能源 20%、燃煤 20%"},"answer":"A","explanation":"依二次能源轉型規劃，2030年電力結構目標約為燃氣50%、再生能源30%、燃煤20%，呈現增氣、展綠、減煤的轉型方向，故選A。其餘選項之占比配置與官方規劃不符。教材載2050年再生能源占比60~70%，2030年具體配比依官方能源轉型政策判定。","idx":9},{"id":"PE-1151-L11-11","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"下列何者屬於可作為能源使用的燃料形式，而非僅為原料或衍生產品？","options":{"A":"生物質","B":"生質廢棄物","C":"生物燃料","D":"生物炭"},"answer":"C","explanation":"生物質(biomass)、生質廢棄物與生物炭主要屬原料或衍生產品，生物炭多作為土壤改良或碳封存用途；生物燃料（biofuel）則是可直接作為能源使用的燃料形式，故選C。","idx":10},{"id":"PE-1151-L11-12","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"下列何者為關注氣候變遷可能導致資產錯誤定價及資本配置失衡，進而影響金融體系穩定性的國際揭露框架？","options":{"A":"TNFD","B":"TIFD","C":"TCFD","D":"TAFD"},"answer":"C","explanation":"關注氣候變遷恐導致資產錯誤定價與資本配置失衡、進而危及金融體系穩定之揭露框架，為由金融穩定委員會(FSB)成立的TCFD，選C。TNFD針對自然、TIFD／TAFD為混淆選項，均非以氣候相關財務風險與金融穩定為核心。","idx":11},{"id":"PE-1151-L11-13","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"依據氣候變遷相關財務揭露（TCFD）架構，氣候風險可區分為「實體風險」與「轉型風險」。下列何者屬於實體風險？","options":{"A":"碳定價政策導致企業營運成本上升","B":"市場需求與營運成本結構發生變化","C":"暴雨、颱風、乾旱等極端氣候事件","D":"新技術導入導致既有技術設備淘汰"},"answer":"C","explanation":"依TCFD，實體風險指氣候變遷引發極端天氣所致之災害衝擊，如暴雨、颱風、乾旱等，選C。A碳定價政策成本、B市場需求與成本結構變化、D新技術導致既有設備淘汰，均屬政策法規、市場或技術面之「轉型風險」。","idx":12},{"id":"PE-1151-L11-14","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"依據碳揭露計畫（Carbon Disclosure Project, CDP）之官方揭露問卷，下列哪些領域屬於其主要環境影響揭露範疇？","options":{"A":"氣候變遷、水、森林、塑膠","B":"氣候變遷、能源、交通、工業","C":"氣候變遷、水、生物多樣性、廢棄物","D":"氣候變遷、生物多樣性、水、土壤"},"answer":"A","explanation":"依CDP官方問卷，主要環境揭露範疇為氣候變遷、水、森林，並陸續擴及塑膠（2023年納入），2024年整併為單一問卷，故選A。B、C、D所列能源、交通、工業、廢棄物、土壤等，非CDP問卷之核心揭露主題組合。","idx":13},{"id":"PE-1151-L11-15","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"下列哪一項倡議為投資者聯合推動的氣候行動倡議，旨在向高排放公司施壓，以設定科學減排目標並符合巴黎協定 1.5°C 路徑？","options":{"A":"RE100","B":"EV100","C":"Climate Action 100+","D":"科學基礎目標倡議（SBTi）"},"answer":"C","explanation":"由投資人聯合發起、向高排放企業施壓使其設定科學減量目標並對齊巴黎協定1.5°C路徑之倡議為Climate Action 100+，選C。RE100（再生能源）、EV100（電動運具）、SBTi（企業自行設定科學目標）性質不同，非以投資人集體施壓為核心。教材未直接涵蓋，依公認國際倡議定位判定。","idx":14},{"id":"PE-1151-L11-16","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"關於COP29 正式通過的巴黎碳市場運作規則中，下列何者是碳市場制度的核心基礎？","options":{"A":"強化國家報告機制","B":"增加碳權交易數量","C":"不重複計算與使用","D":"統一定價機制"},"answer":"C","explanation":"巴黎協定第六條碳市場（COP29通過其運作規則）之核心基礎在於避免重複計算與重複使用減量成果，確保一筆減量不被兩方同時計入，以維護市場誠信，故選C。並非強化國家報告(A)、增加交易量(B)或統一定價機制(D)。","idx":15},{"id":"PE-1151-L11-17","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"關於巴黎協定的法律約束力特性，下列何者最為正確？","options":{"A":"有罰則的法律約束","B":"自願性協議","C":"非正式的國際條約","D":"無罰則的法律約束"},"answer":"D","explanation":"《巴黎協定》為具法律約束力的國際條約，惟各國減量以國家自主貢獻(NDC)方式自訂提出，未對未達標設有罰則，屬「無罰則的法律約束」，選D。故非自願性協議(B)或非正式條約(C)，亦非有罰則之約束(A)。","idx":16},{"id":"PE-1151-L11-18","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"依據《巴黎協定》第六條機制，國際轉讓減緩成果（ITMOs）在各締約方達成國家自定貢獻（NDCs）的過程中，扮演何種核心角色？","options":{"A":"支援技術移轉和能力建置，但不包含轉移額度","B":"允許締約方之間互相轉讓環境稅收收益","C":"作為國際間自願轉讓的減緩成果，以促進國家自定貢獻的達成","D":"僅用於監控減排進度，不涉及實質減排成果轉換"},"answer":"C","explanation":"依巴黎協定第六條，國際轉讓減緩成果(ITMOs)係作為國家間自願轉讓之減量成果，供締約方用以達成其國家自定貢獻(NDC)目標，選C。其涉及實質減量額度之移轉，並非僅技術移轉與能力建置(A)、稅收移轉(B)或僅監控進度(D)。","idx":17},{"id":"PE-1151-L11-19","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L111","stem":"依據《巴黎協定》，在已宣示淨零排放目標之各國政策實務中，下列何者為最主要之兩大減碳政策工具？","options":{"A":"強化跨國間的氣候技術轉移合作，並積極推動大規模核能發電建設","B":"推動淨零目標之內國法化（Legislation）程序，並採用多元碳定價機制引導減排","C":"建立企業強制性氣候資訊揭露，並導入科學基礎減量目標（SBTi）之設定","D":"實踐聯合國全球永續發展目標（SDGs），並致力於解決極端貧窮與消除貧困"},"answer":"B","explanation":"已宣示淨零之各國，實務上最主要之兩大減碳政策工具為：推動淨零目標之內國法化（立法），以及採多元碳定價機制（如碳稅費、排放交易）引導減排，選B。A核能、C強制揭露與SBTi、D落實SDGs消除貧困雖為相關作為，但非普遍認定之兩大核心政策工具。","idx":18},{"id":"PE-1151-L11-20","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於氣候變遷因應法中「碳費制度」之相關子法，下列何者非屬直接規範碳費徵收或費率機制之內容？","options":{"A":"碳費收費對象與費率","B":"指定減量目標","C":"溫室氣體盤查登錄管理","D":"自主減量計畫審核"},"answer":"C","explanation":"碳費制度三項配套子法為「碳費收費辦法」（含收費對象與費率，對應A）、「自主減量計畫管理辦法」（對應D自主減量計畫審核）及「碳費徵收對象溫室氣體減量指定目標」（對應B指定減量目標）。溫室氣體盤查登錄管理屬盤查登錄相關規範，非直接規範碳費徵收或費率之子法，故選C。","idx":19},{"id":"PE-1151-L11-21","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於企業參與科學基礎減量目標倡議（Science Based Targets initiative, SBTi）與全球再生能源倡議（RE100），下列敘述何者正確？","options":{"A":"企業可以同時參與 SBTi 和RE100，因為兩者的目標並不衝突，且可以互補","B":"企業參與 SBTi 或RE100均屬於強制性法律規定，特別是針對高碳排之大型企業","C":"企業只需參與其中一個倡議，因為 SBTi和RE100的目標完全重疊","D":"企業必須先達到 SBTi 設定的科學減碳目標，才能申請加入 RE100"},"answer":"A","explanation":"SBTi（設定科學減碳目標）與RE100（承諾100%使用再生能源）均為自願性倡議，目標方向一致且可互補，企業可同時參與，選A。兩者非強制法律規定(B)、目標非完全重疊(C)，亦無「須先達成SBTi目標才能加入RE100」之先後限制(D)。","idx":20},{"id":"PE-1151-L11-22","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於科學基礎減量目標倡議（Science Based Targets initiative, SBTi）對中小型企業的定義條件，下列何者不正確？","options":{"A":"員工人數少於 500 人","B":"非子公司","C":"排除金融機構（FI）","D":"企業必須是獨立的私人企業"},"answer":"D","explanation":"SBTi對中小型企業(SME)之認定條件通常包含員工人數少於500人、非子公司、排除金融機構(FI)等（教材另以範疇一、二排放量門檻等界定）。SME並不限於私人企業，公開發行或上市公司亦可符合，故「必須是獨立的私人企業」之敘述不正確，選D。","idx":21},{"id":"PE-1151-L11-23","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"依據科學基礎減量目標倡議（Science Based Targets initiative, SBTi）的要求，若某企業的範疇三（Scope3）排放量高於排放總量的 40%，則其設定之近期減量目標至少需涵蓋多少比例之範疇三排放量？","options":{"A":"40%","B":"50%","C":"67%","D":"90%"},"answer":"C","explanation":"依SBTi規定，當企業範疇三排放量超過總排放量40%時，其近期（短期）減量目標至少須涵蓋範疇三排放量的67%，選C，以確保占比重大的價值鏈排放被納入目標管理。教材未列此特定比例，係依SBTi公認準則判定。","idx":22},{"id":"PE-1151-L11-24","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"依據金融監督管理委員會現行規定，永續報告書須取得會計師依相關確信準則出具確信報告之適用產業，下列何者正確？","options":{"A":"僅實收資本額達新臺幣 50億元以上之公司","B":"食品工業、餐飲營收占比達 50%以上、化學工業及金融保險業","C":"全體已編製永續報告書之上市櫃公司","D":"僅適用於水泥工業、塑膠工業、鋼鐵工業"},"answer":"B","explanation":"依金管會現行規定，永續報告書須取得會計師依確信準則出具確信報告之產業，為食品工業、餐飲收入占比達50%以上之公司、化學工業及金融保險業，選B。並非僅以實收資本額50億元為門檻(A)、全體上市櫃公司(C)或僅水泥塑膠鋼鐵(D)。此屬主管機關現行規定，教材未直接涵蓋。","idx":23},{"id":"PE-1151-L11-25","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"某中型紡織製造商員工人數為 400人，決定透過 SBTi 快速路徑（SME Route）設定目標。該公司總排放量中，範疇三（Scope 3）占 50%。關於該公司目標設定的敘述，下列何者不正確？","options":{"A":"中型公司可跳過標準企業所需的「承諾（Commit）」步驟","B":"該公司範疇一和範疇二的減排目標，應對標 1.5°C 路徑（例如，以 2020年為基準年，2030 年減少42%）","C":"該公司必須設定範疇三的減排目標，且長期目標必須覆蓋至少 90%的範疇三排放量","D":"由於該公司為獨立公司且員工人數少於 500人，因此可視為 SBTi 定義的中小型企業（SME）"},"answer":"A","explanation":"本題應選不正確之敘述。B（範疇一、二對標1.5°C、以2020為基準2030減約42%）、C（長期須涵蓋至少90%範疇三）、D（獨立且員工少於500人可視為SME）均符合SBTi規範。惟本公司範疇三占比達50%（超過40%門檻），須設定並涵蓋範疇三減量目標，不適用逕行跳過承諾步驟之簡化處理，故A敘述於本情境不正確。","idx":24},{"id":"PE-1151-L11-26","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"依據《臺灣 2050淨零排放路徑及策略總說明》，在推動工業部門減碳過程中，下列何者被視為關鍵減量技術？","options":{"A":"推動核能發電以降低整體電力排放","B":"擴大太陽光電應用以提升再生能源占比","C":"強化風力發電建置以增加綠電供應","D":"發展碳捕捉與封存技術以達成碳減量"},"answer":"D","explanation":"依《臺灣2050淨零排放路徑及策略總說明》，工業部門之關鍵減量技術為碳捕捉、利用與封存(CCUS)，用以移除製程與能源設施難以削減之碳排放，選D。核能(A)不符非核家園方向，太陽光電(B)、風力發電(C)屬電力部門再生能源，非工業部門之關鍵減量技術。","idx":25},{"id":"PE-1151-L11-27","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於針對具碳洩漏（Carbon Leakage）風險之進口產品進行排放量調查，並要求其平衡支付相關碳價成本之機制，下列何者正確？","options":{"A":"保護稅率","B":"碳邊境調整","C":"貿易配額","D":"反傾銷稅"},"answer":"B","explanation":"針對具碳洩漏風險之進口產品調查其排放量，並要求其平衡支付相當於境內之碳價成本的機制，即「碳邊境調整」（如歐盟CBAM），選B。保護稅率(A)、貿易配額(C)、反傾銷稅(D)均非以平衡碳價、防止碳洩漏為目的。","idx":26},{"id":"PE-1151-L11-28","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於國際財務報導準則（IFRS）之主要目的，下列敘述何者正確？","options":{"A":"僅用於企業內部管理決策，不對外揭露","B":"著重企業長期永續績效之揭露與評估","C":"主要用於揭露企業環境與社會績效","D":"提供一致性財務報導準則，以提升資訊可比較性"},"answer":"D","explanation":"國際財務報導準則(IFRS)之主要目的，在於提供一致的財務報導準則，以提升不同企業間財務資訊的可比較性與透明度，選D。其係對外揭露（非A），以財務資訊為主而非以永續或環境社會績效為核心（非B、C，後者屬ISSB永續準則範疇）。","idx":27},{"id":"PE-1151-L11-29","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於歐盟於 2026 年 1 月 1 日正式實施的歐盟碳邊境調整機制（Carbon Border Adjustment Mechanism, CBAM），「納入豁免門檻」由原先按貨物價值改為按「年度進口重量」規定，下列何者符合豁免門檻？","options":{"A":"年度進口總值≤150 歐元","B":"年度進口總量≤50 噸","C":"批次進口重量≤50 噸","D":"年度進口總量≤100 噸"},"answer":"B","explanation":"依2026年正式實施之CBAM修正，納入豁免門檻由按貨物價值改為按「年度進口總量」計，年度進口總量在50噸以下者可豁免，選B。此以重量門檻取代原先約150歐元之價值門檻。教材載原始規範，本題依修正後規定判定。","idx":28},{"id":"PE-1151-L11-30","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於歐盟於 2026 年 1 月 1 日正式實施的歐盟碳邊境調整機制（Carbon Border Adjustment Mechanism, CBAM），申報截止日由原先的「每年 5月31日前」延至哪一天？","options":{"A":"6月30日","B":"7月31日","C":"9月30日","D":"12月31 日"},"answer":"C","explanation":"依CBAM修正，年度申報截止日由原先每年5月31日延後至9月30日，選C，給予申報人更充裕之申報準備時間。教材載原5月31日規定，本題依修正後時程判定。","idx":29},{"id":"PE-1151-L11-31","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於歐盟於 2026 年 1 月 1 日正式實施的歐盟碳邊境調整機制（Carbon Border Adjustment Mechanism, CBAM），自 2027年起，申報人每季必須至少持有多少比例的預估憑證量？","options":{"A":"20%","B":"30%","C":"50%","D":"80%"},"answer":"C","explanation":"依CBAM修正，自2027年起，申報人每季至少須持有相當於其預估應繳憑證量50%之CBAM憑證，選C，以兼顧現金流負擔並確保履約。教材未涵蓋此季度持有比例，係依修正後規定判定。","idx":30},{"id":"PE-1151-L11-32","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於歐盟於 2026 年 1 月 1 日正式實施的歐盟碳邊境調整機制（Carbon Border Adjustment Mechanism, CBAM），下列哪一個項目被新增排除於 CBAM適用範圍？","options":{"A":"所有化學品","B":"軍事使用貨品","C":"鋼鐵製品","D":"所有電力"},"answer":"B","explanation":"依CBAM修正，新增將「軍事使用貨品」排除於適用範圍之外，選B。其餘如所有化學品(A)、鋼鐵製品(C)、所有電力(D)並非此次新增排除之項目。教材未涵蓋此新增排除，係依修正後規定判定。","idx":31},{"id":"PE-1151-L11-33","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"下列何者未納入臺灣十二項關鍵戰略中的「前瞻能源」內？","options":{"A":"海洋能","B":"地熱發電","C":"氫能","D":"生質能"},"answer":"C","explanation":"依臺灣十二項關鍵戰略，「前瞻能源」以基載型地熱、海洋能為發展重點，並擴大生質能使用；氫能則獨立列為另一項戰略（氫能），不屬前瞻能源之範疇，故選C。","idx":32},{"id":"PE-1151-L11-34","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於臺灣十二項關鍵戰略，下列何者為「綠色金融」的主要目的？","options":{"A":"規範銀行業的碳排放量","B":"強制要求企業揭露氣候風險資訊","C":"引導資金流向支持淨零轉型及綠色產業","D":"制定碳費的收費標準"},"answer":"C","explanation":"依十二項關鍵戰略，「綠色金融」之主要目的在於運用金融市場力量，引導資金流向支持淨零轉型及綠色產業，提升金融業與產業之氣候韌性，選C。並非規範銀行業碳排放量(A)、強制揭露氣候風險(B)或制定碳費收費標準(D)。","idx":33},{"id":"PE-1151-L11-35","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"企業依循國際財務報導準則（IFRS）S1進行揭露時，下列何者為其核心原則？","options":{"A":"著重與投資人決策相關之資訊揭露","B":"以歷史資訊為主要揭露基礎，輔以未來趨勢說明","C":"優先揭露環境議題相關資訊，以回應永續發展需求","D":"永續資訊揭露可獨立於財務報表之外呈現"},"answer":"A","explanation":"IFRS S1為一般性永續揭露準則，其核心原則在於著重揭露與投資人（資本市場使用者）決策攸關之永續相關資訊，選A。其強調前瞻性而非以歷史資訊為主(B)、不限於環境議題(C)，且永續資訊應與財務報表連結呈現而非完全獨立(D)。教材著墨有限，依IFRS S1公認原則判定。","idx":34},{"id":"PE-1151-L11-36","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"臺灣預計至 2030年自然碳匯仍無法大量增加，下列何者為其受限的主因？","options":{"A":"森林覆蓋率不斷下降","B":"地理環境限制可擴張碳匯的幅度","C":"氣候變遷使樹木加速生長","D":"土地大量淪為農業"},"answer":"B","explanation":"臺灣森林覆蓋率已高、平地造林與可供擴張碳匯之土地有限，受地理環境條件限制，至2030年自然碳匯難以大量增加，選B。並非森林覆蓋率不斷下降(A)、氣候變遷使樹木加速生長(C)或土地大量淪為農業(D)。","idx":35},{"id":"PE-1151-L11-37","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"下列何者為臺灣推動碳捕捉、利用與封存（Carbon Capture, Utilization and Storage, CCUS）的主要目的？","options":{"A":"增加燃煤產能","B":"提升能源密度","C":"協助難減量產業減碳","D":"提高汽車燃油效率"},"answer":"C","explanation":"臺灣推動碳捕捉、利用與封存(CCUS)的主要目的，在於協助鋼鐵、石化等難以減量產業及能源設施移除碳排放，選C。並非增加燃煤產能(A)、提升能源密度(B)或提高汽車燃油效率(D)。","idx":36},{"id":"PE-1151-L11-38","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"依據臺灣官方能源轉型規劃，下列何者最能描述氫能在 2050 年能源系統中的角色？","options":{"A":"短期即取代所有電力","B":"屬於長期關鍵能源之一","C":"僅用於家用電器","D":"政府無氫能相關規劃"},"answer":"B","explanation":"依官方能源轉型規劃，氫能被定位為長期（2050年）淨零能源系統的關鍵選項之一，用於零碳製程原料、運輸及無碳發電，選B。並非短期即取代所有電力(A)、僅用於家用電器(C)，政府亦有相關規劃（非D）。","idx":37},{"id":"PE-1151-L11-39","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於歐盟碳邊境調整機制（Carbon Border Adjustment Mechanism, CBAM）的主要目的，除解決碳洩漏問題外，另一個主要目的為何？","options":{"A":"確保所有進口貨品均符合歐洲安全標準","B":"鼓勵其他國家推動碳定價措施","C":"提升歐盟內部的工業技術標準","D":"促使出口國轉換經濟發展模式"},"answer":"B","explanation":"CBAM除防止碳洩漏、維護歐盟產業競爭力外，另一主要目的為透過對進口品課徵碳成本，促使並鼓勵其他國家推動自身碳定價措施，選B。並非確保符合安全標準(A)、提升歐盟技術標準(C)或迫使出口國轉換經濟模式(D)。","idx":38},{"id":"PE-1151-L11-40","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"在設定內部碳定價時，下列何種方式用來評估某企業單位面對減碳情境，或是因應法遵碳成本支出等價格？","options":{"A":"市場價格調查","B":"影子碳價或隱含碳價","C":"能源稽核報告","D":"企業減排潛力分析"},"answer":"B","explanation":"在內部碳定價中，用以評估企業面對減碳情境或未來法遵碳成本之假設性價格，為影子碳價（隱含碳價），選B。其不涉及實際金錢交易，而是於投資決策中假設一碳價以評估風險與可行性。並非市場價格調查(A)、能源稽核報告(C)或減排潛力分析(D)。","idx":39},{"id":"PE-1151-L11-41","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"關於核發減量額度（Carbon Credits，亦稱碳信用額度）之必要流程，下列何者不正確？","options":{"A":"基礎情境比較","B":"繳交碳費","C":"計畫確證","D":"監測查證"},"answer":"B","explanation":"核發減量額度（碳信用）之必要流程包括基礎情境（基線）比較(A)、計畫確證(C)與監測查證(D)等步驟。繳交碳費屬碳費制度下之繳費義務，與減量額度之核發流程無關，故不正確者為B。","idx":40},{"id":"PE-1151-L11-42","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"在碳減量或移除計畫（Carbon Reduction／Removal Project）品質要求中，判定「外加性（Additionality）」時，下列哪一項最能反映其核心評估原則？","options":{"A":"可量測、可報告、可驗證","B":"法規、投資、障礙性及普遍性要求","C":"法規要求、碳關稅要求、誠信原則","D":"不對社會環境造成影響"},"answer":"B","explanation":"判定外加性(Additionality)之核心評估原則，在於檢視該減量是否超越法規要求、具投資（財務）障礙、面臨執行障礙，且非屬普遍（常規）作法，即法規、投資、障礙性及普遍性等測試，選B。A之可量測、可報告、可驗證(MRV)屬監測查證原則，非外加性之判定。","idx":41},{"id":"PE-1151-L11-43","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"下列何者為碳交易所（Carbon Exchange）在碳權市場流程中的主要作用？","options":{"A":"管理內部帳戶的碳權轉移","B":"提供拍賣、定價及協議交易的平台","C":"直接核發碳權給計畫開發商(賣方)","D":"協助計畫註冊及資本投資"},"answer":"B","explanation":"碳交易所在碳權市場流程中的主要作用，是提供拍賣、定價及協議交易的平台，媒合買賣雙方供需，選B。核發碳權係由主管機關或方案機構為之（非C），計畫註冊、資本投資及內部帳戶轉移亦非交易所之核心功能（非A、D）。","idx":42},{"id":"PE-1151-L11-44","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"不同於排放額度交易制度，碳稅（Carbon Tax）之徵收方式主要依據下列何者？","options":{"A":"規定某個排放交易額度基準以上者","B":"規定自願減排計畫基準以上者","C":"規定某個排放量基準以上者","D":"按能源使用量估算課徵"},"answer":"C","explanation":"不同於以排放額度（配額）為基礎的排放交易制度，碳稅主要係針對排放者超過某一排放量基準以上之排放量課徵，選C。其以排放量為課徵依據，而非以交易額度基準(A)或自願減量計畫基準(B)為準。","idx":43},{"id":"PE-1151-L11-45","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"企業推動供應鏈減碳措施，主要對應下列哪一種排放範疇？","options":{"A":"範疇一","B":"範疇二","C":"範疇三","D":"非屬溫室氣體盤查範圍"},"answer":"C","explanation":"企業推動供應鏈減碳，主要對應範疇三（Scope 3）排放，選C。範疇三涵蓋企業價值鏈上下游（如採購、原料、運輸、產品使用等）之間接排放，供應鏈即屬此範疇；範疇一為直接排放、範疇二為外購電力等能源之間接排放。","idx":44},{"id":"PE-1151-L11-46","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"依據ISO14068-1：2023，碳中和聲明必須具備下列何項要素？","options":{"A":"直接購買碳權即可","B":"需進行完整量化並查驗","C":"需組成專責團隊","D":"需列出抵換量計算公式"},"answer":"B","explanation":"依ISO 14068-1:2023，碳中和聲明須建立在完整的溫室氣體量化並經查驗（查證）之基礎上，以確保聲明真實可信，選B。僅直接購買碳權(A)不符該標準優先減量、要求量化與查證之原則；組成專責團隊(C)、列出抵換量計算公式(D)非其必要構成要素。","idx":45},{"id":"PE-1151-L11-47","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"依據ISO14068-1：2023，為提升碳中和公信力，碳中和宣告通常需包含排放量、抵銷量、期程與範疇等資訊。下列哪一項資訊不屬於宣告中必須揭露的內容？","options":{"A":"購買碳權之形式與註銷量","B":"供應鏈碳中和進度報告","C":"碳中和期程與範疇界定","D":"GHG 排放量與 GHG移除量的敘述"},"answer":"B","explanation":"依ISO 14068-1:2023，碳中和宣告須揭露排放量與移除量、抵銷（抵換）量與碳權形式及註銷量、期程與範疇界定等資訊。「供應鏈碳中和進度報告」非宣告中必須揭露之項目，故選B。","idx":46},{"id":"PE-1151-L11-48","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"根據ISO14068-1：2023 碳中和管理計畫碳足跡抵換要求，下列何者為執行溫室氣體減量的優先順序？","options":{"A":"溫室氣體減量→溫室氣體移除→碳抵換","B":"碳抵換→溫室氣體移除→溫室氣體減量","C":"溫室氣體移除→溫室氣體減量→碳抵換","D":"碳抵換→溫室氣體減量→溫室氣體移除"},"answer":"A","explanation":"依ISO 14068-1:2023碳足跡抵換要求，溫室氣體減量之優先順序為：先進行溫室氣體減量，次為加強溫室氣體移除，最後才以碳抵換處理殘餘排放，選A。該標準強調優先於價值鏈內實質減排與移除，而非依賴抵換。","idx":47},{"id":"PE-1151-L11-49","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"根據ISO14068-1：2023 標準，在碳中和計畫中衡量溫室氣體排放減量，可採用下列哪兩種方法？","options":{"A":"基線及替代","B":"絕對值和強度值","C":"百分比變化和總值減少","D":"年增率與累計總量"},"answer":"B","explanation":"依ISO 14068-1:2023，衡量溫室氣體排放減量可採「絕對值」與「強度值」兩種目標類型，選B。絕對目標以排放總量衡量，強度目標以單位產出等基準衡量，兩者亦可併用。","idx":48},{"id":"PE-1151-L11-50","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第一次","unit":"L112","stem":"在ISO14068-1：2023 的碳中和執行步驟中，下列哪一個步驟需要最先執行，以確定減量與移除目標？","options":{"A":"完成碳中和報告","B":"制定溫室氣體減量計畫專案","C":"界定範疇以及選定欲碳中和標的物","D":"直接進行碳抵換"},"answer":"C","explanation":"依ISO 14068-1:2023碳中和執行步驟，須最先界定範疇並選定欲達成碳中和之標的物，作為後續盤查量化及設定減量、移除目標之基礎，選C。完成碳中和報告(A)、制定減量計畫專案(B)、進行碳抵換(D)均為界定標的與範疇之後的步驟。","idx":49},{"id":"PE-1151-L12-01","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"事業單位依「溫室氣體排放量盤查登錄及查驗管理辦法」進行盤查時，溫室氣體總排放量應計算至小數點後第幾位？","options":{"A":"第三位","B":"第一位","C":"第四位","D":"第二位"},"answer":"A","explanation":"依溫室氣體排放量盤查登錄及查驗管理辦法，事業申報之溫室氣體總排放量應計算至小數點後第三位，故選A。此屬法規對數值呈現精度的統一規定，目的在確保各事業申報結果具一致性與可比較性；教材雖以範例計算示範取位，但總量申報位數係依辦法規範辦理。","idx":50},{"id":"PE-1151-L12-02","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"進行組織型溫室氣體盤查時，某企業使用外購電力，並另外自設鍋爐補充熱能。下列何種歸類方式最正確？","options":{"A":"自設鍋爐屬能源間接排放，外購電力屬直接排放","B":"外購電力屬能源間接排放，自設鍋爐屬直接排放","C":"兩者皆屬能源間接排放","D":"兩者皆屬直接排放"},"answer":"B","explanation":"依ISO 14064-1，外購電力屬輸入能源之間接排放（類別二／範疇二），企業自設鍋爐燃燒燃料所產生者為自有設施之直接排放（類別一／範疇一），故選B。選項A將兩者對調，混淆了直接燃燒與外購能源的分類原則。","idx":51},{"id":"PE-1151-L12-03","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"關於組織型溫室氣體盤查中，企業使用「委外物流」運輸產品，但不具有物流車輛之控制權，則該運輸產生之溫室氣體排放應歸類為何？","options":{"A":"固定排放","B":"能源間接排放","C":"製程排放","D":"其他間接排放"},"answer":"D","explanation":"委外物流且不具車輛控制權，運輸排放非企業自有設施之直接排放、亦非外購能源之能源間接排放，而屬與營運相關之其他間接排放（運輸類別／範疇三），故選D。固定排放與製程排放皆屬直接排放，能源間接僅限外購電力蒸汽，均不符。","idx":52},{"id":"PE-1151-L12-04","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"若企業進行組織型溫室氣體盤查採用營運控制權原則設定邊界，下列哪一種情況會被納入排放量？","options":{"A":"財務投資但無營運控制權","B":"無持股但具有營運決策權","C":"僅提供設備使用權","D":"與企業無契約關係"},"answer":"B","explanation":"採營運控制權法時，只要企業具有完全主導並執行事業體營運政策之權力，即應100%認列其排放，與持股比例無關，故B（無持股但具營運決策權）應納入。財務投資而無營運控制權、僅提供設備使用權或無契約關係者，依營運控制法不納入。","idx":53},{"id":"PE-1151-L12-05","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"若企業欲提高盤查結果的可查證性，下列哪一項行為最為重要？","options":{"A":"所有數據以估算方式呈現","B":"活動數據來源可追溯","C":"排除不確定數據","D":"僅呈現電力排放"},"answer":"B","explanation":"提高盤查結果可查證性的關鍵在於活動數據來源可追溯，使查驗人員能依原始單據或量測紀錄重現計算，符合透明度與準確性原則，故選B。全以估算呈現、刻意排除不確定數據或僅呈現電力排放，反而降低完整性與可信度。","idx":54},{"id":"PE-1151-L12-06","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"依據ISO14064-1：2018 之規範，關於「不確定性（Uncertainty）」與「誤差（Error）」，下列敘述何者正確？","options":{"A":"透過校正儀器可以完全消除不確定性，但無法消除誤差","B":"誤差是指測量值與真值之間的差異，應予以修正","C":"若不確定性評估結果為±5%，代表數據錯誤率為 5%","D":"查驗機構的主要職責是計算不確定性，而非發現誤差"},"answer":"B","explanation":"誤差（error）指測量值與真值間的差異，可辨識來源並予以修正；不確定性（uncertainty）則為對結果變異程度的定量描述，無法完全消除。故B正確。不確定性±5%非指錯誤率5%，校正無法完全消除不確定性，查驗機構職責亦非僅計算不確定性。","idx":55},{"id":"PE-1151-L12-07","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"依據ISO14064-1：2018 之規範，除了傳統的燃燒與製程排放外，直接排放（Category 1）還額外包含下列哪一個項目？","options":{"A":"土地使用、土地使用變更及林業","B":"委外廢棄物處理","C":"租賃資產排放","D":"投資產生的排放"},"answer":"A","explanation":"依ISO 14064-1，直接排放（類別一）除固定燃燒、製程、移動燃燒與逸散排放外，尚包含土地使用、土地使用變更及林業（LULUCF）所致之排放與移除，故選A。委外廢棄物處理、租賃資產、投資等屬間接排放（類別四至五），非直接排放。","idx":56},{"id":"PE-1151-L12-08","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"某企業使用 10,000度的電力，每度電排放係數為 0.5kgCO₂e，以及 1,000公升柴油用於發電機，每公升柴油排放係數為 2.5kgCO₂e。請問該企業上述情境下的類別一、類別二排放量分別為下列何者？","options":{"A":"5tCO₂e，2.5tCO₂e","B":"25tCO₂e，50tCO₂e","C":"0.5tCO₂e，0.25tCO₂e","D":"2.5tCO₂e，5tCO₂e"},"answer":"D","explanation":"外購電力屬類別二：10,000度×0.5 kg＝5,000 kg＝5 tCO2e；柴油用於自設發電機燃燒屬類別一：1,000 L×2.5 kg＝2,500 kg＝2.5 tCO2e。題目詢問類別一、類別二分別為何，故為2.5 tCO2e與5 tCO2e，選D。","idx":57},{"id":"PE-1151-L12-09","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"某工廠進行溫室氣體盤查，發現使用一台冰水機，其冷媒原始填充量為 0.007公噸，GWP 值為 1,136，自然溢散率為 7.4%，請問當年度未重新填充之情境下，其溫室氣體排放量約為多少？","options":{"A":"58.8tCO₂e","B":"0.588tCO₂e","C":"5.88tCO₂e","D":"0.0588tCO₂e"},"answer":"B","explanation":"冷媒自然溢散之排放量＝原始填充量×GWP×溢散率＝0.007公噸×1,136×7.4%≈0.588 tCO2e，故選B。此屬含氟氣體逸散排放之量化，係以逸散質量乘以全球暖化潛勢值換算為二氧化碳當量。","idx":58},{"id":"PE-1151-L12-10","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"若企業採用財務控制權法（Financial Control Approach）界定組織邊界，下列何者正確？","options":{"A":"僅需計入母公司之排放","B":"具有財務控制權之排放皆需納入盤查","C":"與營運控制法相同，不涉及財務決策","D":"該方法僅適用製造業"},"answer":"B","explanation":"財務控制權法指企業有能力主導事業體之財務與營運政策，對具財務控制權之事業體應100%認列其排放與移除，故選B。該方法與營運控制法不同（涉及財務決策主導權），亦非僅計母公司或僅適用製造業。","idx":59},{"id":"PE-1151-L12-11","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"若A公司與 B 公司共同持有一項合資事業，各占 50%，依照環境部要求進行申報，A公司具有營運控制權，則兩家公司的排放量應如何計算？","options":{"A":"A公司與 B 公司各計入 50%排放量","B":"A公司應計入 100%排放量，B 公司不需計入","C":"A公司僅需計入範疇三排放","D":"A公司與 B 公司均不需計入排放"},"answer":"B","explanation":"依環境部要求以營運控制權法彙總，具營運控制權者應100%認列該事業體排放。A公司具營運控制權故計入100%，B公司不具控制權則不計入，故選B。此避免雙方各計50%造成的計算不一致。","idx":60},{"id":"PE-1151-L12-12","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"某工廠將廠房屋頂出租給能源業者設置太陽能板，該太陽能電力全數「售予台電」，工廠並未自用。在設定該工廠的 ISO14064-1：2018盤查邊界時，該太陽能發電量及其減碳效益應如何處理？","options":{"A":"應計入類別 2，並扣抵工廠的用電排放","B":"應計入類別 1，視為自產能源","C":"不屬於該工廠的盤查邊界，不需列入清冊","D":"需列在類別 2，但排放係數設為 0"},"answer":"C","explanation":"太陽能板由能源業者設置、電力全數售予台電，工廠既不具該設備之營運控制權、亦未使用該電力，依ISO 14064-1組織邊界原則不屬工廠盤查邊界，不需列入清冊，故選C。因非自用亦無外購，不計入類別一或類別二，更不得作為減碳抵扣。","idx":61},{"id":"PE-1151-L12-13","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"某汽車租賃公司（出租人）將車輛租給客戶使用。若該租賃公司進行盤查，且不掌握車輛的燃油控制權（由客戶自付），則客戶使用期間的排放，在租賃公司的報告中屬於哪一類？","options":{"A":"類別1：直接排放","B":"類別3：運輸間接排放","C":"類別4：上游租賃資產","D":"類別5：下游租賃資產"},"answer":"D","explanation":"租賃公司為出租人，客戶承租車輛且自付燃油、掌握燃油控制權，該使用期間排放對出租人而言屬下游租賃資產，依分類對應類別五，故選D。因出租人不具控制權故非類別一，承租使用屬下游而非上游租賃資產。","idx":62},{"id":"PE-1151-L12-14","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"企業採購一台射出成型機（資本物品），由設備商負責從國外運送到工廠。試問：（1）射出成型機製造過程的排放、（2）射出成型機運送到工廠的排放，分別屬於 ISO 14064-1：2018 的哪一類？","options":{"A":"皆屬於類別 3","B":"（1）屬於類別 4；（2）屬於類別 3","C":"（1）屬於類別 2；（2）屬於類別 3","D":"皆屬於類別 4"},"answer":"B","explanation":"射出成型機為採購之資本物品（資本財），其製造過程排放屬類別四；設備由設備商運送到廠屬上游運輸，屬類別三，故選B。資本財對應類別四、上游原物料運輸及分配對應類別三。","idx":63},{"id":"PE-1151-L12-15","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"工廠在盤查邊界內建置了太陽能發電設施，電力全數供廠內製程使用（自發自用），未躉售給台電。關於這部分電力的排放邊界界定，下列敘述何者正確？","options":{"A":"屬於類別 1，但因太陽能係數為 0，故排放量為0","B":"屬於類別 2，係數為0","C":"不屬於盤查邊界，因為沒有向外購買","D":"視為碳抵換，可扣減其他排放"},"answer":"A","explanation":"太陽能發電設施位於盤查邊界內且自發自用，屬企業自有能源，歸類別一；惟太陽能發電之排放係數為0，故該部分排放量為0，選A。因屬自產能源而非外購，不列類別二；自用發電亦非對外購電，不能視為碳抵換扣減。","idx":64},{"id":"PE-1151-L12-16","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"某製造商於 113年度燃燒天然氣達8,000 立方公尺，用電量為 120,000kWh。碳排放係數為2.0 公斤CO₂e/立方公尺，電力排放係數為 0.5公斤 CO₂e/kWh。請問該製造商 113年度的總排放量為多少公噸二氧化碳？","options":{"A":"64,000","B":"16,000","C":"76","D":"60"},"answer":"C","explanation":"天然氣：8,000 m³×2.0 kg＝16,000 kg＝16公噸；電力：120,000 kWh×0.5 kg＝60,000 kg＝60公噸。總排放量＝16＋60＝76公噸CO2e，故選C。選項A、B為未換算成公噸之誤導值。","idx":65},{"id":"PE-1151-L12-17","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"根據溫室氣體排放量盤查登錄及查驗管理辦法第四條規定，當以排放係數法計算燃料燃燒產生之排放量，應以燃料用量乘以何者位階熱值及係數?","options":{"A":"高","B":"中","C":"低","D":"均可"},"answer":"C","explanation":"依盤查登錄及查驗管理辦法，以排放係數法計算燃料燃燒排放時，應以燃料用量乘以低位發熱值（低位熱值）及排放係數，故選C。採低位熱值係因高位熱值含水蒸氣潛熱、不代表實際可用熱能，計算排放時須以低位熱值為基準。","idx":66},{"id":"PE-1151-L12-18","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"下列何者為排放係數法的公式？","options":{"A":"排放量=活動數據×排放係數×全球暖化潛勢值","B":"排放量=燃料使用量÷排放係數","C":"排放量=濃度數據×流率×全球暖化潛勢值","D":"排放量=排放源數量÷活動數據"},"answer":"A","explanation":"排放係數法公式為：排放量＝活動數據（如燃料耗用量）×排放係數×全球暖化潛勢值（GWP），將活動數據乘以係數後再以GWP換算為二氧化碳當量，故選A。其餘選項之運算關係與單位皆不符該法定義。","idx":67},{"id":"PE-1151-L12-19","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"進行溫室氣體盤查時，若企業使用生質燃料（如生質柴油、木屑等），依據 IPCC 規範，關於其燃燒產生之二氧化碳（CO₂）排放量，應如何處理？","options":{"A":"屬於自然界循環，完全不需要計算或量化","B":"需量化計算，並直接加總計入公司的總排放量中","C":"需量化計算，但分別表列，不彙總到排放總量中","D":"視為類別 2的間接排放計算"},"answer":"C","explanation":"依IPCC規範，生質燃料燃燒所產生之二氧化碳仍須量化計算，但應個別分開表列，不彙總計入公司總排放量，故選C。此與ISO標準對生物源排放與移除須分別記錄的原則一致；生質CO2並非完全免計，亦非歸為類別二。","idx":68},{"id":"PE-1151-L12-20","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"計算燃料燃燒排放時，若供應商僅提供「高位熱值（HHV）」，依據指引建議的轉換公式，針對「天然氣（氣態燃料）」與「燃油（液態燃料）」的低位熱值（LHV）轉換比例分別為何？","options":{"A":"氣態95%；液態90%","B":"氣態90%；液態95%","C":"皆為90%","D":"皆為95%"},"answer":"B","explanation":"當供應商僅提供高位熱值（HHV）時，依指引建議之轉換，氣態燃料（如天然氣）低位熱值約為高位熱值的90%，液態燃料（如燃油）約為95%，故選B。此係因氣、液態燃料含氫比例與水蒸氣潛熱差異，導致換算比例不同。","idx":69},{"id":"PE-1151-L12-21","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"某工廠整年度分三批次採購燃煤，每批次熱值不同。依據《113年版溫室氣體排放量盤查作業指引》，若要計算全年度的平均熱值以進行排放量計算，應採用下列何種統計方法？","options":{"A":"算術平均法","B":"加權平均法","C":"直接採用數值最大者以保守估計","D":"採用最後一批次的熱值"},"answer":"B","explanation":"分批次採購之燃煤各批熱值不同且數量不一，計算全年平均熱值時應以各批次用量為權重採加權平均法，方能反映實際投入比重，故選B。算術平均忽略用量差異、取最大值或末批熱值皆不具代表性。","idx":70},{"id":"PE-1151-L12-22","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"根據ISO14064-1：2018 之規範，下列何者不屬於 GHG Protocol 的範疇三盤查邊界？","options":{"A":"組織使用產品","B":"運輸","C":"輸入能源","D":"員工通勤"},"answer":"C","explanation":"輸入能源（外購電力、蒸汽等）屬範疇二（能源間接排放），非GHG Protocol範疇三之盤查邊界，故選C。組織使用之產品、運輸、員工通勤均屬範疇三（價值鏈間接排放）項目。","idx":71},{"id":"PE-1151-L12-23","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"關於事業購買再生能源電力，若該筆電力之排放係數以 0計算，則下列敘述何者正確？","options":{"A":"只要購買再生能源憑證（T-REC）即可，形式不拘","B":"憑證類型須為「電證合一」，並檢具轉供證明","C":"憑證類型為「電證分離」","D":"只要向台電申請綠電標章"},"answer":"B","explanation":"事業採購再生能源電力欲以排放係數0計算，其憑證類型須為「電證合一」並檢具轉供證明，確保該度電力實際轉供予該事業使用，故選B。僅憑證不拘、電證分離或僅申請標章，無法確認電力與憑證對應關係，不符扣抵條件。","idx":72},{"id":"PE-1151-L12-24","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"溫室氣體盤查報告書中，下列何者為報告邊界所呈現的內容？","options":{"A":"描述績效追蹤的邊界","B":"描述盤查報告的期間","C":"描述組織的邊界與彙總方法","D":"描述組織所考量的排放類別"},"answer":"D","explanation":"報告邊界之目的在鑑別組織營運相關之排放源與溫室氣體，並以直接與間接共六大類別分類呈現，故報告書中報告邊界呈現的是組織所考量的排放類別，選D。描述盤查範圍涵蓋之廠區屬組織邊界，期間與彙總方法另有章節陳述。","idx":73},{"id":"PE-1151-L12-25","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"在撰寫ISO14064-1盤查報告書時，若因數據無法取得而排除了某些次要排放源。依據指引及 ISO原則，報告書應如何呈現這些排除項目？","options":{"A":"僅在附錄中列出排除項目，不需在報告主體揭露","B":"僅需在清冊中標示\"0\"","C":"應透明陳述排除項目及其理由","D":"需取得環境部同意函"},"answer":"C","explanation":"依ISO原則與指引，因數據無法取得而排除次要排放源時，應於報告中透明陳述排除之項目及其理由，以符合透明度與完整性原則，故選C。僅列附錄、僅標示0或須取得環境部同意函皆非規範要求。","idx":74},{"id":"PE-1151-L12-26","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"若查驗機構完成查證並提出「查驗總結報告」，且查驗過程中發現數據錯誤並已修正，事業在最終定稿的盤查報告書與清冊中，應如何處理數據以符合規範要求？","options":{"A":"保留原始錯誤數據以示誠實","B":"報告書與清冊的數據必須與查驗結果完全一致","C":"報告書寫修正後的數據，清冊保留修正前的數據","D":"僅需修正總量，細項數據不需修正"},"answer":"B","explanation":"查驗過程發現並修正數據後，最終定稿之盤查報告書與排放清冊所載數據必須與查驗結果完全一致，確保申報內容反映經查證確認之正確值，故選B。保留錯誤數據、報告與清冊不一致或僅修正總量皆不符一致性與準確性要求。","idx":75},{"id":"PE-1151-L12-27","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"在報告書的「排放量計算」章節中，針對所引用的排放係數（例如電力係數、 GWP 值），下列哪一項揭露方式不符合指引要求？","options":{"A":"標註係數的發佈單位","B":"標註係數的年份或版本","C":"寫「引用官方係數」或「引用自軟體資料庫」","D":"使用自廠係數，說明檢測方法與日期"},"answer":"C","explanation":"依透明度與可追溯要求，引用排放係數須標註發佈單位、年份或版本，自廠係數須說明檢測方法與日期；僅寫「引用官方係數」或「引用自軟體資料庫」無法追溯來源，不符規範，故選C。","idx":76},{"id":"PE-1151-L12-28","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"若企業在廠區內種植樹木（碳匯），並計算其碳移除量（Removal）。在填寫排放清冊時，這筆移除量應如何處理？","options":{"A":"直接與排放量相減，申報淨排放量","B":"填寫在「直接排放」欄位，並標示為負值","C":"填寫在獨立的「溫室氣體移除量」欄位，不得與排放量相抵扣","D":"視為購買綠電，係數設為 0"},"answer":"C","explanation":"廠區種樹之碳移除量應填寫於獨立的溫室氣體移除量欄位，排放與移除分別量化，不得逕與排放量相抵扣申報淨排放，故選C。直接相減、填入直接排放欄標負值或比照綠電係數設0，皆違反排放與移除分列的原則。","idx":77},{"id":"PE-1151-L12-29","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"企業發生下列哪一種變動時，通常不需要在當年度報告書中重訂基準年或調整歷史數據？","options":{"A":"併購了一家排放量占總量 20%的新工廠","B":"出售了一家排放量占總量 15%的子公司","C":"發現過去使用的排放係數有重大錯誤，誤差> 5%","D":"因產能自然擴增，導致排放量較去年增加 10%"},"answer":"D","explanation":"重訂基準年之情形限於報告邊界或組織結構性變更（併購、撤資）、計算方法或排放係數改變、發現超過顯著性門檻之實質誤差。產能自然擴增導致排放增加屬營運規模變化，非結構性或方法變更，通常不需重訂基準年，故選D。","idx":78},{"id":"PE-1151-L12-30","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"在查核一份盤查報告書時，發現其電力排放係數引用來源僅寫「經濟部能源署」。依據ISO14064-1對於資訊透明度的要求，這樣的描述缺少哪一項關鍵資訊，將導致數據無法追溯？","options":{"A":"係數的計算公式","B":"係數的發佈日期或適用年份","C":"能源署的地址","D":"台電的董事長姓名"},"answer":"B","explanation":"電力排放係數僅註明發佈單位「經濟部能源署」，缺少係數的發佈日期或適用年份，將使數據無法對應特定版本而難以追溯，不符ISO 14064-1透明度要求，故選B。計算公式、單位地址或人員姓名非追溯所必需。","idx":79},{"id":"PE-1151-L12-31","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"關於國內產品碳足跡計算的相關指引，在設定切斷原則時，任何單一溫室氣體源之排放貢獻占產品預期之生命週期內溫室氣體排放量若低於多少百分比，可於盤查時被忽略；且所有被忽略項目的累積不得超過總排放量的多少百分比？","options":{"A":"單一源≤5%；累積不得超過 10%","B":"單一源≤1%；累積不得超過 5%","C":"單一源≤0.5%；累積不得超過 1%","D":"單一源≤10%；累積不得超過 20%"},"answer":"B","explanation":"依國內產品碳足跡切斷（截斷）準則，任何單一溫室氣體源排放貢獻占預期生命週期排放量≦1%者可於盤查時忽略，且所有被忽略項目累積不得超過5%，故選B。即納入評估之排放貢獻至少應達95%。","idx":80},{"id":"PE-1151-L12-32","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"根據《氣候變遷因應法》第三十七條，中央主管機關審查核定產品碳足跡後，業者應於規定期限內依核定內容對產品進行何種標示？","options":{"A":"零碳標示","B":"分級標示","C":"再生能源比例標示","D":"碳中和承諾標示"},"answer":"B","explanation":"依氣候變遷因應法相關規定，中央主管機關審查核定產品碳足跡後，業者應依核定內容對產品進行分級標示（碳足跡減量／分級型標示），故選B。零碳、再生能源比例或碳中和承諾標示非該法定之標示方式。","idx":81},{"id":"PE-1151-L12-33","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"依據ISO14067：2018標準，於進行碳排放數據量化時，若存在需分配的排放源，則下列關於排放分配原則之引用優先順序何者正確？","options":{"A":"物理性分配→經濟分配→無分配","B":"經濟分配→物理性分配→無分配","C":"無分配→經濟分配→物理性分配","D":"無分配→物理性分配→經濟分配"},"answer":"D","explanation":"依ISO 14067分配原則之優先順序，應先盡可能避免分配（無分配，透過次製程細分或系統擴充），無法避免時以反映物理關係之物理性分配，最後才採經濟價值等經濟分配，故選D：無分配→物理性分配→經濟分配。","idx":82},{"id":"PE-1151-L12-34","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"下列何者為使用「排放係數法」計算燃料燃燒所產生之溫室氣體排放量時，所必須具備的數據？","options":{"A":"燃料消耗量與低位熱值","B":"設備的總負荷量","C":"燃料價格與碳稅","D":"溫室氣體排放清冊的類別"},"answer":"A","explanation":"以排放係數法計算燃料燃燒排放，必須具備燃料消耗量（活動數據）與低位熱值，據以乘上排放係數換算排放量，故選A。設備總負荷量、燃料價格與碳稅、清冊類別皆非該計算式的必要輸入數據。","idx":83},{"id":"PE-1151-L12-35","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"關於生命週期評估（Life Cycle Assessment, LCA）的功能單位（Functional Unit, FU），下列何者為其主要目的？","options":{"A":"作為溝通產品外觀特性的指標","B":"作為產品生命週期的量化基準","C":"用於計算公司年度排放量","D":"僅提供使用階段的排放基礎"},"answer":"B","explanation":"功能單位（FU）的主要目的在提供產品系統投入與產出之量化參考基準，使不同產品或服務之環境表現能在共同基準上比較，故選B。它並非溝通產品外觀、計算公司年度排放，亦不限於使用階段。","idx":84},{"id":"PE-1151-L12-36","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"在生命週期衝擊評估（Life Cycle Impact Assessment, LCIA）中，將生命週期盤查（Life Cycle Inventory, LCI）的結果轉化為衝擊指數時，其程序依序為：分類、特徵化，接下來是哪一個步驟？","options":{"A":"決策","B":"替代方案之排序","C":"權重","D":"評價模式及方法"},"answer":"C","explanation":"生命週期衝擊評估（LCIA）將盤查結果轉化為衝擊指數之程序依序為分類、特徵化，接著為正規化／權重（weighting）等步驟，故選C。權重屬將各衝擊類別整合比較的後續程序，而非決策或替代方案排序本身。","idx":85},{"id":"PE-1151-L12-37","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"關於產品碳足跡（Product Carbon Footprint, CFP）或部分CFP 之生命週期衝擊評估（Life Cycle Impact Assessment, LCIA）中，計算產品系統的潛在氣候變遷衝擊時，應採用哪一種時間範圍的全球暖化潛勢？","options":{"A":"20年","B":"50年","C":"100年","D":"200年"},"answer":"C","explanation":"依ISO 14067，於CFP或部分CFP之LCIA計算潛在氣候變遷衝擊時，應採用最新版100年全球暖化潛勢值（GWP-100）乘以各溫室氣體排放或移除質量，故選C。100年時間範圍為國際通用之標準化基準。","idx":86},{"id":"PE-1151-L12-38","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"下列哪一項屬於生命週期評估（Life Cycle Assessment, LCA）的限制？","options":{"A":"無法分析環境衝擊","B":"無法定義產品是否永續","C":"無法使用數據","D":"無法應用於製造業"},"answer":"B","explanation":"生命週期評估（LCA）量化的是產品從原物料到最終處置之環境衝擊，但無法直接判定產品是否永續（永續涉及環境、社會、經濟等多面向價值判斷），故選B為其限制。LCA確能分析環境衝擊、使用數據並應用於製造業。","idx":87},{"id":"PE-1151-L12-39","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"根據ISO14025：2006的規定，產品類別規則（Product Category Rules, PCR）委員會在制定PCR 文件時應收集或製作適當的生命週期評估（Life Cycle Assessment, LCA）以告知其發展過程，此 LCA 的主要作用是？","options":{"A":"確保單一企業內部碳排報告的保密性","B":"決定產品的功能單位應使用何種貨幣","C":"確保特定產品類別內 EPD之間的可比性","D":"規定產品的最終處置方式"},"answer":"C","explanation":"依ISO 14025，PCR委員會制定PCR時收集或製作適當的LCA，其主要作用在確保同一產品類別內各EPD（環境產品宣告）之間具有一致的比較基礎與可比性，故選C。其目的非保密、非決定計價貨幣或規定最終處置方式。","idx":88},{"id":"PE-1151-L12-40","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"下列哪一種溫室氣體不是類別一固定式燃燒源的排放物？","options":{"A":"二氧化碳（CO₂）","B":"甲烷（CH₄）","C":"氧化亞氮（N₂O）","D":"六氟化硫 (SF₆)"},"answer":"D","explanation":"類別一固定式燃燒源之主要排放物為二氧化碳、甲烷與氧化亞氮；六氟化硫（SF6）通常來自電力設備等之逸散排放，非燃料燃燒產物，故選D。選項A、B、C皆為固定燃燒典型溫室氣體。","idx":89},{"id":"PE-1151-L12-41","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L121","stem":"某公司有一部柴油發電機，盤查同時收集到現場的完整柴油使用紀錄、針對該發電機的柴油採購金額、發電機的運轉時間等資料，請問該以下列何者作為活動數據較佳？","options":{"A":"使用現場使用紀錄統計年度實際用量","B":"使用採購金額回推柴油數量","C":"利用運轉時間跟手冊上單位時間耗用量來計算年度用油量","D":"以上皆可"},"answer":"A","explanation":"活動數據應優先採用可直接反映實際用量且可追溯的來源。現場完整柴油使用紀錄為實測／實際統計，準確度與可查證性最高，故選A。以採購金額回推或以運轉時間乘手冊耗油量屬估算，不確定性較高。","idx":90},{"id":"PE-1151-L12-42","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"根據ISO14067：2018的條文更新，當產品碳足跡的量化涉及能源屬性憑證（EACs），在電網相互連接的情況下，若使用不同電力追溯系統可能導致結果差異，應執行並報告哪一種分析結果？","options":{"A":"質量平衡分析","B":"財務審計分析","C":"敏感度分析","D":"總量平衡分析"},"answer":"C","explanation":"依ISO 14067條文更新，當CFP量化涉及能源屬性憑證（EACs）且在電網互連、不同電力追溯系統可能導致結果差異時，應執行並報告敏感度分析以呈現其影響，故選C。質量平衡、財務審計或總量平衡非針對此情形之規定分析。","idx":91},{"id":"PE-1151-L12-43","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"在生命週期評估（Life Cycle Assessment, LCA）中，當進行敏感性分析時，應主要關注哪一類因素？","options":{"A":"關鍵數據的估算假設與不確定性","B":"製程運行順序或工序選擇差異","C":"原物料價格或市場供需波動","D":"產品設計變更對功能性能的影響"},"answer":"A","explanation":"LCA進行敏感性分析時，應主要關注關鍵數據的估算假設與不確定性，檢視其變動對結果重大性的影響，故選A。製程順序、原物料價格波動或產品功能設計變更非敏感性分析所聚焦的資料不確定性因素。","idx":92},{"id":"PE-1151-L12-44","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"根據環境部碳足跡產品類別規則訂定、引用及修訂指引規定，要求在取得環境部文件登錄編號後，產品類別規則（PCR）應在下列何時內制定完成，以提送工作小組審查？","options":{"A":"60個工作天內","B":"3個月內","C":"半年內","D":"一年內"},"answer":"C","explanation":"依環境部碳足跡產品類別規則訂定、引用及修訂指引，取得文件登錄編號後，PCR應於半年內制定完成並提送工作小組審查，故選C。此為程序時限規定，逾期未完成者須依指引另行處理。","idx":93},{"id":"PE-1151-L12-45","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"在生命週期評估（Life Cycle Assessment, LCA）中，下列哪一項資訊於闡釋階段可不用進行說明？","options":{"A":"得採結論與建議的形式給予決策者","B":"闡釋合併盤查分析與衝擊評估的觀察結果","C":"對未來新產品的環境衝擊改變之影響","D":"將盤查分析的觀察結果，與目的及範疇整合一致之階段，以達成結論與建議"},"answer":"C","explanation":"LCA闡釋階段須說明的內容包括：整合盤查分析與衝擊評估之觀察結果、與目的範疇一致之結論與建議，並得以結論建議形式提供決策者。對未來新產品環境衝擊改變之影響非該階段必要說明項目，故選C。","idx":94},{"id":"PE-1151-L12-46","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"下列哪一項產品類型無法向環境部申請取得產品碳足跡標籤？","options":{"A":"矽晶圓片","B":"高鐵服務","C":"百貨禮品","D":"高粱酒"},"answer":"A","explanation":"依官方答案，矽晶圓片無法向環境部申請取得產品碳足跡標籤，故選A。相較之下，高鐵服務、百貨禮品、高粱酒等具可對終端對象溝通之產品／服務範疇，較符合碳足跡標籤之申請條件；本題屬申請適用性之判定，教材未逐項列舉細節。","idx":95},{"id":"PE-1151-L12-47","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"在計算產品碳足跡（Product Carbon Footprint, CFP）時，為何不建議使用組織型碳盤查（GHG）的電力排碳係數？","options":{"A":"GHG 係數僅用於 B2C 產品，不適用 CFP","B":"GHG係數只計算發電過程的排放","C":"CFP 係數只考慮綠色能源，GHG係數考慮所有能源。","D":"CFP 係數由台電提供，GHG係數由環境部提供"},"answer":"B","explanation":"CFP須涵蓋電力之完整生命週期排放，包括上游（燃料開採運輸）、發電過程（含輸配電損耗）及下游（廢棄物處理）排放；組織型碳盤查之電力排碳係數通常僅計發電過程排放，範圍不足，故不建議用於CFP，選B。","idx":96},{"id":"PE-1151-L12-48","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"關於作為碳足跡溝通所需依據 ISO標準，下列何者不正確？","options":{"A":"ISO14044","B":"ISO14068-1","C":"ISO14026","D":"ISO14071"},"answer":"B","explanation":"作為碳足跡溝通依據之ISO標準包括ISO 14044（LCA）、ISO 14026（足跡溝通）、ISO 14071（關鍵性審查）等；ISO 14068-1屬碳中和相關標準，非碳足跡溝通依據，故選B為不正確者。","idx":97},{"id":"PE-1151-L12-49","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"關於依據ISO14067：2018 進行之產品碳足跡（Product Carbon Footprint, CFP）研究報告內容，下列哪一項資訊應於報告中予以「分開描述」？","options":{"A":"預期應用及對象","B":"碳足跡揭露報告摘要","C":"生質碳排放量與移除量","D":"數據品質評估與敏感度分析結果"},"answer":"C","explanation":"依ISO 14067，CFP研究報告中化石與生物源之溫室氣體排放量與移除量應個別分開表示（生質碳排放與移除須分列），故選C應分開描述。預期應用與對象、報告摘要、數據品質與敏感度分析結果則依報告架構一併呈現。","idx":98},{"id":"PE-1151-L12-50","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第一次","unit":"L122","stem":"若產品是持續性的提供，溫室氣體排放評估應涵蓋至少多久期間？","options":{"A":"一季","B":"半年","C":"一年","D":"三年"},"answer":"C","explanation":"當產品係持續性提供時，溫室氣體排放評估應涵蓋至少一年之期間，以反映一個年度內的變化並具代表性，故選C。數據時間界限須考量年度內與各年度間之變化，選取可代表該期間趨勢之數值。","idx":99},{"id":"PE-1152-L11-01","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"依據《聯合國氣候變化綱要公約》（UNFCCC）所揭示之「共同但有區別的責任及各自能力（CBDR-RC）」原則，下列敘述何者正確？","options":{"A":"所有國家均需承擔相同的減排義務","B":"開發中國家需首先實現碳中和目標","C":"考量國家的經濟實力，忽略歷史排放責任","D":"發達國家應率先減排，並支持開發中國家"},"answer":"D","explanation":"依UNFCCC與京都議定書，基於共同但有區別的責任及各自能力(CBDR-RC)原則，已開發國家對歷史累積排放負主要責任，應率先對付氣候變遷並對開發中國家提供資金、技術與能力建構支持，故D正確。A忽略區別責任、C忽略歷史排放責任、B要求開發中國家先達標，均與原則相悖。","idx":100},{"id":"PE-1152-L11-02","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"依據《巴黎協定》規定，關於國家自定貢獻（Nationally Determined Contributions, NDC）之特性，下列敘述何者正確？","options":{"A":"各國首次提交 NDC 後，其減量目標即不得修正，以確保國際氣候治理制度之穩定性","B":"各國可自行決定 NDC 之提交頻率與內容格式，《巴黎協定》並未建立共同規範或要求","C":"各締約方應至少每五年提交一次 NDC，並參考全球盤點結果，逐步提升減量目標之企圖心","D":"NDC 制度主要適用於開發中國家，已開發國家則以提供氣候資金與技術協助為主要義務"},"answer":"C","explanation":"巴黎協定以五年為一週期，各締約方須定期提交國家自定貢獻(NDC)，並參考全球盤點結果使每次更新反映更高企圖心、逐步提升減量目標，故C正確。NDC非提交後不得修正(A錯)，協定確有共同規範(B錯)，且已開發與開發中國家均須提交NDC(D錯)。","idx":101},{"id":"PE-1152-L11-03","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"在 COP28 會議中，關於「加速能源轉型」所提出的具體行動，下列敘述何者正確？","options":{"A":"到2030 年將全球再生能源裝置容量提升至現有的兩倍","B":"到2030 年實現所有國家的能源完全脫碳","C":"實現發電碳密度降低至零，且停止所有核能項目","D":"提高再生能源發電占比，並減少化石燃料補貼"},"answer":"D","explanation":"COP28延續全球加速能源轉型方向，重點在提高再生能源發電占比並逐步減少化石燃料補貼，以推動能源系統有序去碳化，故D最符合。B要求所有國家能源完全脫碳、C要求發電碳密度歸零並停止核能，均過度絕對而不切實際。","idx":102},{"id":"PE-1152-L11-04","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"「巴黎協定」第 6.4條「巴黎協定額度機制（PACM）」終於在亞塞拜然 COP29 中拍板通過。關於本項決議所造成的影響，下列敘述何者不正確？","options":{"A":"將建立一個全球碳市場規範，提升碳權品質與資訊透明度，從而吸引更多國家和企業投入碳交易","B":"要求減量額度必須要符合真實性，保守性（即在計算移除量或減排量時應保守估計避免高估）","C":"不限聯合國會員或《巴黎協定》締約方參與，這為臺灣開出了一扇參與國際碳市場的門","D":"臺灣政府有機會能透過聯合國全球碳市場協助他國減碳，但減排成果不可納入臺灣的國家自定貢獻（NDC）"},"answer":"D","explanation":"COP29拍板巴黎協定第6.4條PACM，建立聯合國層級全球碳市場，強調減量額度之真實性、保守性與避免重複計算，並不限締約方參與，為臺灣開啟參與空間。D為不正確敘述：第6條機制之減量成果在經授權及相應調整後，設計上係可認列於參與方之減量進展，故稱一律不可納入NDC與機制設計不符。","idx":103},{"id":"PE-1152-L11-05","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"COP30 正式決議中提出「全球共作／全球動員（Global Mutirão）」，其意涵最接近下列何者？","options":{"A":"全球共同動員、加速與擴大氣候行動","B":"建立全球一致的碳稅並統一各國環境稅率","C":"全面禁止各國進行碳權買賣與市場交易機制","D":"限制氣候政策僅能由各國官方政府獨自執行"},"answer":"A","explanation":"Global Mutirão一詞源自葡萄牙語社區集體協作之意，COP30以此倡議呼籲全球共同動員、加速並擴大氣候行動，強調跨部門與多方廣泛參與，故A最接近。B統一碳稅、C禁止碳交易、D限政府獨自執行，均與全球共作之廣泛動員精神不符。","idx":104},{"id":"PE-1152-L11-06","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"某大型跨國製造企業 M 為了向投資人展現其氣候風險管理和永續績效，決定編寫一份符合國際標準的永續報告書。下列何種標準組合能最有效地幫助 M 公司達成「向投資人溝通氣候變遷對公司財務的影響」及「揭露行業特定的永續績效指標」這兩個目標？","options":{"A":"TCFD（氣候相關財務揭露）與 GRI（全球報告倡議）","B":"TCFD（氣候相關財務揭露）與 SASB（永續會計準則委員會）","C":"RE100 倡議與 SBTi（科學基礎減量目標倡議）","D":"ISO 14064-1溫室氣體盤查清冊與 ISO 14067產品碳足跡"},"answer":"B","explanation":"向投資人溝通氣候變遷對公司財務之影響宜採TCFD框架(治理、策略、風險管理、指標與目標)；揭露行業特定永續績效指標則SASB以投資人為對象、聚焦財務重大性並提供行業別準則，故B最有效。GRI偏利害關係人與整體永續，RE100/SBTi、ISO盤查標準則屬目標或盤查工具，非資訊揭露組合。","idx":105},{"id":"PE-1152-L11-07","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"根據環境部推動之「抗高溫調適行動路徑」，其規劃包含「兩制度、兩方法、兩拓展」。其中，「兩方法」除「試辦建置抗高溫涼適地圖（Cool Map）」外，另一項為下列何者？","options":{"A":"建立高溫應變啟動機制","B":"舉辦北中南抗高溫行動展","C":"研擬企業抗高溫行動指引","D":"大數據分析強化氣候關懷行動"},"answer":"C","explanation":"環境部抗高溫調適行動路徑以兩制度、兩方法、兩拓展為架構，兩方法除試辦建置抗高溫涼適地圖(Cool Map)外，另一項為研擬企業抗高溫行動指引，協助企業因應高溫風險，故C正確。其餘選項非屬兩方法項目。","idx":106},{"id":"PE-1152-L11-08","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"依據《2024 年中華民國國家溫室氣體排放清冊報告》（統計至 2022年），電力部門仍為臺灣溫室氣體排放的重要來源。此數據對能源轉型的主要啟示為何？","options":{"A":"推動產業節能，即可達成 2050淨零目標，無須調整電力結構","B":"電力部門排放占比較低，因此可延後推動其減碳措施","C":"淨零路徑應以增加化石燃料發電作為主要策略方向","D":"電力系統去碳化為產業與住商部門低碳轉型之關鍵基礎"},"answer":"D","explanation":"依國家溫室氣體排放清冊，電力部門為我國主要排放來源，顯示電力系統去碳化(擴大再生能源、提高零碳電力占比)是帶動產業與住商部門電氣化、低碳轉型的關鍵基礎，故D正確。A忽略電力結構調整、B低估電力占比、C主張增加化石燃料，均與淨零路徑相悖。","idx":107},{"id":"PE-1152-L11-09","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"近年我國因應電力供需型態變化，調整電力系統尖峰與離峰電價時段，其主要驅動因素為何？","options":{"A":"燃煤電廠逐步除役，導致全天供電能力下降","B":"太陽光電占比增加，改變白天與傍晚供電型態","C":"國際燃料價格波動，改變尖離峰時段劃分","D":"核能發電量增加，使夜間供電過剩"},"answer":"B","explanation":"太陽光電裝置容量增加後，白天供電充裕、淨尖峰移至傍晚與夜間，供電型態改變，故需調整尖離峰電價時段以反映實際供需，B為主要驅動因素。燃煤除役、國際燃料價格波動或核能夜間過剩(A、C、D)均非我國調整時段之主因。","idx":108},{"id":"PE-1152-L11-10","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於臺灣能源轉型策略中「電力系統與儲能」戰略，下列何者最符合其核心目標？","options":{"A":"建置分散式能源系統，逐步降低集中式電網之供電比重","B":"提升電網韌性並降低再生能源間歇性對供電穩定造成的衝擊","C":"擴大傳統發電設施容量，以滿足未來整體用電需求","D":"提高跨境電力交易比例，以增加低碳電力供應來源"},"answer":"B","explanation":"電力系統與儲能戰略核心在強化電網韌性、推動電網數位化與擴大儲能，以降低風電、光電等再生能源間歇性對供電穩定之衝擊，故B最符合。該戰略並非降低集中式電網比重、擴大傳統發電容量或以跨境電力交易為主軸(A、C、D)。","idx":109},{"id":"PE-1152-L11-11","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"關於淨零排放（Net Zero Emissions）之概念，下列敘述何者正確？","options":{"A":"淨零排放係指完全消除所有溫室氣體排放，包含技術上或經濟上無法避免之排放亦不得存在","B":"淨零排放係指溫室氣體排放量與透過移除或抵換機制所減除之排放量達成平衡","C":"淨零排放之管理範圍主要以二氧化碳為主，因此甲烷、氧化亞氮等其他溫室氣體通常不納入管理","D":"組織一旦達成淨零排放目標後，即可停止後續之排放盤查、監測及減量管理工作"},"answer":"B","explanation":"淨零排放指特定期間內溫室氣體人為排放量與透過碳匯移除或抵換所減除之量達成平衡，而非完全消除所有排放，故B正確。技術或經濟上不可避免之殘餘排放仍存在(A錯)，管理涵蓋各類溫室氣體而非僅CO2(C錯)，達標後仍須持續盤查、監測與減量管理(D錯)。","idx":110},{"id":"PE-1152-L11-12","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"關於碳市場交易中所稱之「碳排放權（Emission Allowance）」，下列敘述何者正確？","options":{"A":"指各國政府依法對溫室氣體排放行為進行監督與管理之行政權限","B":"指允許國家、企業或組織於一定額度範圍內排放溫室氣體之權利","C":"指於金融市場中交易之衍生性商品，主要用於投資與避險操作","D":"指國際組織針對企業永續發展與 ESG 績效所制定之揭露規範"},"answer":"B","explanation":"碳排放權(排放配額,allowance)指在總量管制下，允許國家、企業或組織於一定額度範圍內排放溫室氣體之權利，可於市場買賣交易，故B正確。它並非政府行政監督權限(A)、金融衍生性商品(C)，亦非ESG揭露規範(D)。","idx":111},{"id":"PE-1152-L11-13","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"下列何項名詞是指將二氧化碳或其他溫室氣體自排放源或大氣中持續移除後，吸收或儲存之樹木、森林、土壤、海洋、地層、設施或場所？","options":{"A":"碳匯","B":"碳權","C":"碳中和","D":"碳封存"},"answer":"A","explanation":"碳匯(sink)指持續將二氧化碳或其他溫室氣體自排放源或大氣中移除後加以吸收、儲存之樹木、森林、土壤、海洋、地層或場所，故A正確。碳權為可交易之減量額度、碳中和為排放與移除達平衡之狀態、碳封存僅指二氧化碳注入地層永久儲存之程序。","idx":112},{"id":"PE-1152-L11-14","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"關於「碳中和」與「淨零排放」差異之描述，下列何者不正確？","options":{"A":"碳中和僅需二氧化碳排放與移除達平衡","B":"淨零排放必須考慮所有的溫室氣體排放","C":"碳中和的抵銷方法可包含種樹等碳移除方式","D":"淨零排放不包含大氣中溫室氣體的移除"},"answer":"D","explanation":"淨零排放係溫室氣體排放量與碳匯(移除)量達成平衡，本就包含大氣中溫室氣體之移除，故D敘述不正確(為應選項)。碳中和多指CO2排放與移除平衡、可用種樹等方式抵銷(A、C正確)，淨零則需考量所有溫室氣體(B正確)。","idx":113},{"id":"PE-1152-L11-15","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"關於「負碳技術（Carbon Negative Technologies）」的判定原則，下列何者正確？","options":{"A":"透過提升能源效率降低溫室氣體排放，即可視為負碳技術","B":"捕集並封存化石燃料燃燒產生的二氧化碳，即可使整體系統達到負碳","C":"從大氣中移除的二氧化碳總量，必須大於系統排放至大氣中的總量","D":"負碳技術只要達到碳中和，即可視為完成負碳目標"},"answer":"C","explanation":"負碳(負排放)技術之判定在於系統自大氣中移除的二氧化碳總量必須大於其排放至大氣的總量，使淨值為負，故C正確。單純提升能效或僅捕集封存化石燃料燃燒之二氧化碳多僅達減量或中和，且達成碳中和亦不等同完成負碳(A、B、D錯)。","idx":114},{"id":"PE-1152-L11-16","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"國際間愈來愈多投資人、金融機構及利害關係人要求企業揭露氣候變遷對財務之影響。企業通常依循下列哪一項國際架構進行氣候相關財務資訊揭露？","options":{"A":"氣候相關財務揭露（TCFD）","B":"碳揭露計畫（CDP）","C":"科學基礎目標倡議（SBTi）","D":"再生能源倡議（RE100）"},"answer":"A","explanation":"企業向投資人與利害關係人揭露氣候變遷對財務之影響，通常依循氣候相關財務揭露(TCFD)架構，以治理、策略、風險管理、指標與目標四核心要素呈現風險與機會，故A正確。CDP為環境數據揭露、SBTi為科學基礎減量目標、RE100為再生能源使用倡議，目的不同。","idx":115},{"id":"PE-1152-L11-17","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"依據《巴黎協議》第六條（Article 6）有關國際轉讓減量成果（Internationally Transferred Mitigation Outcomes, ITMOs）之規範，下列何者屬於 ITMOs運作的核心要求？","options":{"A":"各國可自行認定減量成果，無須進行跨國協調或資訊揭露","B":"減量成果須經參與國家授權，並執行相應調整以避免重複計算","C":"減量成果得由不同國家同時認列，以提升全球減量績效之彈性","D":"國際轉讓之減量成果必須全部來自森林碳匯或其他自然碳吸收措施"},"answer":"B","explanation":"巴黎協定第6條ITMOs之運作核心要求為：減量成果須經參與國家授權，並執行相應調整(corresponding adjustment)以避免重複計算，確保嚴謹性與透明度，故B正確。成果不可由不同國家同時認列(C錯)、須協調與揭露(A錯)，且來源不限森林碳匯等自然吸收(D錯)。","idx":116},{"id":"PE-1152-L11-18","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"根據國際能源總署（International Energy Agency, IEA）2050 淨零排放情境之推估，下列何者為未來全球能源消費的重要趨勢？","options":{"A":"天然氣將取代石油成為化石燃料來源","B":"電力消費占比大幅增加，預計至 2050年成長至近半數","C":"總能源供給量可因為人口成長而持續增加","D":"再生能源的成長會因為核能的普及而停滯"},"answer":"B","explanation":"依IEA 2050淨零排放情境，隨終端部門大規模電氣化，電力於最終能源消費之占比將大幅上升，推估至2050年接近半數，故B正確。天然氣不會取代石油成為主力(A)、總能源供給趨於下降而非持續增加(C)，再生能源為成長主力且不因核能普及而停滯(D)。","idx":117},{"id":"PE-1152-L11-19","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於全球報告倡議組織（Global Reporting Initiative, GRI）報告框架與永續會計準則委員會（Sustainability Accounting Standards Board, SASB）標準之主要差異，下列敘述何者正確？","options":{"A":"GRI提供行業特定的報告標準，而 SASB則是通用標準，適用於所有行業","B":"GRI和SASB 的標準完全一致，只是使用不同的名稱來區分它們的報告框架","C":"GRI注重財務重要性，而 SASB 更關注企業的社會影響和可持續發展","D":"GRI重於企業的整體可持續性表現，而 SASB 專注於財務重要性"},"answer":"D","explanation":"GRI著重企業整體永續表現、採利害關係人導向並涵蓋經濟、環境、社會面；SASB則以投資人為對象、聚焦具財務重大性之行業別議題，故D正確。A將兩者行業/通用角色對調、B稱兩者完全一致、C將財務重要性與社會影響重點對調，均屬錯誤。","idx":118},{"id":"PE-1152-L11-20","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於碳揭露計畫（Carbon Disclosure Project, CDP）問卷設計中，下列何者屬於 CDP 用以支持企業達成淨零排放目標的重要評估方法？","options":{"A":"整合科學基礎減量目標倡議（SBTi），作為評估企業減量目標及排放路徑之重要依據","B":"建立適用於所有產業之統一碳成本核算公式，以作為企業減量績效之主要評估依據","C":"規定所有企業均須優先揭露 Scope 3排放量，並以其作為評等分級之唯一標準","D":"針對高耗能產業設計固定之減排行動方案，要求企業依照標準流程執行減碳措施"},"answer":"A","explanation":"CDP問卷設計整合科學基礎減量目標倡議(SBTi)，以其作為評估企業減量目標與排放路徑是否符合科學基礎之重要依據，支持企業邁向淨零，故A正確。CDP未採統一碳成本公式(B)、未以Scope 3為唯一評等標準(C)，亦非提供固定減排行動方案(D)。","idx":119},{"id":"PE-1152-L11-21","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"下列何者最符合科學基礎減量目標倡議（Science Based Targets initiative, SBTi）對 Scope 3 排放管理之觀點？","options":{"A":"Scope 3 屬間接排放，企業無管理責任","B":"Scope 3 僅包含企業購電造成之排放","C":"Scope 3 可由企業單方面完全控制","D":"Scope 3 涵蓋價值鏈上下游之排放"},"answer":"D","explanation":"SBTi觀點下，Scope 3為價值鏈上下游(採購、運輸、產品使用等)之間接排放，雖非企業直接控制，仍屬企業須納入管理與減量之範圍，故D正確。Scope 3並非無管理責任(A)、不僅限購電排放(屬Scope 2)(B)，亦無法由企業單方面完全控制(C)。","idx":120},{"id":"PE-1152-L11-22","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"氣候相關財務揭露（Task Force on Climate-related Financial Disclosures, TCFD）建議企業應針對氣候風險與機會進行資訊揭露，其核心要素為何？","options":{"A":"溫室氣體盤查、第三方查證、資訊揭露及主管機關登錄","B":"治理、策略、風險管理、指標與目標","C":"能源部門、工業部門、運輸部門及住商部門之減碳管理措施","D":"經濟面、環境面、社會面及公正轉型等永續發展推動面向"},"answer":"B","explanation":"TCFD建議以四大核心要素揭露氣候相關風險與機會，即治理、策略、風險管理、指標與目標，故B正確。A屬溫室氣體盤查查證與登錄流程、C為部門別減碳管理、D為永續發展推動面向，均非TCFD核心要素架構。","idx":121},{"id":"PE-1152-L11-23","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於科學基礎減量目標倡議（Science Based Targets initiative, SBTi）之內容，下列敘述何者正確？","options":{"A":"要求企業僅透過碳抵換（Offset）達成淨零目標，而非進行實質減排","B":"旨在鼓勵企業設定符合《巴黎協定》溫控目標的科學基礎減碳路徑","C":"目標經審核通過後，企業無須再進行定期檢視或更新","D":"適用於跨國大型企業，中小型企業無法申請"},"answer":"B","explanation":"SBTi旨在協助企業設定符合巴黎協定溫控目標(1.5°C)之科學基礎減碳路徑，強調實質減排，故B正確。其非僅靠碳抵換達標(A錯)、目標通過後仍須每五年重新審核更新(C錯)，且另設中小企業版，非僅限跨國大型企業(D錯)。","idx":122},{"id":"PE-1152-L11-24","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於再生能源倡議 RE100之會員加入規範，下列敘述何者正確？","options":{"A":"企業須承諾於 2050 年達成 100%使用再生能源，且核能可納入綠電使用計算","B":"加入之企業需每年至少有 100GWh 的電力需求，且必須以「集團層級」的身分加入","C":"全體已編製永續報告書之上市櫃公司","D":"會員應透過碳揭露計畫（CDP）定期揭露進度，未達目標年度前得免逐年更新再生能源使用情形"},"answer":"B","explanation":"RE100規範要求加入企業每年至少有100GWh再生能源(電力)需求，且原則上須以集團層級身分加入，故B正確。RE100不納入核能(A錯)、並非所有已編永續報告書之上市櫃公司皆為會員(C錯)，且會員須每年報告進度(D錯)。","idx":123},{"id":"PE-1152-L11-25","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"依據國際永續準則理事會（ISSB）發布之國際財務報導準則 IFRS S2《氣候相關揭露》，企業應揭露哪些範疇（Scope）之溫室氣體排放資訊？","options":{"A":"強制揭露 Scope 1","B":"強制揭露 Scope 2","C":"強制揭露 Scope 1 與Scope 2","D":"須揭露Scope 1、Scope 2與Scope 3"},"answer":"D","explanation":"依ISSB發布之IFRS S2氣候相關揭露，企業應揭露Scope 1、Scope 2與Scope 3溫室氣體排放資訊，涵蓋價值鏈排放，故D正確。僅揭露Scope 1、Scope 2或其組合(A、B、C)均不符IFRS S2對完整範疇揭露之要求。","idx":124},{"id":"PE-1152-L11-26","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"在永續發展報告的生態系統中，全球報告倡議組織（Global Reporting Initiative, GRI）、永續會計準則委員會（Sustainability Accounting Standards Board, SASB）及碳揭露計畫（Carbon Disclosure Project, CDP）各自服務於不同的目的和受眾。關於這三個揭露框架及其應用，下列何者不正確？","options":{"A":"CDP 著重氣候與環境數據揭露，常作為投資人與採購機構評估企業氣候行動之依據","B":"GRI提供利害關係人導向框架，涵蓋環境社會治理面向，強調透明度與完整資訊揭露","C":"SASB 以投資人為主要對象，聚焦具財務重大性之永續議題與風險機會之揭露","D":"金融機構因應 SEC 財務重大性要求，應優先採用 GRI並可取代 SASB 與TCFD 以簡化報告"},"answer":"D","explanation":"D為不正確敘述：GRI、SASB、TCFD目的與對象不同，不宜以GRI取代SASB與TCFD；金融機構因財務重大性需求應採以投資人為對象之SASB、TCFD(或接手之ISSB)框架。A(CDP作投資與採購評估依據)、B(GRI利害關係人導向)、C(SASB聚焦財務重大性)之定位描述均正確。","idx":125},{"id":"PE-1152-L11-27","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"歐盟碳邊境調整機制（Carbon Border Adjustment Mechanism, CBAM）的主要目的為何？","options":{"A":"鼓勵歐盟企業將工廠轉移至境外的國家","B":"防止碳洩漏，並維護全球貿易的公平競爭環境","C":"降低歐盟境內企業的溫室氣體排放費用","D":"完全禁止高碳排產品進入歐盟的消費端"},"answer":"B","explanation":"CBAM主要目的在防止碳洩漏(產業為規避碳成本而外移至管制寬鬆國家)，使進口產品承擔與歐盟境內相當之碳成本，維護全球貿易公平競爭環境，故B正確。CBAM非鼓勵工廠外移(A)、非降低歐盟企業排放費用(C)，亦非全面禁止高碳排產品進入(D)。","idx":126},{"id":"PE-1152-L11-28","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於歐盟碳邊境調整機制（Carbon Border Adjustment Mechanism, CBAM）之申報要求，下列何者正確？","options":{"A":"進口商應於相關報關文件中申報符合之豁免或適用資格","B":"出口商應於產品規格文件中揭露碳權交易紀錄","C":"製造商應於環境影響評估文件中完成 CBAM申報","D":"供應商應於能源管理系統文件中聲明適用條件"},"answer":"A","explanation":"CBAM下負申報義務者為進口商(授權申報人)，應於相關報關/申報文件中申報進口產品之內含排放量及符合之豁免或適用資格，故A正確。申報主體為進口商，而非由出口商、製造商或供應商於產品規格、環評或能源管理文件中辦理(B、C、D)。","idx":127},{"id":"PE-1152-L11-29","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"在歐盟碳邊境調整機制（Carbon Border Adjustment Mechanism, CBAM）的規定中，每張 CBAM 憑證等同多少碳排放量？","options":{"A":"一公噸產品於生產過程所產生的直接碳排放量","B":"一公噸二氧化碳當量之碳排放量","C":"一公噸產品生命週期碳足跡所對應之排放量","D":"一公噸產品於歐盟境內運輸所產生之碳排放量"},"answer":"B","explanation":"依CBAM規定，每張CBAM憑證等同一公噸二氧化碳當量(CO2e)之碳排放量，進口商須繳交足以抵銷前一年進口產品內含排放量之憑證，故B正確。憑證以CO2e計量，而非以產品生產直接排放、生命週期足跡或境內運輸排放為單位(A、C、D)。","idx":128},{"id":"PE-1152-L11-30","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於歐盟碳邊境調整機制（Carbon Border Adjustment Mechanism, CBAM）排放量計算原則，下列敘述何者不正確？","options":{"A":"CBAM 排放量需考慮製程中的直接排放和電力消費的間接排放","B":"對於複雜產品之排放量計算，CBAM 對預設值的使用比例設有限制，例如過渡期最高不得超過 20%","C":"產品排放量計算僅需考慮生產設施內之燃料燃燒排放，不需納入外部能源供應相關排放","D":"CBAM 監測與申報制度並未要求企業直接依循 ISO 14064-1或ISO 14067，而係依據歐盟所制定之專屬計算方法辦理"},"answer":"C","explanation":"C為不正確敘述：CBAM產品排放量須納入電力等外部能源消費之間接排放，不可僅計生產設施內之燃料燃燒直接排放。CBAM須同時考量直接與間接排放(A)、對預設值使用設有比例限制(B)，並依歐盟專屬計算方法而非逕依ISO 14064-1或14067(D)，均屬正確。","idx":129},{"id":"PE-1152-L11-31","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"依據歐盟碳邊境調整機制（Carbon Border Adjustment Mechanism, CBAM）規定，在計算複雜產品之內含排放量時，若其使用之「前驅物（Precursors）」係來自歐盟境內或 CBAM 豁免國家，則該前驅物之排放量應如何處理？","options":{"A":"計算該設施的實際排放量","B":"使用該國家的預設值","C":"視為零排放","D":"按全球平均值計算"},"answer":"C","explanation":"依CBAM，計算複雜產品內含排放時，若所用前驅物(precursors)來自歐盟境內或CBAM豁免國家，因其已受歐盟碳定價或等效規範涵蓋，該前驅物排放視為零排放處理，故C正確，以避免重複課徵。非採實際排放、預設值或全球平均值計算(A、B、D)。","idx":130},{"id":"PE-1152-L11-32","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"某鋼鐵產品出口至歐盟，生產過程使用外部供應之電力與蒸汽。關於歐盟碳邊境調整機制（Carbon Border Adjustment Mechanism, CBAM）嵌入排放計算原則，下列敘述何者正確？","options":{"A":"僅計算廠內燃料燃燒造成之直接排放","B":"外部能源排放皆不屬於產品排放範圍","C":"應依規定納入相關能源造成之排放","D":"僅需申報原料階段之排放量"},"answer":"C","explanation":"鋼鐵等產品生產使用外部供應之電力與蒸汽時，依CBAM嵌入排放計算須將相關能源所造成之間接排放一併納入，故C正確。不可僅計廠內燃料燃燒之直接排放(A)、不可將外部能源排放全數排除(B)，亦非僅申報原料階段排放量(D)。","idx":131},{"id":"PE-1152-L11-33","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於我國推動能源效率提升政策之作法，下列何者最符合現行推動方向？","options":{"A":"推動高效率空調、照明與設備","B":"增加所有電價補貼","C":"提高能源使用總量，以維持產業競爭力與經濟成長","D":"優先增加能源供給能力，取代各項節能改善措施"},"answer":"A","explanation":"我國能源效率提升政策方向在推動高效率空調、照明與設備，並透過經濟誘因、教育輔導與強制法規加速高效設備市場滲透，故A正確。增加電價補貼、提高能源使用總量或優先增加供給以取代節能改善(B、C、D)均與節能戰略方向相悖。","idx":132},{"id":"PE-1152-L11-34","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於我國 2050 淨零排放路徑之能源轉型方向，下列何者正確？","options":{"A":"降低高碳能源依賴，擴大再生能源應用，並發展低碳新興能源","B":"提高天然氣使用占比，延後再生能源建置，逐步推動能源轉型","C":"維持既有能源結構配置，透過提升供電能力達成減碳目標","D":"集中發展單一替代能源，藉以取代多元能源轉型策略"},"answer":"A","explanation":"我國2050淨零路徑能源轉型方向為降低高碳(化石)能源依賴、極大化擴大再生能源應用，並發展氫能等低碳新興能源，故A正確。提高天然氣占比並延後再生能源、維持既有能源結構或集中發展單一替代能源(B、C、D)均不符多元能源轉型策略。","idx":133},{"id":"PE-1152-L11-35","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於我國 2050 淨零轉型中的「社會轉型」，最核心的目標為何？","options":{"A":"增加執法單位強制取締排碳者的權力與罰則","B":"確保轉型過程中「公正轉型」，不遺落任何人","C":"推動產業低碳製程，提升企業減碳技術與競爭力","D":"建立智慧電網系統，提高整體能源使用效率"},"answer":"B","explanation":"2050淨零轉型之社會轉型最核心目標為確保公正轉型，以盡力不遺落任何人為原則，兼顧政策目標平衡性、社會分配公正性與利害關係包容性，故B正確。強制取締排碳(A)、產業低碳製程(C)、智慧電網(D)分屬治理、產業或能源面向，非社會轉型核心。","idx":134},{"id":"PE-1152-L11-36","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於「氫能」在我國 2050淨零路徑中的定位，下列敘述何者不正確？","options":{"A":"為12項關鍵戰略之一，規劃應用於工業高溫製程與重型運輸","B":"包含發展氨能發電技術，以作為氫能應用的一環","C":"臺灣現階段之燃氣發電機組已全面完成 20%氫氣混燒之商業化運轉","D":"規劃包含建立進口氫能接收與儲存之基礎設施"},"answer":"C","explanation":"C為不正確敘述：我國氫能仍在發展階段，燃氣機組氫氣混燒尚屬研發示範，並未全面完成20%混燒之商業化運轉。氫能為十二項關鍵戰略之一，規劃應用於工業高溫製程與重型運輸、含氨能發電，並建立進口氫能接收與儲存基礎設施(A、B、D正確)。","idx":135},{"id":"PE-1152-L11-37","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"國家發展委員會推動我國「2050淨零轉型」路徑中，積極倡導數位轉型與綠色轉型的「雙軸轉型」。關於數位技術如何賦能（Enable）並輔助企業與政府進行減碳，下列敘述何者不正確？","options":{"A":"透過物聯網（IoT）與智慧感測器，能即時收集製程能耗數據，建立碳盤查與碳足跡的數位化管理系統","B":"利用人工智慧（AI）與大數據分析，可優化供應鏈物流排程與建築能源管理系統（BEMS），達到節能減碳","C":"數位轉型雖能提升能源管理效率，但數位設備本身（如資料中心）的能耗，在政策上不需納入溫室氣體盤查邊界","D":"引進數位雙生（Digital Twin）技術，可在虛擬環境中模擬製程改良，減少實體試錯過程中的能源與資源浪費"},"answer":"C","explanation":"C為不正確敘述：資料中心等數位設備本身之能耗仍屬組織營運產生之排放，應納入溫室氣體盤查邊界管理，不能免除。以IoT感測建立碳盤查數位系統、以AI大數據優化物流與建築能源管理、導入數位雙生模擬減少試錯(A、B、D)皆為數位賦能減碳之正確作法。","idx":136},{"id":"PE-1152-L11-38","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L111","stem":"下列哪一選項最能描述碳洩漏（Carbon Leakage）之現象？","options":{"A":"因環保技術不足或能源轉型緩慢，導致整體減碳成效不佳","B":"產業因溫室氣體管制成本增加，而轉移至管制較寬鬆之國家","C":"因無法即時導入先進技術，致使企業碳排放難以有效降低","D":"國內企業污染排放量完全控制在低水準，而使碳排放增加"},"answer":"B","explanation":"碳洩漏指因實施溫室氣體管制及碳定價使產業管制成本增加，導致生產活動外移至管制較寬鬆之國家，再輸入受管制國，反而增加全球或區域排碳量之現象，故B正確。A為整體減碳成效、C為技術導入問題、D描述均與碳洩漏定義不符。","idx":137},{"id":"PE-1152-L11-39","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於「碳信用額度（Carbon Credit）」核發之品質要求，下列何者不屬於其核心評估原則？","options":{"A":"市場流動性","B":"避免重複計算","C":"排放減量之真實性","D":"減量成果之外加性"},"answer":"A","explanation":"碳信用額度核發之核心品質原則包括排放減量之真實性、外加性及避免重複計算(另含可量化、可查證、永久性等)。市場流動性屬交易市場之特性，並非碳權品質之核心評估原則，故A為不屬於者(應選)。","idx":138},{"id":"PE-1152-L11-40","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"企業進行碳資產與碳管理評估時，導入內部碳價（Internal Carbon Pricing, ICP）的主要目的為何？","options":{"A":"增加碳權交易收益","B":"將碳成本納入投資決策","C":"取代企業減碳目標設定","D":"降低政府法規要求"},"answer":"B","explanation":"導入內部碳價(ICP)之主要目的在將碳排放之外部成本內部化，使企業於投資與營運決策中納入碳成本考量，引導減碳及低碳技術投資，故B正確。其非為增加碳權交易收益、取代企業減碳目標設定，亦非降低政府法規要求(A、C、D)。","idx":139},{"id":"PE-1152-L11-41","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於「碳信用額度（Carbon Credit）」抵換機制之運作，下列敘述何者符合其核心概念？","options":{"A":"碳信用額度是指企業透過購買他人的排放配額（Allowance），來增加自身法定的排放上限","B":"碳信用額度須代表具「外加性」之減量或移除成果，並經量化及第三方查證","C":"所有的碳信用額度皆具有相同的法律效力，國際自願市場的碳權一定可以用於抵減國家碳稅","D":"碳信用額度僅能透過植樹造林產生，建築能效提升或製程改善等活動絕對無法轉化為碳權"},"answer":"B","explanation":"碳信用額度(碳權)須代表具外加性之實際減量或移除成果，並經量化及第三方查證、於登錄處註冊以避免重複計算，故B符合核心概念。碳權非用以提高自身法定排放上限(A)、不同機制法律效力與用途不一(C錯)，且減量來源不限植樹造林(D錯)。","idx":140},{"id":"PE-1152-L11-42","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於我國《氣候變遷因應法》中「碳費」徵收之規定，下列何者正確？","options":{"A":"碳費徵收對象依產業部門別分階段開徵，依序涵蓋服務、製造及運輸等部門","B":"碳費收入應全數繳入國庫，作為一般公共支出用途","C":"事業提出自主減量計畫並達成目標者，得申請適用優惠費率","D":"碳費之徵收與管理由經濟部能源主管機關負責執行"},"answer":"C","explanation":"依氣候變遷因應法，碳費由環境部徵收並專款專用於減碳相關用途；徵收對象提出自主減量計畫並達成指定目標者，得申請適用優惠費率，故C正確。碳費非全數繳入國庫作一般支出(B錯)，主管機關為環境部而非經濟部能源單位(D錯)。","idx":141},{"id":"PE-1152-L11-43","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於臺灣碳權交易所（Taiwan Carbon Solution Exchange, TCX）之功能，下列敘述何者最符合現階段之政策定位？","options":{"A":"負責辦理國內企業溫室氣體盤查、查驗及查證結果之審核與證書核發作業","B":"提供國內碳權額度及國際高品質碳權之交易撮合平台","C":"規定所有上市櫃公司均須定期進場交易碳權，以履行企業法定減碳責任","D":"受環境部委託辦理碳費徵收、收入管理及相關費用分配等行政業務"},"answer":"B","explanation":"臺灣碳權交易所現階段政策定位在建置交易平台，提供國內減量額度及國際高品質碳權之交易撮合服務，創造企業減碳誘因，故B正確。其不負責盤查查驗查證之審核發證(A)、未強制所有上市櫃公司進場交易(C)，碳費徵收與管理亦由環境部辦理(D)。","idx":142},{"id":"PE-1152-L11-44","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"關於 ISO 14064-1與ISO 14068-1之關係，下列敘述何者正確？","options":{"A":"ISO 14064-1用於量化組織溫室氣體排放，ISO 14068-1用於規範碳中和之實施要求","B":"ISO 14064-1用於執行碳抵換作業，ISO 14068-1用於能源效率評估","C":"ISO 14064-1用於產品碳足跡計算，ISO 14068-1用於規範碳中和之實施要求","D":"ISO 14064-1用於碳權交易管理，ISO 14068-1用於能源效率評估"},"answer":"A","explanation":"ISO 14064-1用於組織層級溫室氣體排放與移除之量化及報告，ISO 14068-1則規範碳中和之實施原則與要求(並以14064-1及14067為盤查數據來源)，故A正確。兩者分屬盤查與碳中和標準，非碳抵換作業、產品碳足跡或能源效率/碳權交易用途(B、C、D)。","idx":143},{"id":"PE-1152-L11-45","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"企業購買再生能源憑證（如 T-REC）後，主要可用於下列何項碳管理用途？","options":{"A":"消除所有產品排放","B":"降低所有直接排放","C":"取代能源效率改善","D":"認列再生能源抵減量"},"answer":"D","explanation":"企業購買再生能源憑證(如T-REC)後，主要用於認列再生能源使用之抵減量，以降低範疇二(外購電力)之間接排放並支持RE100等綠電目標，故D正確。憑證無法消除所有產品排放、降低所有直接排放，也不能取代能源效率改善(A、B、C)。","idx":144},{"id":"PE-1152-L11-46","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"依據 ISO 14068-1：2023，為何2020 年以前產生的碳權不被推薦使用？","options":{"A":"該碳權之適用範圍有限，僅可用於特定排放類別","B":"該碳權供給充足，因此無需優先使用","C":"碳權品質可能不佳且距離使用年度超過五年","D":"該碳權市場價格較高，導致使用成本增加"},"answer":"C","explanation":"依ISO 14068-1:2023，2020年以前產生之碳權因品質可能不佳，且其減量發生年度距使用年度已超過五年、時效性不足，故不被推薦使用，C正確。其與適用範圍受限、供給充足或市場價格高低(A、B、D)無關。","idx":145},{"id":"PE-1152-L11-47","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"在執行碳中和管理計畫過程中，下列何者屬於「即使完成碳中和宣告，仍不會因此改變之數據」？","options":{"A":"溫室氣體盤查之結果數據","B":"企業核發之碳信用額度","C":"碳抵換額度之計算結果","D":"企業財務與經濟效益之報告"},"answer":"A","explanation":"溫室氣體盤查所得之排放量結果數據反映實際排放事實，不因完成碳中和宣告而改變，故A正確。碳中和係就剩餘排放進行抵換，企業核發之碳信用、碳抵換額度計算或財務與經濟效益報告(B、C、D)則會隨抵換與管理作為而變動。","idx":146},{"id":"PE-1152-L11-48","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"某企業欲宣告碳中和，根據 ISO 14068-1，下列哪項做法最有可能不符合標準要求？","options":{"A":"全面以碳權抵換達成碳中和","B":"同時減少 Scope 1 與Scope 2排放","C":"將碳中和計畫書與年度永續報告書同步對外公開透明","D":"完成減量規劃後，就剩餘排放採用符合要求之碳權抵換"},"answer":"A","explanation":"依ISO 14068-1，碳中和須採分層方法，優先進行價值鏈內實質減排與加強移除，僅就無法避免之剩餘排放採用符合要求之碳權抵換。全面以碳權抵換達成碳中和(A)忽略優先減排原則，最可能不符標準要求，故選A。同時減Scope 1與2、資訊公開透明、先減量後抵剩餘(B、C、D)均符合。","idx":147},{"id":"PE-1152-L11-49","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"某電子商務公司擬針對其「快遞服務」宣告碳中和。根據 ISO 14068-1，關於其邊界設定，下列何者正確？","options":{"A":"僅需包含該公司自有辦公室與自有物流車輛之 Scope 1與 Scope 2排放量","B":"考量到數據獲取困難，所有委外第三方物流車隊產生之排放量應一律排除","C":"應包含該快遞服務從收件、運輸、集貨至交付給客戶之完整生命週期內顯著的排放量","D":"只要該公司已達成「組織型」碳中和，則其旗下所有服務自動視為達成邊界設定"},"answer":"C","explanation":"依ISO 14068-1，針對快遞服務此一產品/服務宣告碳中和時，邊界應涵蓋該服務自收件、運輸、集貨至交付客戶之完整生命週期內顯著排放量，含委外第三方物流之顯著排放，故C正確。僅計自有Scope 1、2(A)、一律排除委外(B)或沿用組織型結果(D)均不符合。","idx":148},{"id":"PE-1152-L11-50","source":"past_exam","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":"115年第二次","unit":"L112","stem":"依據 ISO 14068-1有關碳中和之要求，組織於使用碳權進行抵換時，須確認碳權具備「外加性（Additionality）」。下列何者最符合外加性之意涵？","options":{"A":"該減量專案必須屬於法規強制執行事項，以確保其執行過程符合相關法令要求","B":"該減量專案必須是因為缺乏碳權機制的財務支持下發生","C":"外加性是指該專案在原有的減量目標之外，又多增加了 1～1.5倍的植樹數量","D":"係指該碳權額度可以在多個不同的國際平台重複賣出，增加市場流動性"},"answer":"B","explanation":"外加性(additionality)指該減量專案若無碳權機制(碳權收益)之財務支持即不會發生，亦即其減量係額外、並非法規強制或原本即會進行者，故B最符合。減量專案若屬法規強制事項(A)則不具外加性，C以植樹倍數、D以重複賣出描述外加性亦屬錯誤。","idx":149},{"id":"PE-1152-L12-01","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"依據《溫室氣體排放量盤查登錄及查驗管理辦法》，下列何者最符合盤查、登錄及查驗三者之關係？","options":{"A":"查驗完成後，即可免辦盤查、登錄及後續申報","B":"完成盤查登錄程序後，即視為完成查驗作業","C":"盤查、登錄及查驗均有法定程序，應依法辦理","D":"查驗制度僅適用產品碳足跡，不適用組織盤查作業"},"answer":"C","explanation":"依氣候變遷因應法授權訂定的盤查登錄及查驗管理辦法，盤查、登錄與查驗分屬不同法定作業，各有程序與時程要求，事業應依法逐項辦理，三者不可互相取代。故C正確。查驗完成不能免除盤查登錄申報(A)，完成登錄亦不等於完成查驗(B)，且查驗制度適用於組織型盤查而非僅限產品碳足跡(D)。","idx":150},{"id":"PE-1152-L12-02","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"組織型溫室氣體盤查在排放量計算中，下列哪一項屬於「活動數據」？","options":{"A":"全球暖化潛勢（GWP）","B":"碳排放量","C":"燃料使用量","D":"地區電力排放係數"},"answer":"C","explanation":"依排放係數法公式：溫室氣體排放量＝活動數據(燃料耗用量)×排放係數×GWP。燃料使用量屬反映實際營運活動的活動數據，故C正確。GWP(A)是將各氣體換算為二氧化碳當量的係數，電力排放係數(D)為排放係數，碳排放量(B)則是計算結果，皆非活動數據。","idx":151},{"id":"PE-1152-L12-03","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"某公司完成 2025年度溫室氣體盤查，排放量經計算為 18,625.56743tCO₂e。依規定登錄時，應填列為何？","options":{"A":"18,625.56tCO₂e","B":"18,625.567tCO₂e","C":"18,625.5675tCO₂e","D":"18,626tCO₂e"},"answer":"B","explanation":"依溫室氣體排放量盤查登錄相關規定，排放量登錄數值應取至小數點後三位，故18,625.56743應填列為18,625.567tCO₂e，B正確。A取兩位、C取四位、D取整數均不符登錄位數規定。(註：登錄小數位數為辦法程序性規定，教材未逐條列明，係依現行登錄作業規範。)","idx":152},{"id":"PE-1152-L12-04","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"進行組織型溫室氣體盤查時，若燃料使用量缺乏直接量測數據，而企業須採用估算方式取得活動數據，下列何者最符合資料品質管理原則？","options":{"A":"當無法取得實際量測數據時，可採用未具明確來源之估計值，以完成排放量計算權","B":"使用上游供應商提供的預估量","C":"使用能反映實際活動的替代性數據並說明假設","D":"引用同業或同產業之平均數據，以確保與其他企業之盤查結果具有一致性"},"answer":"C","explanation":"資料品質管理要求數據具代表性、可追溯且透明。當缺乏直接量測時，宜採用能反映實際活動的替代性數據並明確說明所採假設與方法，C正確。採用無明確來源之估計值(A)違反可追溯與透明原則，上游預估量(B)未必反映實際使用，同業平均值(D)不能代表該組織實際活動。","idx":153},{"id":"PE-1152-L12-05","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"某上市櫃公司僅受金管會永續資訊揭露規範，其組織邊界設定方式應如何選擇？","options":{"A":"須使用營運控制權法","B":"須使用股權比例分攤","C":"須使用財務控制權法","D":"營運控制權法或股權比例法皆可"},"answer":"D","explanation":"依教材，金管會對盤查邊界僅要求與財務報表一致並維持內部統計方法一致，並未強制規定須採財務控制法、營運控制法或股權持分法中特定一種，企業得依自身情況選擇。故D(營運控制權法或股權比例法皆可)最適當，A、B、C將方法限定為單一法皆不符。","idx":154},{"id":"PE-1152-L12-06","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"在組織推動溫室氣體盤查的實務流程中，通常首先由高階主管指派盤查推動小組，而非直接由工程師進行排放量計算，其主要原因為何？","options":{"A":"工程技術人員通常僅具備設備操作經驗，未必具備完整之溫室氣體盤查專業知識","B":"溫室氣體盤查涉及多部門之活動數據蒐集，須透過高階主管支持以促進跨部門合作","C":"高階主管須親自參與各項活動數據計算，以確保最終盤查結果之正確性與完整性","D":"現行法規規定溫室氣體盤查工作僅能由管理階層執行，工程技術人員不得參與相關作業"},"answer":"B","explanation":"盤查需跨部門整合各單位的能源與活動數據，故理想做法是先由高階主管承諾並成立推動小組，透過其支持促進跨部門合作與資源分配，B正確。此屬組織運作與授權考量，而非工程師專業不足(A)，高階主管不必親自計算(C)，法規亦未限定僅管理階層得執行(D)。","idx":155},{"id":"PE-1152-L12-07","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"關於事業執行溫室氣體排放量盤查的六步驟作業流程（1.盤查資料保存、2.邊界設定、3.數據品質管理、4.排放源鑑別、5.排放量清冊及盤查報告書、6.排放量計算），下列何者為正確之盤查執行程序？","options":{"A":"243651","B":"246315","C":"231465","D":"234561"},"answer":"B","explanation":"依教材口訣「邊→源→算→報→查」，正確順序為：邊界設定(2)→排放源鑑別(4)→排放量計算(6)→數據品質管理(3)→排放量清冊及盤查報告書(5)→盤查資料保存(1)，即246315，故B正確。先界定邊界與排放源才能計算並彙整報告，最後保存資料。","idx":156},{"id":"PE-1152-L12-08","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"關於金管會（永續報告書）與環境部（氣候變遷因應法列管事業）對溫室氣體盤查邊界之要求，下列敘述何者正確？","options":{"A":"環境部要求必須涵蓋海外子公司，而金管會限於國內單一場址","B":"金管會看財報邊界，環境部以登記範圍為準","C":"兩者皆強制要求必須採用「財務控制法」來設定邊界","D":"環境部規範的邊界大於金管會規範的財務報表邊界"},"answer":"B","explanation":"依教材，金管會要求盤查邊界與財務報表邊界保持一致(看財報邊界)，環境部納管事業則以核發管制編號所規範的設置、登記範圍為基準，故B正確。兩機關未強制同採財務控制法(C)，邊界大小依個案而定而非必然環境部大於金管會(D)，A的國內外範圍敘述亦不符規定。","idx":157},{"id":"PE-1152-L12-09","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"依據環境部溫室氣體排放量盤查登錄相關規定，下圖中各單位均具有圖示所示之登記資格，應劃分為幾個不同的盤查邊界？ 圖示：○○大學校本部內含綜合教學大樓、○○大學附設醫院（具醫事機構代碼），以及便利商店（具公司／商業登記）。","options":{"A":"1個","B":"2個","C":"3個","D":"4個"},"answer":"C","explanation":"盤查邊界以主管機關核准的登記資格為準，具獨立登記者應各自劃設。校本部(含綜合教學大樓)、附設醫院(具醫事機構代碼)與便利商店(具公司／商業登記)三者各具不同登記資格，應劃分為3個不同盤查邊界，故C正確。","idx":158},{"id":"PE-1152-L12-10","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"組織採用「股權比例法」設定溫室氣體盤查邊界時，對於合資企業（Joint Venture）之排放量，應如何認列？","options":{"A":"不包括合資企業的排放量","B":"僅包括合資企業的 Scope 1和Scope 2排放量","C":"按照股權比例分攤合資企業的排放量","D":"必須全部納入報告範疇"},"answer":"C","explanation":"股權持分法係依公司對各事業體所持股權比例認列其溫室氣體排放量與移除量，故對合資企業應按股權比例分攤其排放量，C正確。不納入(A)、全部納入(D)皆非比例認列，且股權持分法並非僅限範疇一、二(B)。","idx":159},{"id":"PE-1152-L12-11","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"依據 ISO 14064-1：2018 規定，組織若採用「財務控制權法」設定組織邊界，下列何者應納入溫室氣體盤查範圍？","options":{"A":"由組織負責營運管理與決策，但未具財務控制權且未納入合併報表之子公司","B":"組織持股比例雖不高，但因具財務控制權而須納入合併財務報表之子公司","C":"所有承包商、委外廠商及供應鏈上下游活動所產生之排放，均須納入組織邊界","D":"僅限由組織持有 100%股權且完全擁有之子公司，始須納入溫室氣體盤查"},"answer":"B","explanation":"依ISO 14064-1，財務控制權法指組織有能力主導事業體的財務與營運政策即具財務控制，應100%認列其排放。故雖持股不高但具財務控制權而須納入合併財務報表之子公司應納入，B正確。負營運決策但未具財務控制且未併表者(A)、供應鏈上下游(C)及僅限100%持股(D)均不符財務控制權法判定。","idx":160},{"id":"PE-1152-L12-12","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"某工業園區同一地址內，同時登記有「甲公司」與「乙公司」兩家不同工廠登記證。甲公司進行環境部列管事業溫室氣體盤查時，發現廠區內一座廢水處理場位於甲公司地理圍牆範圍內，但由甲、乙兩家公司共同持有與使用。依據相關盤查指引，甲公司應如何設定盤查邊界？","options":{"A":"因共用設施位於甲公司圍牆範圍內，故乙公司於該廠區所產生之所有排放均應納入甲公司盤查","B":"應依工廠登記證界定盤查邊界，無法區分時應依協議或持分比例分攤排放","C":"共用設施之排放歸屬不易界定，因此甲公司僅需盤查自有辦公室及生產設備之排放即可","D":"因兩家公司共同使用同一廢水處理設施，故應由甲、乙兩家公司合併申報並視為單一排放源管理"},"answer":"B","explanation":"盤查邊界應以主管機關核准的設置、登記範圍為基準，故同址不同工廠登記證應各依其工廠登記證界定邊界；對共用設施無法明確區分歸屬時，應依雙方協議或持分比例分攤排放，B正確。全數歸甲(A)、僅盤自有設備(C)或合併為單一排放源申報(D)均不符登記範圍界定原則。","idx":161},{"id":"PE-1152-L12-13","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"某石化廠將廠內廢水處理設施及其操作人員全權委由專業環保公司管理，但該設施位於石化廠圍牆內，產權仍屬石化廠，且水電費亦由石化廠支付。若石化廠採用「營運控制權法」設定組織邊界，則該廢水處理場產生之甲烷（CH₄）逸散排放應如何界定？","options":{"A":"應列為石化廠之類別一排放，因為石化廠擁有營運控制權且承擔營運風險","B":"應列為環保公司之類別一排放，而石化廠則列為類別四之間接排放","C":"應列為石化廠之類別五排放，視為委外處理營運廢棄物所產生之排放","D":"應由石化廠與環保公司共同認列，並分別列入雙方之類別三排放"},"answer":"A","explanation":"營運控制權法下，具完全權力主導並承擔營運風險者應100%認列該設施排放。本案設施位於石化廠圍牆內、產權屬石化廠且水電費由其支付，石化廠具營運控制權，故廢水處理場甲烷逸散應列為石化廠之類別一(直接)排放，A正確，與是否委外操作無關。","idx":162},{"id":"PE-1152-L12-14","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"根據溫室氣體盤查指引，若百貨公司或鐵路車站之盤查邊界內設有進駐餐廳或商店，且該進駐單位未辦理獨立商業登記時，下列何者為正確之處理方式？","options":{"A":"該餐廳非由百貨公司或車站營運，因此不納入盤查","B":"百貨公司或鐵路車站盤查時，仍應將該餐廳納入其盤查邊界","C":"由該進駐單位自行向環境部申請另一個管制編號辦理盤查","D":"盤查該餐廳的用電量，不需考慮其瓦斯燃燒之直接排放"},"answer":"B","explanation":"盤查邊界以登記範圍為基準，邊界內未辦理獨立商業登記的進駐餐廳或商店，無法自行取得管制編號，應併入該百貨公司或鐵路車站的盤查邊界一併盤查，B正確。不納入(A)、由進駐單位另申請管編(C)或僅盤電力而忽略瓦斯直接排放(D)均不符完整性與邊界界定原則。","idx":163},{"id":"PE-1152-L12-15","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"某公司2位員工出差拜訪客戶。員工甲騎乘機車 4公里至捷運站，員工乙駕駛自用車4公里至同一捷運站；兩人隨後共同搭乘捷運 15公里，再轉乘公車 6公里至目的地，最後步行至客戶公司（步行碳排放量不計）。依下表交通運具排放係數計算，請問此次兩位員工單趟出差共產生多少碳排放量？","options":{"A":"2.9608kgCO₂e","B":"2.5006kgCO₂e","C":"2.3608kgCO₂e","D":"1.9006kgCO₂e"},"answer":"A","explanation":"依排放係數法，交通排放＝各運具里程×對應排放係數後加總，並依人數計入。本題須將甲(機車4km)、乙(自用車4km)各自分段，加上兩人共乘捷運15km、公車6km的排放分別計算再合計，步行不計，依題附係數表計算結果為2.9608kgCO₂e，故A正確。","idx":164},{"id":"PE-1152-L12-16","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"某公司有員工 45人，已知化糞池逸散 CH₄排放數為3.825公斤 CH₄ ／人年，本次盤查 GWP 採用 IPCC AR5 版本，CH₄之GWP 為28，請問某公司年度化糞池逸散量為多少公噸二氧化碳當量？","options":{"A":"0.0041895","B":"4.8195","C":"481.95","D":"4819.5"},"answer":"B","explanation":"化糞池逸散量＝人數×每人年CH₄排放數×GWP換算。計算為45人×3.825kg CH₄／人年＝172.125kg CH₄；乘以AR5之CH₄ GWP 28得4,819.5kg CO₂e，換算為4.8195公噸CO₂e，故B正確。C、D單位(公斤誤為公噸)錯誤，A則漏乘GWP。","idx":165},{"id":"PE-1152-L12-17","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"進行溫室氣體排放量化時，若缺乏燃料實際重量資料，僅取得採購發票金額及平均單價，下列何者最符合活動數據管理原則？","options":{"A":"依採購發票金額及平均單價推估燃料用量，並於報告中說明估算方法及不確定性","B":"依同期間其他月份之平均燃料用量估算，但因屬估算資料，可免揭露估算依據","C":"依採購發票金額推估燃料用量，並於查證完成後再決定是否補充相關佐證資料","D":"以歷年燃料平均使用量替代當年度活動數據，只要排放趨勢一致即可作為量化依據"},"answer":"A","explanation":"活動數據管理要求資料可追溯並揭露估算方法與不確定性。缺乏實際重量時，依採購發票金額及平均單價推估燃料用量，並於報告中說明估算方法及不確定性，最符合原則，A正確。免揭露估算依據(B)、查證後再補佐證(C)或逕以歷年平均替代(D)均違反透明與可追溯要求。","idx":166},{"id":"PE-1152-L12-18","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"某工廠鍋爐以木屑（生質燃料）作為燃料。依據溫室氣體盤查原則，在計算組織直接溫室氣體排放總量（CO₂e）時，下列哪一項排放量不應加總於直接排放總量，而應另行揭露？","options":{"A":"木屑燃燒產生之甲烷（CH₄）排放量","B":"木屑燃燒產生之氧化亞氮（N₂O）排放量","C":"木屑燃燒產生之生質二氧化碳（CO₂）排放量","D":"木屑燃燒所產生之其他直接溫室氣體排放量"},"answer":"C","explanation":"依教材特定GHG排放之處理，生物源(生質)二氧化碳排放與移除應個別分開表示，不併入直接排放總量加總，而應另行揭露，故C正確。木屑燃燒產生的CH₄、N₂O(A、B)及其他非生質CO₂之溫室氣體(D)仍屬應加總的直接排放。","idx":167},{"id":"PE-1152-L12-19","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"企業進行溫室氣體盤查時，若排放來源為生物質分解產生之甲烷，應如何處理 GWP 係數？","options":{"A":"套用二氧化碳排放係數計算","B":"視為能源使用排放不需區分來源","C":"僅需記錄甲烷量不需換算排放量","D":"依生物甲烷對應係數進行換算"},"answer":"D","explanation":"生物質分解所產生的甲烷雖屬生物源，但甲烷本身仍為具暖化效應的溫室氣體，須以其對應的GWP係數換算為二氧化碳當量，故D(依生物甲烷對應係數進行換算)正確。不可套用CO₂係數(A)、不可不區分來源(B)，亦不可僅記錄量而不換算(C)。","idx":168},{"id":"PE-1152-L12-20","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"某工廠進行組織型溫室氣體盤查，已知：一、製程使用天然氣排放 600tCO₂e。二、外購電力排放 400tCO₂e。三、出租予第三方獨立營運之倉儲，其用電排放 50tCO₂e。四、員工公務車油耗排放 20tCO₂e。若工廠採用「營運控制權法」設定組織邊界，下列何者為其應認列之類別一與類別二排放總量？","options":{"A":"應納入所有排放來源，類別一與二合計 1,070tCO₂e","B":"應排除第三方獨立營運倉儲之用電排放，類別一與二合計 1,020tCO₂e","C":"應僅計入固定燃燒源及外購電力，類別一與二合計 1,000tCO₂e","D":"應排除員工公務車之油耗排放，類別一與二合計 1,050tCO₂e"},"answer":"B","explanation":"營運控制權法下，類別一為直接排放、類別二為外購能源間接排放。製程天然氣600(類別一)＋外購電力400(類別二)＋員工公務車油耗20(屬類別一移動燃燒)應認列；出租予第三方獨立營運倉儲之用電50因非本廠營運控制，應排除。合計1,020tCO₂e，故B正確。","idx":169},{"id":"PE-1152-L12-21","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"某企業年度溫室氣體排放量為 2,000tCO₂e，其中100tCO₂e來自生物質燃料燃燒產生之 CO₂。在溫室氣體報告書中，該 100tCO₂e應如何處理？","options":{"A":"納入類別一總排放量計算，並與化石燃料排放合併揭露","B":"以生物來源 CO₂形式單獨揭露，但不納入總排放量加總計算","C":"因生質碳具有碳中性特性，該排放量可免於報告書中揭露","D":"併入類別二能源間接排放，作為外購能源排放之一部分"},"answer":"B","explanation":"依特定GHG排放之處理，生物源二氧化碳應以生物來源CO₂形式個別分開(單獨)揭露，不納入總排放量加總計算，故B正確。不可併入類別一與化石排放合併(A)或併入類別二(D)，且仍須揭露而非免揭露(C)。","idx":170},{"id":"PE-1152-L12-22","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"關於組織於 ISO 14064-1：2018外部查證前應準備之文件，下列何者正確？","options":{"A":"ISO 14001 驗證文件","B":"內部管理規程、組織架構及內部稽核結果","C":"製程資訊、排放係數資料及合格人員名單","D":"溫室氣體盤查清冊、盤查報告書及管理程序書"},"answer":"D","explanation":"外部查證係針對組織盤查成果進行審查，查證前應備妥溫室氣體盤查清冊、盤查報告書及管理程序書等核心文件，故D正確。ISO 14001驗證文件(A)屬環境管理系統、內部稽核(B)與製程及合格人員名單(C)雖可能參考，但非查證前應準備的核心盤查文件組合。","idx":171},{"id":"PE-1152-L12-23","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"關於溫室氣體盤查報告書應揭露之內容，下列何者不包含於其中？","options":{"A":"基準年或其他過去的溫室氣體盤查清冊之任何重新計算","B":"說明先前使用的量化方法之任何變更之理由","C":"說明歷次過去的溫室氣體數據負責單位及負責人之任何改變","D":"說明將任何重大溫室氣體源或溫室氣體匯排除量化之理由"},"answer":"C","explanation":"盤查報告書應揭露基準年或過去清冊之重新計算(A)、量化方法變更之理由(B)及將重大排放源或匯排除量化之理由(D)等影響可比較性的資訊。歷次數據之負責單位及負責人變更(C)並非報告書必要揭露內容，故C為不包含者，正確。","idx":172},{"id":"PE-1152-L12-24","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"某企業盤查時僅納入主要生產設備排放，未考量冷媒逸散與公務車使用。此作法主要違反溫室氣體清冊之何項原則？","options":{"A":"完整性","B":"相關性","C":"一致性","D":"透明度"},"answer":"A","explanation":"完整性原則要求納入所有相關的溫室氣體排放與移除。僅盤查主要生產設備而遺漏冷媒逸散與公務車等排放源，造成清冊不完整，主要違反完整性原則，故A正確。相關性(B)涉及源與方法選擇、一致性(C)涉及方法比較、透明度(D)涉及揭露，均非本案主要違反者。","idx":173},{"id":"PE-1152-L12-25","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"依據溫室氣體盤查報告書之基本內容要求，某公司盤查報告書目前包含下列章節：一、公司基本資料二、盤查邊界設定三、排放量計算四、查驗結果五、減量規劃若欲使其內容更趨完整，下列何者最應補入？","options":{"A":"財務績效、供應商管理、客戶滿意度","B":"排放源鑑別、數據品質管理、其他主管機關規定事項","C":"員工訓練紀錄、減碳宣導活動、永續獎項","D":"碳權交易紀錄、碳中和聲明、產品碳足跡"},"answer":"B","explanation":"完整的盤查報告書除公司資料、邊界、計算、查驗與減量外，尚應涵蓋排放源鑑別、數據品質管理及其他主管機關規定事項等核心程序內容，故B最應補入。財務績效、客戶滿意度(A)、員工訓練與獎項(C)、碳權交易與產品碳足跡(D)非組織盤查報告書之基本必要章節。","idx":174},{"id":"PE-1152-L12-26","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"關於 ISO 14064-1：2018 規定之溫室氣體盤查報告內容，下列何者係用以界定應盤查之排放？","options":{"A":"界定重大排放準則","B":"文件報告期間資訊","C":"生產製程排放源","D":"組織盤查過程說明"},"answer":"A","explanation":"界定「應盤查之排放」的關鍵在於建立判斷何者為重大排放源的準則；對間接排放須以重大性(顯著性)評估準則決定納入與否，故A(界定重大排放準則)用以界定應盤查的排放，正確。報告期間資訊(B)、製程排放源(C)、盤查過程說明(D)屬報告其他組成，非界定應盤查排放之依據。","idx":175},{"id":"PE-1152-L12-27","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L121","stem":"依據我國環境部《溫室氣體排放量盤查登錄管理辦法》之規定，應辦理盤查登錄之事業，其盤查、登錄及查證相關之原始資料、計算過程及證明文件，至少應保存多久？","options":{"A":"3年","B":"4年","C":"5年","D":"6年"},"answer":"D","explanation":"依我國溫室氣體排放量盤查登錄相關管理辦法，應辦理盤查登錄之事業，其盤查、登錄及查證之原始資料、計算過程與證明文件至少應保存6年，故D正確。(註：保存年限為辦法之程序性規定，本教材未逐條列明，係依現行管理辦法規定。)","idx":176},{"id":"PE-1152-L12-28","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"在執行產品碳足跡盤查的數據檢核程序中，關於資料品質管理原則的作法，下列何者通常不符合？","options":{"A":"透過質量平衡（Mass Balance）檢核投入與產出資料，並評估是否落於合理誤差範圍","B":"確認活動數據以實際使用量為原則，並依庫存變動修正領用量後進行計算","C":"保存電費單、採購單及領料紀錄等佐證文件，以利後續查證及追溯","D":"盤查資料可與 ERP 或原始單據存在差異，只要經內部人員說明原因即可接受"},"answer":"D","explanation":"資料品質管理要求活動數據可追溯、可查證並與原始單據一致。選項D主張盤查資料可與ERP或原始單據存在差異、僅憑內部人員說明即接受，違反可追溯與查證原則，為不符合者，故D正確。質量平衡檢核(A)、依庫存修正領用量(B)、保存佐證文件(C)皆屬正確作法。","idx":177},{"id":"PE-1152-L12-29","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"關於產品生命週期終結階段納入產品碳足跡（Carbon Footprint of Product, CFP）研究之規定，下列何者不屬於生命終結階段之作業？","options":{"A":"有機回收（如堆肥與厭氧消化）","B":"製程剩餘原料或廢棄物之委外處理","C":"掩埋處理及掩埋場維護與甲烷排放管理","D":"焚化處理及底渣分類再利用作業"},"answer":"B","explanation":"生命終結(End-of-life)階段涵蓋產品使用後的最終處置，如有機回收(堆肥、厭氧消化)(A)、掩埋及甲烷管理(C)、焚化與底渣再利用(D)。製程剩餘原料或廢棄物之委外處理(B)係製造階段產生之廢棄物處理，不屬產品生命終結階段作業，故B為不屬於者，正確。","idx":178},{"id":"PE-1152-L12-30","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"依據 ISO 14067：2018標準要求，於進行數據量化時，排放源計算至標的產品之分配原則，其引用優先順序為何？","options":{"A":"避免分配（Avoid Allocation）→物理分配法（Physical Allocation）→經濟分配法（Economic Allocation）","B":"物理分配法（Physical Allocation）→經濟分配法（Economic Allocation）→避免分配（Avoid Allocation）","C":"經濟分配法（Economic Allocation）→物理分配法（Physical Allocation）→避免分配（Avoid Allocation）","D":"避免分配（Avoid Allocation）經濟分配法（Economic Allocation）→物理分配法（Physical Allocation）"},"answer":"A","explanation":"依ISO 14067，分配處理之引用優先順序為：先盡可能避免分配(以次製程細分或擴大系統邊界)，其次採反映基本物理關係的物理分配法，最後在物理關係無法建立時才採經濟價值等經濟分配法。故順序為避免分配→物理分配→經濟分配，A正確。","idx":179},{"id":"PE-1152-L12-31","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"在計算產品碳足跡（Carbon Footprint of Product, CFP）時，為何不能直接使用組織型碳盤查（GHG）的電力排碳係數？","options":{"A":"因為GHG 係數僅計算發電時的排碳","B":"因為GHG 係數包含原料開採的排碳","C":"因為GHG 係數專門用於計算水資源","D":"因為GHG 係數已排除電網輸配損耗"},"answer":"A","explanation":"組織型GHG盤查之電力排放係數主要僅反映發電當下的排碳，未涵蓋燃料開採、運輸等上游生命週期與輸配損耗；而CFP需以生命週期觀點納入電力供應系統全生命週期排放，故不能直接沿用，A正確。GHG係數並非含原料開採(B)、用於水資源(C)或已排除輸配損耗(D)。","idx":180},{"id":"PE-1152-L12-32","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"關於生命週期評估（Life Cycle Assessment, LCA）中「功能單位（Functional Unit）」之主要作用，下列何者正確？","options":{"A":"規定產品在市場上必須具備之銷售價格基準","B":"提供量化基準，以比較相同服務下產品環境負荷","C":"統計工廠員工工時與碳排放之關聯程度分析","D":"用於換算產品重量與每單位體積碳排放關係"},"answer":"B","explanation":"功能單位的主要作用是提供清楚且可量測的量化基準(參考單位)，使相同功能或服務下不同產品的環境負荷得以在一致基礎上比較，故B正確。功能單位非銷售價格基準(A)、非員工工時統計(C)，亦非單純重量與體積換算(D)。","idx":181},{"id":"PE-1152-L12-33","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"關於生命週期評估（Life Cycle Assessment, LCA）之系統邊界設定，下列何者通常不需納入產品生命週期評估範圍？","options":{"A":"生產設備的維運保養","B":"輔助性物料之製造","C":"產品的研發","D":"生產階段的照明與空調"},"answer":"C","explanation":"LCA系統邊界通常納入與產品實體生命週期直接相關的流程，如生產設備維運保養(A)、輔助物料製造(B)、生產階段照明與空調(D)。產品的研發(C)屬前期設計活動，通常不納入產品生命週期評估範圍，故C為不需納入者，正確。","idx":182},{"id":"PE-1152-L12-34","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"關於生命週期評估（Life Cycle Assessment, LCA）中「使用階段」之溫室氣體排放，下列何種產品通常於該階段排放占比最高？","options":{"A":"寶特瓶裝礦泉水","B":"電冰箱或大型中央空調設備","C":"傳統鋼鐵建材或預拌混凝土","D":"木造家具或再生紙張"},"answer":"B","explanation":"使用階段為消費者使用產品之過程，耗能型產品於此階段排放占比最高。電冰箱或大型中央空調設備使用期長且持續耗電，使用階段排放通常最高，故B正確。瓶裝水(A)、鋼鐵建材或混凝土(C)、木造家具或再生紙(D)排放多集中於原料或製造階段。","idx":183},{"id":"PE-1152-L12-35","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"關於產品類別規則（PCR）之適用原則及國際通用性，下列何者正確？","options":{"A":"若同一產品已有適用之 PCR，企業仍可自行改採其他產品類別之 PCR，以提升不同產品間之比較性","B":"依ISO 14067：2018 規定，產品已有適用之 PCR 時，執行產品碳足跡量化原則上應依該 PCR 辦理","C":"產品依我國環境部核定之 PCR 完成碳足跡查證後，即可直接作為各國產品環境宣告之共同依據","D":"PCR 可由企業自行制定並直接採用，不須經公開審查或利害關係人參與程序"},"answer":"B","explanation":"依ISO 14067，若產品已有相關且適用之PCR或CFP-PCR，執行碳足跡量化原則上應依該PCR辦理，以確保同類產品可比較，故B正確。不可自行改採他類PCR(A)，國內查證結果不等同各國共同依據(C)，PCR須經公開審查與利害關係人參與，不得由企業自訂逕用(D)。","idx":184},{"id":"PE-1152-L12-36","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"國內某公司擬向環境部申請產品碳足跡標籤，於碳足跡資訊網查得該產品對應之 CCC Code已有國內產品類別規則（PCR），但部分規定與產品特性不符。下列何者為較適當之處理方式？","options":{"A":"引用較符合產品特性的國外 PCR，完成第三方查證後即可據以申請國內產品碳標籤","B":"依據「碳足跡產品類別規則訂定、引用及修訂指引」申請修訂該份國內 PCR","C":"使用ISO 14067：2018 進行盤查，提出產品標籤申請時需加註說明該 PCR 為何不適用","D":"申請作廢該份國內 PCR，重新制定屬於自家產品的 PCR"},"answer":"B","explanation":"當產品已有對應CCC Code之國內PCR但部分規定與產品特性不符時，適當做法是依「碳足跡產品類別規則訂定、引用及修訂指引」申請修訂該份國內PCR，故B正確。逕引國外PCR申請國內標籤(A)、自行加註不適用(C)或作廢後重訂(D)均非正規處理程序。","idx":185},{"id":"PE-1152-L12-37","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"依據 CNS 14027《環境標誌與宣告－產品類別規則（PCR）之制定》，關於產品類別規則（PCR）應包含之必要內容，下列何者不正確？","options":{"A":"功能或宣告單位","B":"系統邊界、資料品質要求及生命週期各階段之納入原則","C":"多重產品系統之分配原則","D":"碳標籤的標示方法"},"answer":"D","explanation":"PCR之必要內容應包含功能或宣告單位(A)、系統邊界及資料品質要求與各階段納入原則(B)、多重產品系統之分配原則(C)等量化規則。碳標籤的標示方法(D)屬標籤方案或宣告之規定，非PCR必要內容，故D為不正確者，正確。","idx":186},{"id":"PE-1152-L12-38","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"依據產品類別規則（PCR）之生命週期系統邊界，下列何者通常不屬於產品「製造階段」應納入評估之流程？","options":{"A":"能資源與電力之消耗","B":"製程用水供應","C":"製程廢棄物處理","D":"各原料到製造工廠之運輸"},"answer":"D","explanation":"依PCR之生命週期系統邊界，製造階段納入製程之能資源與電力消耗(A)、製程用水供應(B)及製程廢棄物處理(C)。各原料到製造工廠之運輸(D)屬原料取得階段，非製造階段，故D為不屬於者，正確。","idx":187},{"id":"PE-1152-L12-39","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"關於在臺灣申請碳足跡標籤與使用碳足跡產品類別規則（CFP-PCR）上，下列敘述何者不正確？","options":{"A":"若不申請碳足跡標籤則可依據 ISO 14067：2018進行碳足跡盤查與計算即可，不一定需要依據 PCR","B":"商品製造商、提供該類服務業者或產品業者所組成之同業公（協、商）會、政府機關（構）均可擔任 PCR 制定者","C":"要向環境部申請碳足跡標籤或碳足跡減量標籤者，可依使用需要決定引用國內或國外 PCR","D":"PCR 制定流程的準備階段，需將草案於網路上預告 14日以上，供利害相關者審閱"},"answer":"C","explanation":"選項C不正確：向環境部申請碳足跡標籤時，若國內已有適用PCR應優先引用國內PCR，不得任意依需要自由決定引用國內或國外PCR。其餘正確：不申請標籤時可僅依ISO 14067盤查(A)、業者公協會及政府機關可擔任PCR制定者(B)、PCR草案須網路預告14日以上供審閱(D)。","idx":188},{"id":"PE-1152-L12-40","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"某食品公司辦理蛋糕產品碳足跡（CFP）盤查。依國內CFP-PCR 對一級數據（Primary Data）蒐集之要求，其製造階段排放僅占「原料取得階段與製造階段」總排放量之 5%。下列何者最符合數據蒐集要求？","options":{"A":"應優先取得排放貢獻最高之原料供應商一級數據，且其數據必須經第三方查證後始得採用","B":"應取得上游供應商之一級數據，使製造階段與供應商一級數據合計至少達總排放量 5%，即可符合要求","C":"應取得上游供應商之一級數據，使製造階段與供應商一級數據合計至少達原料取得與製造階段總排放量 10%","D":"若無法取得全部供應商資料，僅需蒐集供貨量占比超過 75%之供應商一級數據，即可視為符合要求"},"answer":"C","explanation":"依題旨之一級數據蒐集要求，當製造階段排放僅占原料取得與製造階段總排放5%時，應向上游供應商取得一級數據，使製造階段與供應商一級數據合計至少達該兩階段總排放量之10%，故C正確。(註：此門檻為CFP-PCR一級數據蒐集之規定，本教材未明列具體百分比，係依官方正確答案判定。)","idx":189},{"id":"PE-1152-L12-41","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"若某產品的碳足跡計算中，某輔助材料碳排放量極低（低於 1%），此時可依據何種原則予以排除？","options":{"A":"依據切斷規則原則予以排除","B":"依據分配計算原則予以排除","C":"依據功能單位原則予以排除","D":"依據數據品質原則予以排除"},"answer":"A","explanation":"依切斷(截斷)準則，任一溫室氣體源之排放貢獻占預期生命週期排放量≦1%者可於盤查時忽略(累計不得超過5%)。輔助材料碳排放低於1%時即可依切斷規則原則予以排除，故A正確，與分配(B)、功能單位(C)、數據品質(D)原則無涉。","idx":190},{"id":"PE-1152-L12-42","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"產品碳足跡（CFP）採用「搖籃到墳墓（Cradle to Grave）」系統邊界時，下列何者通常不納入碳足跡盤查範圍？","options":{"A":"消費者往返零售通路購買產品所產生之交通排放","B":"原料自供應商運送至製造工廠之物流運輸排放","C":"製造產品所投入之原物料及相關製程排放","D":"產品使用階段所消耗之能源或其他資源排放"},"answer":"A","explanation":"搖籃到墳墓涵蓋原料取得、製造、配送、使用及生命終結，但消費者往返銷售據點(零售通路)購買產品的交通排放依規定不列入評估，故A為不納入者，正確。原料運至工廠物流(B)、製程原料與排放(C)、使用階段能源消耗(D)均屬應納入範圍。","idx":191},{"id":"PE-1152-L12-43","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"產品碳足跡（CFP）生命終期（End-of-life）階段進行量化時，下列何者通常為主要活動數據或資訊來源？","options":{"A":"廢棄之產品或包裝材重量","B":"製程廢棄物處理方式","C":"產品或包裝材清運距離","D":"製造產品時經過哪些程序"},"answer":"A","explanation":"產品生命終期(End-of-life)階段量化時，主要活動數據為廢棄之產品或包裝材重量，作為後續清運與處置排放計算之基礎，故A正確。製程廢棄物處理方式(B)與製造程序(D)屬製造階段，清運距離(C)雖相關但非主要的量化活動數據來源。","idx":192},{"id":"PE-1152-L12-44","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"關於產品碳足跡（CFP）系統邊界之規範，下列何者通常需納入 B2C 產品碳足跡計算，但 B2B 產品通常可不納入或視情境決定？","options":{"A":"原料取得階段的相關溫室氣體排放","B":"產品生產製造的相關溫室氣體排放","C":"零組件運輸至工廠的溫室氣體排放","D":"產品使用階段的相關溫室氣體排放"},"answer":"D","explanation":"B2C產品採搖籃到墳墓，須納入產品使用階段排放；B2B產品為搖籃到大門(半成品／零組件)，使用階段通常不納入或視情境決定，故須納入B2C而B2B通常可不納入者為產品使用階段(D)。原料取得(A)、生產製造(B)、零組件運輸(C)兩者一般皆須納入。","idx":193},{"id":"PE-1152-L12-45","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"關於商品（Goods）與服務（Services）之生命週期製程地圖（Process Map），下列哪一階段在兩者間通常無明顯差異？","options":{"A":"製造階段","B":"配送銷售階段","C":"使用階段","D":"廢棄處理"},"answer":"D","explanation":"商品與服務的生命週期製程地圖在製造(A)、配送銷售(B)、使用(C)等階段因實體產品與服務提供方式不同而有明顯差異，但廢棄處理(D)階段兩者處理對象與作業類似，通常無明顯差異，故D正確。","idx":194},{"id":"PE-1152-L12-46","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"關於產品碳足跡（CFP）研究中，若相同產品採用不同的系統邊界進行量化，最可能對研究結果造成下列何種影響？","options":{"A":"排放係數可自動修正系統邊界差異，使結果維持一致","B":"排放結果可能被高估或低估","C":"功能單位通常須重新定義，才能消除不同系統邊界造成之量化差異","D":"系統邊界僅影響資料蒐集成本，不影響量化結果"},"answer":"B","explanation":"系統邊界決定納入計算的單元過程與生命週期階段，相同產品若採用不同系統邊界(納入或排除之範圍不同)，將使排放結果可能被高估或低估，故B正確。排放係數無法自動修正邊界差異(A)，功能單位非用以消除邊界差異(C)，邊界確實影響量化結果而非僅成本(D)。","idx":195},{"id":"PE-1152-L12-47","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"關於產品碳足跡結果闡釋（Interpretation）階段，下列何者為其主要目的？","options":{"A":"檢視碳足跡結果之完整性與一致性，並確認資料是否符合研究目的","B":"評估結果完整性、敏感度及一致性，並提出結論與建議","C":"比較各生命週期階段排放量，僅以排放最高之階段作為改善重點","D":"依量化結果直接決定產品售價及節能改善方案，作為最終研究結論"},"answer":"B","explanation":"生命週期闡釋(Interpretation)階段應鑑別重大議題、進行分配與情境之敏感度分析、評估結果之完整性與一致性，並做出結論、限制與建議，故B最完整正確。A僅涵蓋部分查核，C以單一最高階段為改善重點過於偏狹，D逕定售價與方案並非闡釋之主要目的。","idx":196},{"id":"PE-1152-L12-48","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"企業欲依 ISO 14067：2018進行產品碳足跡比較，下列何項條件最重要？","options":{"A":"確保功能單位與系統邊界一致","B":"優先選擇排放量較低產品比較","C":"僅比較製造階段能源使用量","D":"依企業規模調整計算方法"},"answer":"A","explanation":"依ISO 14067進行產品碳足跡比較時，須確保功能單位與系統邊界一致，才能在相同功能基礎與相同生命週期範圍下公平比較，故A最重要。優先選低排放產品(B)、僅比製造階段能源(C)或依企業規模調整方法(D)均會破壞可比較性。","idx":197},{"id":"PE-1152-L12-49","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"依據 ISO 14067：2018產品碳足跡報告揭露原則，下列何者資訊通常不須單獨揭露？","options":{"A":"產品所含之零件的碳排放量","B":"來自飛機運輸的碳排放量","C":"源自化石的淨溫室氣體量","D":"源自生物的淨溫室氣體量"},"answer":"A","explanation":"依ISO 14067報告揭露原則，源自化石的淨溫室氣體量(C)與源自生物的淨溫室氣體量(D)應分別揭露，特定運輸(如飛機)排放(B)依需要揭露，而產品所含個別零件的碳排放量(A)通常不須單獨揭露，故A正確。","idx":198},{"id":"PE-1152-L12-50","source":"past_exam","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":"115年第二次","unit":"L122","stem":"在產品生命週期的碳排評估中，若企業購買了碳權，是否可以直接將該產品的碳足跡計算為零？","options":{"A":"不可以，計算碳足跡不允許應用碳抵換","B":"可以，只要碳權經過第三方機構認證","C":"不可以，除非碳權來自於植樹造林專案","D":"可以，購買碳權即可抵消所有的碳排"},"answer":"A","explanation":"產品碳足跡係量化產品生命週期實際之溫室氣體排放，計算時不允許以購買碳權進行碳抵換來折抵，故購買碳權不能直接將碳足跡計為零，A正確。無論碳權是否經第三方認證(B)、是否來自造林(C)或數量多寡(D)，均不得於CFP量化中抵減。","idx":199},{"id":"UP-L111-01","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"聯合國氣候變遷大會締約方大會(COP)是在哪一年第一次召開？","options":{"A":"1992 年","B":"1994 年","C":"1995 年","D":"1997 年"},"answer":"C","explanation":"1995 年。","idx":200},{"id":"UP-L111-02","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"《聯合國氣候變化框架公約》(UNFCCC)的最終目標是什麼？","options":{"A":"限制全球平均氣溫上升","B":"降低全球糧食生產量","C":"增加全球綠化覆蓋率","D":"減少全球人口數量"},"answer":"A","explanation":"限制全球平均氣溫上升。","idx":201},{"id":"UP-L111-03","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"京都議定書要求附件一國家的溫室氣體排放量平均減量百分比是多少？","options":{"A":"3.2%","B":"4.5%","C":"5.2%","D":"6.3%"},"answer":"C","explanation":"5.2%。","idx":202},{"id":"UP-L111-04","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"《京都議定書》於哪一年正式生效？","options":{"A":"1997 年","B":"2001 年","C":"2005 年","D":"2008 年"},"answer":"C","explanation":"2005 年。","idx":203},{"id":"UP-L111-05","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"巴黎協定旨在將全球溫室氣體排放限制在遠低於幾度攝氏的水平？","options":{"A":"1℃","B":"1.5℃","C":"2℃","D":"2.5℃"},"answer":"C","explanation":"2°C。","idx":204},{"id":"UP-L111-06","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"由於 COVID-19 大流行，哪一年 COP 未能舉行實體會議？","options":{"A":"2019 年","B":"2020 年","C":"2021 年","D":"2022 年"},"answer":"B","explanation":"2020 年。","idx":205},{"id":"UP-L111-07","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"《巴黎協定》要求各國提交國家氣候行動計劃，即國家自主貢獻(NDC)，這些貢獻的連續更新周期是多久？","options":{"A":"每三年一次","B":"每五年一次","C":"每七年一次","D":"每十年一次"},"answer":"B","explanation":"每五年一次。","idx":206},{"id":"UP-L111-08","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"京都議定書的彈性減量機制不包括下列哪項？","options":{"A":"清潔發展機制(CDM)","B":"排放交易(ET)","C":"共同執行(JI)","D":"環境可持續指數(ESI)"},"answer":"D","explanation":"環境可持續指數(ESI)。","idx":207},{"id":"UP-L111-09","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"《京都議定書》的減量時程是從哪年開始到哪年結束？","options":{"A":"1996 年至 2000 年","B":"1998 年至 2002 年","C":"2000 年至 2004 年","D":"2008年至 2012 年"},"answer":"D","explanation":"2008 年至 2012 年。","idx":208},{"id":"UP-L111-10","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"於阿拉伯聯合大公國杜拜舉辦的 COP28，正式通過設立什麼機制來支持那些因氣候變遷遭受重大損失的國家？","options":{"A":"綠色氣候基金","B":"國際環境機構","C":"損失和損害資金","D":"全球氣候恢復基金"},"answer":"C","explanation":"損失和損害資金。","idx":209},{"id":"UP-L111-11","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"聯合國氣候變化框架公約的目標是什麼？","options":{"A":"增加溫室氣體排放","B":"減少臭氧層破壞","C":"穩定大氣中溫室氣體濃度","D":"促進經濟發展"},"answer":"C","explanation":"穩定大氣中溫室氣體濃度。","idx":210},{"id":"UP-L111-12","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"已開發國家締約方應如何對待氣候變遷及其不利影響？","options":{"A":"等待進一步的科學證據","B":"積極應對","C":"交由發展中國家處理","D":"僅通過財務援助參與"},"answer":"B","explanation":"依 UNFCCC，已開發國家締約方應率先且積極應對氣候變遷及其不利影響，而非等待科學證據或交由開發中國家處理，故選 B。","idx":211},{"id":"UP-L111-13","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"發展中國家在公約中的特殊考慮是什麼？","options":{"A":"不需要減少溫室氣體排放","B":"獲得額外資金","C":"面臨的具體需要和特殊情況應充分考慮","D":"享有豁免權"},"answer":"C","explanation":"公約明定應充分考慮開發中國家（尤其最脆弱國家）面臨的具體需要與特殊情況，而非給予豁免或僅提供資金，故選 C。","idx":212},{"id":"UP-L111-14","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"締約方應採取哪種類型的措施來對付氣候變遷？","options":{"A":"僅政策上的改變","B":"僅投資高科技解決方案","C":"預防措施，包括緩解其不利影響","D":"僅通過國際會議進行討論"},"answer":"C","explanation":"預防措施，包括緩解其不利影響。","idx":213},{"id":"UP-L111-15","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"聯合國氣候變化框架公約中關於減緩或適應氣候變遷的項目應如何進行？","options":{"A":"必須由政府單獨進行","B":"應融入相關社會、經濟和環境政策及行動中","C":"僅在國際壓力下進行","D":"必須完全獨立於其他政策"},"answer":"B","explanation":"應融入相關社會、經濟和環境政策及行動中。","idx":214},{"id":"UP-L111-16","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"台灣制定氣候變遷調適策略的願景是什麼？","options":{"A":"增加溫室氣體排放","B":"減少自然資源的使用","C":"為建構能適應氣候風險之低碳家園","D":"完全依賴再生能源"},"answer":"C","explanation":"台灣的願景是通過制定氣候變遷調適策略及淨零排放路徑藍圖，建構一個能夠適應氣候風險的低碳家園，以確保國家的永續發展。","idx":215},{"id":"UP-L111-17","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"台灣設定的國家溫室氣體長期減量目標是什麼？","options":{"A":"112 年溫室氣體淨零排放","B":"120 年溫室氣體淨零排放","C":"139 年溫室氣體淨零排放","D":"150 年溫室氣體淨零排放"},"answer":"C","explanation":"台灣的目標是在 139 年達到溫室氣體淨零排放，這顯示了台灣對於減少溫室氣體排放和應對氣候變遷的承諾。","idx":216},{"id":"UP-L111-18","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"台灣在因應氣候變遷的基本原則中，不包括以下哪項？","options":{"A":"遵循「巴黎協定」","B":"實施碳交易制度","C":"新增核能發電","D":"增強化資訊公開及公民參與"},"answer":"C","explanation":"台灣的基本原則中明確指出，不以新增核能發電作為因應氣候變遷的措施，而是逐步降低化石燃料依賴，並訂定再生能源發展目標。","idx":217},{"id":"UP-L111-19","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"台灣推動綠色金融及碳定價機制的目的是什麼？","options":{"A":"加速溫室氣體減量","B":"增加政府收入","C":"限制民間資金運用","D":"減少國際合作"},"answer":"A","explanation":"透過推動綠色金融及碳定價機制，包括碳費徵收和溫室氣體總量管制與排放交易等，台灣旨在透過經濟誘因機制加速溫室氣體的減量，協助產業轉型，並提升國家競爭力，促進社會公益。","idx":218},{"id":"UP-L111-20","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"台灣政策配套中，不包括以下哪項？","options":{"A":"推動綠色金融","B":"檢討與改善再生能源等法令","C":"發展氣候變遷科學及衝擊調適研究","D":"全面禁止再生能源的發展"},"answer":"D","explanation":"台灣的政策配套著重於推動綠色金融、檢討和改善相關法令以支持再生能源、能源管理等，並非禁止再生能源的發展。相反，台灣致力於透過各項措施支持再生能源的發展，以促進綠色轉型和氣候韌性。","idx":219},{"id":"UP-L111-21","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"氣候變遷調適(Adaptation)是指？","options":{"A":"降低二氧化碳排放","B":"增加綠色植被面積","C":"人類與自然系統回應氣候變遷風險的調整過程","D":"減少工業化進程"},"answer":"C","explanation":"人類與自然系統回應氣候變遷風險的調整過程。","idx":220},{"id":"UP-L111-22","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"碳中和(Carbon Neutrality)指的是？","options":{"A":"完全停止二氧化碳排放","B":"主體相關的人為二氧化碳排放量與移除量達平衡狀態","C":"對碳排放量進行監控","D":"增加二氧化碳的吸收"},"answer":"B","explanation":"碳中和指特定主體在特定期間內，人為二氧化碳排放量與移除量達成平衡（淨值為零），並非完全停止排放或僅進行監控，故選 B。","idx":221},{"id":"UP-L111-23","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"碳洩漏(Carbon Leakage)是指？","options":{"A":"碳的物理洩漏","B":"碳排放管制導致產業轉移到碳管制較寬鬆的地區","C":"植物吸收二氧化碳的過程","D":"溫室氣體的自然循環"},"answer":"B","explanation":"碳洩漏指因各地碳管制嚴格程度不同，使產業或排放移轉至管制較寬鬆地區，抵消全球減量成效，故選 B，非指碳的物理洩漏。","idx":222},{"id":"UP-L111-24","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"碳捕捉技術(CCUS)包括以下哪些過程？","options":{"A":"從大氣中移除氧氣","B":"僅指從工業設施中捕捉二氧化碳","C":"從排放源捕捉二氧化碳及儲存過程","D":"增加化石燃料的使用"},"answer":"C","explanation":"CCUS（碳捕捉、再利用與封存）涵蓋自排放源捕捉二氧化碳並加以再利用或封存儲存的完整流程，故選 C，而非移除氧氣或增加化石燃料使用。","idx":223},{"id":"UP-L111-25","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"碳定價(Carbon pricing)通常被視為以下哪一項？","options":{"A":"溫室氣體排放的獎勵計劃","B":"減緩政策努力過程的經濟手段","C":"增加碳排放的懲罰措施","D":"一種氣候變遷適應措施"},"answer":"B","explanation":"減緩政策努力過程的經濟手段。","idx":224},{"id":"UP-L111-26","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"總量管制與排放交易系統(Cap and trade)的主要特點是什麼？","options":{"A":"為溫室氣體排放設定一個不變的上限","B":"為溫室氣體排放設定一個上限並允許排放權的交易","C":"僅限於管制碳排放的產業","D":"鼓勵企業自由排放溫室氣體"},"answer":"B","explanation":"為溫室氣體排放設定一個上限並允許排放權的交易。","idx":225},{"id":"UP-L111-27","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"組織邊界(organizational boundary)的定義是什麼？","options":{"A":"組織建築的實體邊界","B":"組織財務報告中所包含的邊界","C":"組織的行銷範圍","D":"組織管理控制範圍內的活動或設施"},"answer":"D","explanation":"組織管理控制範圍內的活動或設施。","idx":226},{"id":"UP-L111-28","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"直接溫室氣體排放(direct greenhouse gas emission)指的是什麼？","options":{"A":"來自組織所擁有或控制的溫室氣體源的排放","B":"任何溫室氣體的排放","C":"由消費者排放的溫室氣體","D":"來自自然源的溫室氣體排放"},"answer":"A","explanation":"來自組織所擁有或控制的溫室氣體源的排放。","idx":227},{"id":"UP-L111-29","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"碳抵換(carbon offsetting)通常涉及？","options":{"A":"減少產品的重量來減少運輸成本","B":"在產品系統外部減少或消除溫室氣體排放","C":"調整產品設計來降低生產成本","D":"通過技術創新來提升產品的能效"},"answer":"B","explanation":"在產品系統外部減少或消除溫室氣體排放。","idx":228},{"id":"UP-L111-30","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"產品碳足跡(CFP)是指？","options":{"A":"單一產品的製造成本","B":"產品從生產到銷毀的總能耗","C":"產品的市場價值","D":"產品系統中溫室氣體排放與移除的總和"},"answer":"D","explanation":"產品系統中溫室氣體排放與移除的總和。","idx":229},{"id":"UP-L112-31","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CDP 成立於哪一年？","options":{"A":"1995 年","B":"2000 年","C":"2005 年","D":"2010 年"},"answer":"B","explanation":"CDP (國際碳揭露計畫)於 2000 年成立，最初命名為「碳揭露計畫」，隨後發展成一個全球性的揭露系統，旨在幫助投資者、公司、城市、州份等管理其環境影響。","idx":230},{"id":"UP-L112-32","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CDP 的數據集重點不包括哪一項？","options":{"A":"氣候變化","B":"森林砍伐","C":"水安全","D":"城市擴張"},"answer":"D","explanation":"CDP 的數據集專注於氣候變化、森林砍伐、水安全等環境問題，並在 2021 年擴展到包括生物多樣性、塑膠和海洋等新領域。城市擴張並非 CDP 數據集的重點。","idx":231},{"id":"UP-L112-33","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CDP 每年如何評估公司和城市？","options":{"A":"通過客戶反饋","B":"通過投資者投票","C":"通過獨立評分方法","D":"通過公開投標"},"answer":"C","explanation":"CDP 通過一個獨立的評分方法來評估公司和城市在揭露和環境領導力方面的進展情況。這種方法旨在測量他們在氣候變化、森林和水安全方面的行動進展。","idx":232},{"id":"UP-L112-34","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"通過 CDP 揭露環境數據可以帶來哪些商業利益？","options":{"A":"增加產品銷量","B":"提高公司聲譽","C":"減少員工數量","D":"增加原材料消耗"},"answer":"B","explanation":"通過 CDP 揭露環境數據可以保護和提升公司聲譽，增強競爭優勢，發現風險和機會，以及跟踪和評估進展。這顯示了透明度能夠建立信任並應對公眾日益增長的環境問題，進而提高公司聲譽。","idx":233},{"id":"UP-L112-35","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CDP 原本的名稱是什麼？","options":{"A":"碳排放計畫","B":"碳揭露計畫","C":"氣候變化計畫","D":"環境保護計畫"},"answer":"B","explanation":"CDP 最初於 2000 年成立時被稱為「碳揭露計畫」，隨著時間發展，它已經擴展成一個全球性的揭露系統，旨在幫助投資者、公司、城市和州等管理其環境影響。","idx":234},{"id":"UP-L112-36","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CDP 評分系統的目的是什麼？","options":{"A":"提升公司股票價值","B":"增加企業的市場份額","C":"降低環境法律訴訟的風險","D":"測量企業和城市的環境行動進展"},"answer":"D","explanation":"CDP 透過獨立的評分方法評估公司和城市在揭露和環境領導力方面的進展情況，目的是激勵和測量他們在氣候變化、森林保護和水安全方面的行動進展。","idx":235},{"id":"UP-L112-37","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CDP 揭露對企業有哪些具體商業利益？","options":{"A":"限制國際貿易","B":"增加稅收負擔","C":"提高公司聲譽和競爭優勢","D":"降低員工滿意度"},"answer":"C","explanation":"通過 CDP 進行環境數據的揭露可以幫助企業提高其聲譽，增強競爭優勢，發現風險和機會，以及跟蹤和評估其環境進展。這有助於建立透明度，應對公眾對環境問題的關注，並在股票市場和資金獲取中獲得競爭優勢。","idx":236},{"id":"UP-L112-38","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CDP 如何幫助企業領先於監管要求？","options":{"A":"通過提前滿足多個地區的報告規則","B":"通過減少政府監管","C":"通過提供法律咨詢","D":"通過促進環境創新"},"answer":"A","explanation":"通過 CDP 進行環境數據的揭露可以使公司在面對越來越多的強制性環境報告要求時處於有利位置。 CDP 的揭露要求往往領先於政府和監管機構的規定，幫助企業提前適應未來可能實施的法律和規範，從而在強制揭露勢頭日益強勁的世界中保持領先。","idx":237},{"id":"UP-L112-39","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CDP 的主要目的是什麼？","options":{"A":"提供全球性的金融服務","B":"推動全球森林砍伐","C":"促進全球範圍內的貿易自由化","D":"促進投資者、公司、城市、州和地區管理其環境影響"},"answer":"D","explanation":"CDP (碳揭露計畫)的主要目的是促進投資者、公司、城市、州和地區管理其環境影響。通過提供一個全球性的揭露系統，CDP 鼓勵組織透明化地報告其氣候變化、水安全和森林砍伐等環境議題的資訊，從而推動全球向可持續發展的轉型。","idx":238},{"id":"UP-L112-40","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CDP 在擴展其環境影響評估領域時，新增加了哪些領域的關注？","options":{"A":"僅限於氣候變化的影響","B":"僅限於水資源管理","C":"交通擁堵和城市規劃","D":"生物多樣性、塑膠"},"answer":"D","explanation":"CDP 在其環境影響評估的範圍中新增加了對生物多樣性、塑膠污染。這一擴展反映了 CDP 對於全球環境問題日益增長的認識和回應，展示了該組織致力於全面評估和管理企業和地方政府在更廣泛環境問題上的影響和責任。","idx":239},{"id":"UP-L112-41","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"科學基礎減量目標倡議(SBTi)是由哪些組織共同發起的？","options":{"A":"國際能源機構(IEA)、國際紅十字會、世界衛生組織","B":"綠色和平組織、世界貿易組織、國際奧林匹克委員會","C":"聯合國全球盟約、CDP、世界資源研究所(WRI)、世界自然基金會(WWF)","D":"國際紅十字會、國際能源機構(IEA)、綠色和平組織"},"answer":"C","explanation":"SBTi 是由聯合國全球盟約、CDP、世界資源研究所(WRI)和世界自然基金會(WWF)四大組織於 2015 年共同發起，目的是鼓勵企業設定基於科學的減碳目標，以幫助全球溫控在 1.5℃的目標範圍內。","idx":240},{"id":"UP-L112-42","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"SBTi 的主要目標是為了符合哪個國際協議的目標？","options":{"A":"京都議定書","B":"蒙特利爾議定書","C":"瑞士議定書","D":"巴黎協定"},"answer":"D","explanation":"SBTi 的設立主要是為了支援《巴黎協定》的目標，即將全球平均溫度升幅控制在攝氏 1.5 度以內，通過幫助企業設定和達成科學基礎的減碳目標來實現。","idx":241},{"id":"UP-L112-43","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"SBTi 推動企業實現淨零排放的策略中，不包括以下哪項？","options":{"A":"僅依賴碳抵換","B":"通過設定近期目標來優先考慮快速且深度減排","C":"中和殘餘排放","D":"設定長期目標"},"answer":"A","explanation":"SBTi 強調企業達到淨零排放目標的過程中，需要進行實質減排，而不是僅依賴碳抵換。這意味著企業需要通過減少直接和間接的碳排放來實現減碳目標，碳抵換只能用於中和無法避免的剩餘排放。","idx":242},{"id":"UP-L112-44","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"SBTi 設定的減碳目標主要基於什麼標準？","options":{"A":"企業自定的目標","B":"政府規定的標準","C":"科學研究和全球碳預算","D":"行業平均水平"},"answer":"C","explanation":"SBTi 的減碳目標設定基於科學研究和全球碳預算，以確保企業的減碳行動與全球控制溫升至攝氏 1.5 度的目標一致。","idx":243},{"id":"UP-L112-45","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"SBTi 強調企業應該通過什麼方式達到淨零排放？","options":{"A":"僅依靠碳交易","B":"實質減排加上必要的碳抵換","C":"僅依賴碳抵換","D":"完全停止生產"},"answer":"B","explanation":"SBTi 強調企業達到淨零排放目標應該通過實質減排，並在必要時使用碳抵換，而不是僅依賴碳抵換。","idx":244},{"id":"UP-L112-46","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"根據 SBTi，企業設定的科學基礎減碳目標主要依據什麼？","options":{"A":"全球碳預算","B":"國家法律","C":"個別企業意願","D":"行業平均值"},"answer":"A","explanation":"SBTi 的科學基礎減碳目標是根據全球碳預算來設定的，這確保了企業的減排努力與控制全球溫度上升至 1.5℃的目標相符合。","idx":245},{"id":"UP-L112-47","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"SBTi 如何幫助企業在減碳過程中創新和整合氣候風險？","options":{"A":"通過提供金融激勵","B":"通過強制法律規定","C":"通過設定科學基礎的減排目標和推動低碳技術創新","D":"通過限制企業發展"},"answer":"C","explanation":"SBTi 通過幫助企業設定科學基礎的減排目標，鼓勵它們開發低碳技術和解決方案，從而在其業務決策中整合氣候風險和機會，推動向可持續發展轉型。","idx":246},{"id":"UP-L112-48","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"企業在申請設定科學基礎減排目標的第一步應該採取什麼行動？","options":{"A":"提交承諾信給 SBTi","B":"公開其碳排放量","C":"直接開始減排","D":"與利害關係人溝通"},"answer":"A","explanation":"申請設定科學基礎減排目標的第一步是向 SBTi 提交承諾信，表明企業的意圖設定基於科學的減排目標。這一步驟確保了企業的承諾得到組織的認可，並正式開始其設定減排目標的過程。","idx":247},{"id":"UP-L112-49","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"企業提交其 SBTi 減碳目標後，接下來的程序是什麼？","options":{"A":"立即開始減排活動","B":"等待官方驗證","C":"每月報告進度","D":"停止所有碳排放活動"},"answer":"B","explanation":"在企業提交其基於科學的減碳目標給 SBTi 後，接下來的步驟是等待 SBTi 團隊進行官方的審核，以確認這些目標是否符合資格。這一階段對於確保企業設定的目標具有科學基礎且可實現至關重要。","idx":248},{"id":"UP-L112-50","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"如何確保企業設定的科學基礎減排目標保持最新且有效？","options":{"A":"每 10 年重新設定一次目標","B":"目標一旦設定便永久有效","C":"只需在初次設定目標時審核","D":"每 5 年重新審核或調整目標"},"answer":"D","explanation":"為了確保企業設定的科學基礎減排目標保持與最新的科學研究和全球氣候行動目標一致，SBTi 要求企業每 5 年對其目標進行重新審核或調整。這一機制確保了企業的減排努力能夠持續對抗氣候變化，並隨著新科學發現和技術進步進行適當的更新。","idx":249},{"id":"UP-L112-51","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"RE100 倡議的主要目的是什麼？","options":{"A":"減少全球碳排放","B":"實現 100%使用再生能源","C":"增加全球溫度","D":"減少企業利潤"},"answer":"B","explanation":"RE100 旨在鼓勵和支持全球最有影響力的企業承諾在 2020 年至 2050 年間實現 100%使用再生能源的目標，以加速全球能源轉型和對抗氣候變化。","idx":250},{"id":"UP-L112-52","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"加入 RE100 的企業必須遵守的一項規範是什麼？","options":{"A":"每年消耗至少 100GWh 的化石燃料","B":"每年至少有 100GWh 的可再生能源需求","C":"每年減少 100GWh 的電力消耗","D":"每年增加 100GWh 的碳排放"},"answer":"B","explanation":"RE100 的一般規範要求加入的企業每年至少有 100GWh 的可再生能源需求，以確保參與企業對於推動再生能源使用具有顯著影響。","idx":251},{"id":"UP-L112-53","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"RE100 成員需要達成的目標之一是在哪一年達到 60%的可再生電力使用率？","options":{"A":"2020 年","B":"2030 年","C":"2040 年","D":"2050 年"},"answer":"B","explanation":"根據 RE100 的規範，成員企業需在 2030 年達到至少 60%的可再生電力使用率，作為達成 100%使用再生能源長期目標的階段性要求。","idx":252},{"id":"UP-L112-54","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"關於 RE100 成員的報告要求，下列描述哪一項是正確的？","options":{"A":"只需在加入時報告一次","B":"每十年報告一次進展","C":"不需要報告進展","D":"需要每年報告進展"},"answer":"D","explanation":"RE100 要求其成員企業每年報告其實現再生能源使用目標的進展，以確保透明度和可追蹤性。","idx":253},{"id":"UP-L112-55","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"哪些類型的公司將不被考慮加入 RE100？","options":{"A":"以再生能源為收入的公司","B":"從事化石燃料業的公司","C":"產生零碳排放的公司","D":"提供綠色科技解決方案的公司"},"answer":"B","explanation":"RE100 不會考慮那些從事化石燃料、航空公司、彈藥、賭博以及菸草業的公司加入，因為這些行業的本質與 RE100 推動的氣候行動目標不符。","idx":254},{"id":"UP-L112-56","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"如果一家公司的子公司想單獨加入 RE100，必須滿足什麼條件？","options":{"A":"與母公司切割有明確品牌且耗電量大於 1TWh/年","B":"與母公司合併","C":"子公司無需滿足任何條件","D":"子公司的耗電量少於 100GWh/年"},"answer":"A","explanation":"根據 RE100 的規範，子公司如果想單獨加入 RE100，必須與母公司在品牌上有明顯的區隔，且其耗電量需大於 1TWh/年。","idx":255},{"id":"UP-L112-57","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"RE100 成員在什麼情況下需要提前繳交採購計畫？","options":{"A":"加入後立即繳交","B":"不需要提前繳交","C":"達到目標後","D":"需要提前繳交採購計畫"},"answer":"D","explanation":"RE100 要求其成員在加入時需提前繳交一份關於如何達成 100%使用再生能源目標的採購計畫，以展示其達成目標的具體計畫和承諾。","idx":256},{"id":"UP-L112-58","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"到 2024 年 2 月，RE100 大約有多少家會員企業？","options":{"A":"100 家以上","B":"200 家以上","C":"400 家以上","D":"500 家以上"},"answer":"C","explanation":"截至 2024 年 2 月，RE100 已經匯聚了 428 家來自不同行業的全球領先企業，共同致力於實現 100%使用再生能源的目標。","idx":257},{"id":"UP-L112-59","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"RE100 的目標年份範圍是什麼？","options":{"A":"2015 年至 2025 年","B":"2020 年至 2050 年","C":"2025 年至 2045 年","D":"2030年至 2060 年"},"answer":"B","explanation":"RE100 的目標是鼓勵和支持企業在 2020 年至 2050 年間實現 100%使用再生能源的承諾，以促進能源轉型和應對氣候變化。","idx":258},{"id":"UP-L112-60","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"在 RE100 規範中，哪些類型的企業不會被視為企業會員？","options":{"A":"再生能源設備製造商","B":"再生能源開發商","C":"提供技術支持的公司","D":"提供再生能源解決方案的公司"},"answer":"B","explanation":"根據 RE100 的一般規範，除了製造可再生能源設備的公司外，那些以再生能源為主要收入來源的企業，如開發商和技術提供商，將不會被視為企業會員。","idx":259},{"id":"UP-L112-61","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"GRI 報告框架中，哪個準則提供了報告的基礎原則和報告過程？","options":{"A":"GRI 101：基礎","B":"GRI 102：一般揭露","C":"GRI 103：管理方法","D":"GRI行業準則"},"answer":"A","explanation":"GRI 101「基礎」是所有組織在進行 GRI 報告時必須遵守的首要準則，它提供了報告的目的、原則以及報告過程的概述，是建立報告框架的基石。","idx":260},{"id":"UP-L112-62","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"GRI 102：一般揭露涵蓋的範圍包括以下哪些方面？","options":{"A":"氣候變化影響","B":"組織概況和治理結構","C":"特定行業的環境影響","D":"員工福利管理"},"answer":"B","explanation":"GRI 102「一般揭露」關注於提供組織的背景資訊，包括組織概況、治理結構、策略等，以幫助利害關係人了解組織的運營背景。","idx":261},{"id":"UP-L112-63","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"以下哪個不是 GRI 報告框架的一部分？","options":{"A":"GRI 通用準則","B":"GRI 行業準則","C":"GRI 主題準則","D":"GRI 財務準則"},"answer":"D","explanation":"GRI 報告框架包括 GRI 通用準則、特定行業的 GRI 行業準則和特定主題內容的 GRI 主題準則，並沒有所謂的 GRI 財務準則。","idx":262},{"id":"UP-L112-64","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"GRI 103：管理方法準則的主要目的是什麼？","options":{"A":"評估組織財務績效","B":"報告組織的治理結構","C":"闡述如何管理特定經濟、環境和社會議題","D":"描述組織的員工福利政策"},"answer":"C","explanation":"GRI 103「管理方法」要求組織說明其如何識別、分析和回應其關鍵永續發展議題的過程，這包括組織的風險評估以及相應的管理策略和目標。","idx":263},{"id":"UP-L112-65","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"在 GRI 報告框架中，特定行業的 GRI 行業準則的作用是什麼？","options":{"A":"提供所有行業通用的報告原則","B":"提供針對特定行業特有議題的詳細報告指南","C":"僅適用於金融行業","D":"替代 GRI 通用準則"},"answer":"B","explanation":"GRI 行業準則旨在提供針對特定行業內特有的經濟、環境和社會影響議題的詳細報告指南，幫助該行業的組織更加精確地報告其永續發展績效。","idx":264},{"id":"UP-L112-66","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"特定主題內容的 GRI 主題準則主要關注什麼？","options":{"A":"組織內部治理結構","B":"全球氣候變化","C":"特定的經濟、環境或社會主題的詳細報告要求","D":"財務報告準則"},"answer":"C","explanation":"GRI 主題準則專注於特定的經濟、環境或社會主題，提供了關於如何報告這些特定議題的詳細指南和要求。","idx":265},{"id":"UP-L112-67","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"2021 年 GRI 更新的通用準則主要增強了哪方面的報告要求？","options":{"A":"財務績效","B":"產品創新","C":"盡職調查和人權","D":"市場營銷策略"},"answer":"C","explanation":"GRI 通用準則 2021 的更新主要是在內容結構與格式上進行調整，特別是增強了盡職調查和人權相關的報告要求，以促進更透明和全面的人權影響報告。","idx":266},{"id":"UP-L112-68","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"GRI 報告原則中，哪一項是關於報告品質的關鍵原則？","options":{"A":"準確性","B":"定時性","C":"可比性","D":"經濟指標"},"answer":"A","explanation":"準確性是 GRI 報告原則中關於報告質量的關鍵原則之一，要求組織在其永續發展報告中提供準確、清晰和可靠的資訊。","idx":267},{"id":"UP-L112-69","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"根據 GRI 準則，組織進行永續發展報告的首要目的是什麼？","options":{"A":"增加市場份額","B":"提高品牌形象","C":"透明地報告其經濟、環境和社會影響","D":"遵守政府法規"},"answer":"C","explanation":"GRI 準則的首要目的是幫助組織透明地報告其在經濟、環境和社會層面的影響，從而提高組織對永續發展的貢獻及其產生的負面衝擊的透明度和責任。","idx":268},{"id":"UP-L112-70","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"在 GRI 102：一般揭露中，組織需要提供哪些類型的資訊？","options":{"A":"僅財務資訊","B":"僅環境影響資訊","C":"組織概況、治理結構和策略等背景資訊","D":"僅社會責任活動"},"answer":"C","explanation":"GRI 102「一般揭露」要求組織提供關於其組織概況、治理結構、策略以及倫理和完整性等方面的資訊，以便利害關係人全面了解組織的運營背景及其對永續發展的整體承諾。","idx":269},{"id":"UP-L112-71","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"TCFD 的四大核心要素不包括以下哪一項？","options":{"A":"策略","B":"治理","C":"資產管理","D":"風險管理"},"answer":"C","explanation":"解釋：TCFD 的四大核心要素為治理、策略、風險管理，以及指標與目標。","idx":270},{"id":"UP-L112-72","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"下列哪項是 TCFD 的主要目標之一？","options":{"A":"強制企業削減所有碳排放","B":"增加氣候相關資訊的透明度","C":"減少氣候災害的發生","D":"統一全球氣候政策"},"answer":"B","explanation":"解釋：TCFD 旨在提高氣候相關風險與機會揭露的一致性和透明度，幫助投資者做出更明智的決策。","idx":271},{"id":"UP-L112-73","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"哪個國際機構於 2015 年成立了 TCFD 工作小組？","options":{"A":"聯合國","B":"世界銀行","C":"國際金融穩定委員會(FSB)","D":"國際貨幣基金組織(IMF)"},"answer":"C","explanation":"解釋：TCFD 是由國際金融穩定委員會(FSB)在 2015 年成立的。","idx":272},{"id":"UP-L112-74","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"TCFD 提出的「轉型風險」主要與以下哪一項相關？","options":{"A":"氣候災害的直接影響","B":"極端天氣的發生頻率","C":"低碳轉型對企業的影響","D":"長期的資產壽命管理"},"answer":"C","explanation":"解釋：轉型風險涉及低碳轉型過程中的政策法規、技術、市場和聲譽等衝擊。","idx":273},{"id":"UP-L112-75","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"TCFD 建議中，企業應採取以下何種情境進行分析？","options":{"A":"只需針對過去氣候數據","B":"使用假設的氣候相關情境","C":"無需情境分析","D":"只需進行短期情境分析"},"answer":"B","explanation":"解釋：TCFD 鼓勵企業採用假設的氣候情境進行分析，以評估策略的韌性。","idx":274},{"id":"UP-L112-76","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"歐盟碳排放交易體系(EU ETS)自何年開始實施？","options":{"A":"2000 年","B":"2005 年","C":"2010 年","D":"2015 年"},"answer":"B","explanation":"歐盟碳排放交易體系(EU ETS)自 2005 年開始實施，是全球最大的碳排放交易市場，目的在於透過市場機制控制溫室氣體排放量。","idx":275},{"id":"UP-L112-77","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CBAM 的主要目的是什麼？","options":{"A":"降低歐盟內部的碳排放量","B":"增加歐盟的稅收","C":"防範碳洩漏","D":"促進可再生能源的使用"},"answer":"C","explanation":"CBAM 的設計目的是為了防範碳洩漏，即防止生產活動從歐盟轉移到排放標準較寬鬆的國家，從而確保歐盟生產商在全球市場上的競爭力。","idx":276},{"id":"UP-L112-78","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"歐盟計劃從哪一年開始逐漸取消 ETS 的免費排放配額？","options":{"A":"2020 年","B":"2023 年","C":"2026 年","D":"2034 年"},"answer":"C","explanation":"從 2026 年開始至 2034 年，歐盟計劃逐漸取消其產業獲得的 ETS 免費排放配額，此舉旨在進一步推動減排並促進清潔能源的使用。","idx":277},{"id":"UP-L112-79","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CBAM 規定，過渡期後進口商必須在每年的哪一天前繳交足夠的 CBAM 憑證？","options":{"A":"1 月 1 日","B":"3 月 31 日","C":"5 月 31 日","D":"12 月 31 日"},"answer":"C","explanation":"歐盟進口商必須於每年 5 月 31 日前向主管機關繳交足以抵銷前一年進口產品總碳含量之 CBAM 憑證。","idx":278},{"id":"UP-L112-80","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CBAM 憑證的價格是根據什麼來確定？","options":{"A":"歐盟委員會的固定價格","B":"每年的歐盟預算","C":"歐盟 ETS 排放額度拍賣的平均價格","D":"國際碳價"},"answer":"C","explanation":"CBAM 憑證的價格是根據當週歐盟 ETS 排放額度拍賣的平均價格來確定的，如果當週無拍賣，則使用上一週的平均結標價格。","idx":279},{"id":"UP-L112-81","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CBAM 過渡期間是從哪一年開始到哪一年結束？","options":{"A":"2020 年至 2023 年","B":"2021 年至 2024 年","C":"2023 年至 2025 年","D":"2026年至 2030 年"},"answer":"C","explanation":"CBAM 的過渡期間從 2023 年 10 月 1 日開始，至 2025 年結束，主要讓各國業者有充裕的時間準備因應 CBAM 的施行。","idx":280},{"id":"UP-L112-82","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"根據歐盟 CBAM，進口商必須申報其貨品內的產品碳含量的基礎是什麼？","options":{"A":"僅直接排放","B":"僅間接排放","C":"直接排放與間接排放","D":"生產效率"},"answer":"C","explanation":"進口商必須申報其貨品內產品的碳含量，包括直接排放(即生產過程產生的排放)及間接排放(如消耗的電力所產生的排放)。","idx":281},{"id":"UP-L112-83","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"若進口產品的實際排放量無法被充分確定， CBAM 的排放量計算應使用什麼？","options":{"A":"實際排放量","B":"預設值","C":"最低排放量","D":"最高排放量"},"answer":"B","explanation":"當進口產品的實際排放量無法被充分確定時，應使用預設值進行排放量的計算。","idx":282},{"id":"UP-L112-84","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"歐盟 CBAM 對於哪些產品實施了特定的排放強度計算方法？","options":{"A":"電力","B":"簡單商品與複雜商品","C":"僅限於鋼鐵和水泥","D":"所有進口產品"},"answer":"B","explanation":"歐盟 CBAM 針對簡單商品和複雜商品提出了特定的排放強度計算方法，以考慮其生產過程中的直接和間接碳排放。","idx":283},{"id":"UP-L112-85","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"CBAM 報告中，報告申報者需提供的資訊不包括下列哪項？","options":{"A":"進口產品的數量","B":"產品的 CN 代碼","C":"進口產品的價格","D":"生產設施的主要排放源地理座標"},"answer":"C","explanation":"CBAM 報告要求報告申報者提供進口產品的數量、產品類型的 CN 代碼、產品的原產國、生產設施資訊等，但不要求提供進口產品的價格。","idx":284},{"id":"UP-L112-86","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"臺灣 2050 淨零排放策略的主要目標是什麼？","options":{"A":"增加工業產出","B":"達到淨零溫室氣體排放","C":"加倍能源消耗","D":"減少經濟成長"},"answer":"B","explanation":"達到淨零溫室氣體排放。","idx":285},{"id":"UP-L112-87","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"在實現 2050 年淨零排放目標中，哪個部門被認為是轉型的關鍵領域？","options":{"A":"旅遊","B":"農業","C":"能源和工業","D":"教育"},"answer":"C","explanation":"能源和工業。","idx":286},{"id":"UP-L112-88","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"在臺灣的淨零排放策略中，再生能源扮演什麼角色？","options":{"A":"次要重要性","B":"無角色","C":"主要重要性","D":"將被淘汰"},"answer":"C","explanation":"主要重要性。","idx":287},{"id":"UP-L112-89","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"至 2025 年，關於再生能源安裝的具體目標是什麼？","options":{"A":"5GW 的核能","B":"20GW 的太陽能","C":"10GW 的煤炭能力","D":"15GW 的天然氣"},"answer":"B","explanation":"20GW 的太陽能。","idx":288},{"id":"UP-L112-90","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"臺灣計劃如何解決交通部門的排放問題？","options":{"A":"增加私人車輛的使用","B":"逐步淘汰電動車","C":"擴大綠色公共交通","D":"減少公共交通網絡"},"answer":"C","explanation":"擴大綠色公共交通。","idx":289},{"id":"UP-L112-91","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"工業部門轉型向淨零排放的關鍵策略是什麼？","options":{"A":"降低能效","B":"增加對煤炭的依賴","C":"創新與綠色技術採納","D":"減少出口"},"answer":"C","explanation":"創新與綠色技術採納。","idx":290},{"id":"UP-L112-92","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"臺灣的長期淨零過渡中，哪項技術被提及為關鍵？","options":{"A":"區塊鏈","B":"碳捕獲與封存(CCUS)","C":"傳統的煤電廠","D":"柴油引擎"},"answer":"B","explanation":"碳捕獲與封存(CCUS)。","idx":291},{"id":"UP-L112-93","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"至 2030 年，台灣 NDC 的減排目標比 2005 年減少多少百分比？","options":{"A":"減少 10%","B":"減少 24%","C":"增加 1%","D":"減少 24%+-1%"},"answer":"D","explanation":"台灣 2030 年國家自主貢獻（NDC）目標為相較基準年 2005 年減少 24%±1%，故選 D；選項 B「24%」未含官方公布之 ±1% 區間。","idx":292},{"id":"UP-L112-94","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"在臺灣的淨零排放策略中，綠色金融扮演什麼角色？","options":{"A":"減少對綠色項目的投資","B":"為轉型到可持續經濟提供資金","C":"支持石化工業","D":"無明確角色"},"answer":"B","explanation":"為轉型到可持續經濟提供資金。","idx":293},{"id":"UP-L112-95","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"在非電力能源去碳化方面，臺灣計劃採取哪些措施來取代化石燃料？","options":{"A":"僅加速電氣化進程","B":"僅投入生質能開發","C":"投入氫能與生質能開發，並搭配碳捕捉再利用及封存技術","D":"僅使用氫能"},"answer":"C","explanation":"投入氫能與生質能開發，並搭配碳捕捉再利用及封存技術。","idx":294},{"id":"UP-L112-96","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"總量管制排放交易主要目的是什麼？","options":{"A":"增加企業稅收","B":"減少溫室氣體排放","C":"促進國際貿易","D":"增加政府監管"},"answer":"B","explanation":"總量管制排放交易，旨在通過設定溫室氣體排放上限並允許排放權交易來減少溫室氣體排放。","idx":295},{"id":"UP-L112-97","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"在總量管制排放交易中，如果一個組織減少了碳排放，它可以如何利用多餘的配額？","options":{"A":"減排行動計畫","B":"市場營銷策略","C":"投資回報分析","D":"員工培訓計畫"},"answer":"B","explanation":"在總量管制交易中，組織如果減少了碳排放，可以將多餘的配額出售給那些排放量超過自身配額的組織。","idx":296},{"id":"UP-L112-98","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"我國如果課徵碳稅通常由哪個部門徵收？","options":{"A":"環境部","B":"財政部","C":"金管會","D":"行政院"},"answer":"B","explanation":"碳稅通常由國家的財政部門徵收，我國則為財政部，其收入成為政府的一部分財政收入。","idx":297},{"id":"UP-L112-99","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"碳費的使用範圍通常在哪裡有明確規定？","options":{"A":"國際條約","B":"個人協議","C":"法律中","D":"新聞報導"},"answer":"C","explanation":"碳費的使用範圍通常在法律中有明確規定，專款專用於減少碳排放和氣候變化相關的活動。","idx":298},{"id":"UP-L112-100","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"碳稅與碳費的主要區別在於什麼？","options":{"A":"徵收金額","B":"徵收對象","C":"徵收機關和資金的使用彈性","D":"影響的行業範圍"},"answer":"C","explanation":"碳稅與碳費的主要區別在於徵收機關不同、資金的使用彈性不同。碳稅通常由財政部門徵收，其收入可以用於廣泛的政府支出；而碳費通常由環保相關部門徵收，專款專用於減少碳排放和氣候變化相關的活動。","idx":299},{"id":"UP-L112-101","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"內部碳定價的一種實施方式是對內部產生的每噸二氧化碳排放徵收一定的費用，這稱為什麼模式？","options":{"A":"碳稅模式","B":"碳交易模式","C":"影子碳定價","D":"自願減量模式"},"answer":"A","explanation":"碳稅模式是內部碳定價的一種實施方式，其中企業為自身的碳排放設定一個固定的價格，即對內部產生的每噸二氧化碳排放徵收碳稅。","idx":300},{"id":"UP-L112-102","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"碳費試申報不繳費的年份是？","options":{"A":"113 年","B":"114 年","C":"115 年","D":"116 年"},"answer":"B","explanation":"碳費試申報不繳費的年份為 114 年，讓企業有足夠時間準備並評估減量計畫。115 年則開始依排放量及費率繳費。","idx":301},{"id":"UP-L112-103","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"碳信用額度需要在哪裡註冊以確保其獨一無二？","options":{"A":"國際貿易組織","B":"專門的登錄處","C":"國家環保機構","D":"私人交易平台"},"answer":"B","explanation":"碳信用（額度）須於專門的登錄處（登錄／註冊系統）登錄編號，以確保每單位額度可追溯、獨一無二且避免重複計算，故選 B。","idx":302},{"id":"UP-L112-104","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"以下哪一項是台灣碳權交易所的主要特色之一？","options":{"A":"採用台幣計價交易平台","B":"買賣雙方可使用個人帳戶交易","C":"採「信託帳戶」保障交易安全","D":"減量專案效益發生年度可距申請上架超過 10 年"},"answer":"C","explanation":"台灣碳權交易所的特色包括採用美元計價、使用信託帳戶保障交易安全，以及子帳戶架構管理平台。選項 A、B、D 與事實不符。","idx":303},{"id":"UP-L112-105","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"以下哪一項不符合台灣碳權交易所的上架標準？","options":{"A":"符合黃金標準(GS)或碳驗證標準(Verra)","B":"減量效益與申請上架年度相距超過 5 年","C":"符合聯合國永續發展目標(SDGs)至少 3 項","D":"排除爭議性或不宜上架的專案"},"answer":"B","explanation":"碳交所上架標準要求減量效益發生年度距申請上架年度不得超過 5 年，選項 B不符合規範。","idx":304},{"id":"UP-L112-106","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"ISO 14068-1 碳中和標準於哪一年推出？","options":{"A":"2020","B":"2021","C":"2022","D":"2023"},"answer":"D","explanation":"ISO 14068-1 是國際標準組織於 2023 年推出的碳中和標準，為全球企業和實體提供了一套系統性的框架，取代 PAS 2060。","idx":305},{"id":"UP-L112-107","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"ISO 14068-1 的核心目的是什麼？","options":{"A":"提供國家碳排放報告的統一格式","B":"透過量化、減排和碳抵換實現碳中和","C":"將所有碳足跡數據轉化為經濟指標","D":"減少國際間碳排放報告的數據衝突"},"answer":"B","explanation":"透過量化溫室氣體排放、減排及碳抵換來實現碳中和，並指導企業如何透明地宣示碳中和目標。","idx":306},{"id":"UP-L112-108","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"ISO 14068-1 強調碳中和應優先考慮哪一項？","options":{"A":"直接與間接溫室氣體減排和移除","B":"增加碳抵換的使用比例","C":"將重點放在範疇 3 排放上","D":"簡化減排路徑的規劃"},"answer":"A","explanation":"該標準強調優先進行價值鏈內的直接與間接溫室氣體減排和移除，並盡量減少對碳抵消的依賴，確保碳中和的實踐更具真實性。","idx":307},{"id":"UP-L112-109","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"ISO 14068-1 如何確保碳中和的實踐具備可信度？","options":{"A":"強制所有企業使用 ISO 14064-1 進行盤查","B":"透過第三方查證和透明溝通","C":"優先推動碳交易市場的發展","D":"將碳抵換作為主要實現手段"},"answer":"B","explanation":"為了提升碳中和的可信度，ISO 14068-1 要求通過第三方查證，並以透明方式向利害關係人溝通成果，確保資訊的準確性與可信性。","idx":308},{"id":"UP-L112-110","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"ISO 14068-1 的適用範圍中，下列哪一項不包括？","options":{"A":"金融機構","B":"地方政府","C":"商品或服務","D":"領土(如國家或城市)"},"answer":"D","explanation":"ISO 14068-1 適用於組織(如公司和地方政府)與產品(如商品或服務)，但不適用於領土(如國家或城市)，因其涉及國際協議如 UNFCCC 的專屬框架。","idx":309},{"id":"UP-L112-111","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"根據 ISO 14068-1，溫室氣體盤查的數據來源可以基於以下哪一項標準？","options":{"A":"ISO 14064-1 和 ISO 14067","B":"ISO 14001 和 ISO 50001","C":"GHG Protocol和 ISO 9001","D":"PAS 2060 和 ISO 14064-2"},"answer":"A","explanation":"ISO 14068-1 建議使用 ISO 14064-1(組織層級排放盤查)與 ISO 14067(產品碳足跡)作為溫室氣體盤查的數據來源。","idx":310},{"id":"UP-L112-112","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"ISO 14068-1 碳中和管理計畫的規劃應包含哪些內容？","options":{"A":"高層承諾聲明與基準年設定","B":"減少碳足跡的階段性目標","C":"碳權使用量的預期規劃","D":"以上皆是"},"answer":"D","explanation":"碳中和管理計畫應涵蓋高層承諾聲明、基準年設定、排放量盤查、短期與長期減量目標、碳抵換計畫等，以確保整體碳中和路徑的系統性。","idx":311},{"id":"UP-L112-113","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"在 ISO 14068-1 中，至少多久需要重新量化溫室氣體排放量？","options":{"A":"每半年","B":"每年","C":"每兩年","D":"每三年"},"answer":"B","explanation":"根據 ISO 14068-1，組織應至少每年對溫室氣體排放量進行重新盤查，確保數據的時效性與準確性。","idx":312},{"id":"UP-L112-114","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"ISO 14068-1 強調碳中和應採取什麼樣的方法？","options":{"A":"生命週期和價值鏈的全面方法","B":"專注於短期內的碳交易策略","C":"忽略間接排放的影響","D":"依賴單一的減碳技術"},"answer":"A","explanation":"ISO 14068-1 要求採用生命週期和價值鏈的全面方法，即考慮產品或服務全生命周期的碳排放，並包含上下游供應鏈的減排。","idx":313},{"id":"UP-L112-115","source":"unit_practice","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"ISO 14068-1 提供的碳中和聲明需包含以下哪些資訊？","options":{"A":"碳中和範疇與邊界","B":"碳足跡量及抵換量","C":"查證人及查證日期","D":"以上皆是"},"answer":"D","explanation":"碳中和聲明應包含範疇與邊界、碳足跡數據(排放量、移除量)、碳抵換措施、查證資訊等，確保聲明內容透明且全面。","idx":314},{"id":"UP-L121-01","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"溫室氣體盤查報告原則“不”包括以下哪項？","options":{"A":"準確性","B":"一致性","C":"極大化","D":"完整性"},"answer":"C","explanation":"溫室氣體盤查報告原則包含相關性、完整性、一致性、準確性、透明度。","idx":315},{"id":"UP-L121-02","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"溫室氣體盤查報告原則中，何者是為了使溫室氣體相關資訊能有意義比較，以及容許有意義的跨年度或同產業排放比較？","options":{"A":"準確性","B":"一致性","C":"完整性","D":"透明度"},"answer":"B","explanation":"一致性：能對溫室氣體相關資訊進行有意義之比較。","idx":316},{"id":"UP-L121-03","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"依據標準組織型溫室氣體盤查須納入所有相關的溫室氣體排放與移除。其遵循的盤查原則是？","options":{"A":"準確性","B":"完整性","C":"一致性","D":"相關性"},"answer":"B","explanation":"完整性：納入所有相關的溫室氣體排放與移除。","idx":317},{"id":"UP-L121-04","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"企業進行溫室氣體盤查的第一步是什麼？","options":{"A":"設定邊界鑑別排放源","B":"收集活動數據與計算排放量","C":"請高階主管指派溫室氣體盤查小組","D":"文件化紀錄"},"answer":"C","explanation":"進行溫室氣體盤查的首要步驟是獲得組織內部的支持和資源分配，高階主管的支持對於確保盤查工作得到必要的重視和資源至關重要。","idx":318},{"id":"UP-L121-05","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"在進行溫室氣體盤查時，如何確保報告的完整性？","options":{"A":"報告主要排放源","B":"僅關注直接排放","C":"包括所有相關的直接和間接排放源","D":"忽略間接排放源"},"answer":"C","explanation":"在溫室氣體盤查中應納入所有相關的直接和間接排放源，以提供全面的溫室氣體排放和移除量。","idx":319},{"id":"UP-L121-06","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"組織如何確保其溫室氣體盤查的一致性，以便於時間上的比較？","options":{"A":"每年更換計算方法","B":"維持使用相同的數據來源和計算方法","C":"僅報告最大的排放源","D":"忽略小規模排放源"},"answer":"B","explanation":"一致性原則，即應保持數據來源和計算方法的一致性，以便於進行準確的時間序列比較。","idx":320},{"id":"UP-L121-07","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"組織在溫室氣體報告中如何體現透明度原則？","options":{"A":"僅報告對組織有利的信息","B":"隱藏計算方法","C":"充分且適當地揭露溫室氣體相關資訊","D":"避免公開不確定性數據"},"answer":"C","explanation":"在報告中應充分且適當地揭露溫室氣體相關資訊，使預期使用者能夠作出合理且可信的決策。","idx":321},{"id":"UP-L121-08","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"選擇溫室氣體報告中數據和方法的過程中，應依據什麼原則來確保其相關性？","options":{"A":"報告所有可能的數據","B":"基於預期使用者的需求選擇相關的溫室氣體源和匯","C":"僅報告國際間公認的溫室氣體","D":"避免使用地方性的溫室氣體數據"},"answer":"B","explanation":"選擇與預期使用者需求相關的溫室氣體源、匯、儲存庫、數據及方法，以確保報告的實用性和有效性。","idx":322},{"id":"UP-L121-09","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"溫室氣體報告的一般原則旨在確保什麼？","options":{"A":"報告僅包含正面影響","B":"資訊經過真實公正的考量","C":"報告僅限於公開資料","D":"忽略小規模排放源的影響"},"answer":"B","explanation":"溫室氣體報告一般原則的核心，即確保報告中的資訊經過真實和公正的考量，以提高報告的可信度和準確性。","idx":323},{"id":"UP-L121-10","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"下列何項標準規定組織層級對溫室氣體(GHG)排放與移除之量化報告之原則與要求事項？","options":{"A":"ISO 14064-1","B":"ISO 14064-2","C":"ISO 14067","D":"ISO 14064-3"},"answer":"A","explanation":"ISO 14064-1 規定組織層級對溫室氣體(GHG)排放與移除之量化報告之原則與要求事項。","idx":324},{"id":"UP-L121-11","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"依據標準溫室氣體彙總方法包含以下幾項？","options":{"A":"財務控制法","B":"營運控制法","C":"股權持分法","D":"以上皆是"},"answer":"D","explanation":"彙總分法包含財務控制權、營運控制權、股權持分法。","idx":325},{"id":"UP-L121-12","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"依據環境部盤查作業指引要求，我國列管事業應以何種方式進行溫室氣體彙總方法？","options":{"A":"財務控制法","B":"營運控制法","C":"股權持分法","D":"以上皆可"},"answer":"B","explanation":"營運控制法。","idx":326},{"id":"UP-L121-13","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"下列何者非 ISO14064-1:2018 強制要求應揭露項目？","options":{"A":"生物源溫室氣體排放","B":"生物源二氧化碳移除之處理","C":"電力之處理方式","D":"產生自化石與生質碳之 GHG 排放與移除"},"answer":"D","explanation":"在溫室氣體盤查類別中，非生物源排放、人微生物源排放及非人微生物源排放，若量化與報告應分別計算。","idx":327},{"id":"UP-L121-14","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"請問 A 公司燃燒天然氣鍋爐產生蒸氣以供場外廠商使用，請問這是屬於何種類別排放？","options":{"A":"類別 1 直接溫室氣體排放","B":"類別 2 來自輸入能源之間接溫室氣體排放量","C":"類別 3 來自運輸之間接溫室氣體排放量","D":"類別 4 來自組織使用的產品之間接溫室氣體排放量"},"answer":"A","explanation":"類別 1 直接溫室氣體排放。","idx":328},{"id":"UP-L121-15","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"請問 B 公司引進隔壁廠商燃燒天然氣鍋爐產生的蒸氣作為製程使用，請問這是屬於何種類別排放？","options":{"A":"類別 1 直接溫室氣體排放","B":"類別 2 來自輸入能源之間接溫室氣體排放量","C":"類別 3 來自運輸之間接溫室氣體排放量","D":"類別 4 來自組織使用的產品之間接溫室氣體排放量"},"answer":"B","explanation":"類別 2 來自輸入能源之間接溫室氣體排放量。","idx":329},{"id":"UP-L121-16","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"C 公司在溫室氣體盤查報告書提到盤查的範圍包含桃園廠與小港廠。依據 ISO14064-1:2018 最新條文規範，請問這段描述內容描述的是界定何種邊界？","options":{"A":"組織邊界","B":"營運邊界","C":"報告邊界","D":"系統邊界"},"answer":"A","explanation":"組織邊界。","idx":330},{"id":"UP-L121-17","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"ISO 14064-1:2018 界定全球暖化潛勢(GWP)的溫室氣體(GHG)中，下列何者為非？","options":{"A":"二氧化碳","B":"氦氣","C":"氧化亞氮","D":"六氟化硫"},"answer":"B","explanation":"溫室氣體包含二氧化碳、甲烷、氧化亞氮、三氟化氮、六氟化硫、氫氟碳化物、全氟碳化物。","idx":331},{"id":"UP-L121-18","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"在溫室氣體盤查中，組織邊界的設定可能根據什麼來進行？","options":{"A":"法規要求","B":"國際供應鏈需求","C":"組織的財務控制權法","D":"公眾的意見反應"},"answer":"C","explanation":"組織在確定盤查邊界時，可能根據其財務控制權法、營運控制權法或股權比例法來設定邊界。","idx":332},{"id":"UP-L121-19","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"組織在建立報告邊界時，應該包含哪些內容？","options":{"A":"直接溫室氣體排放和移除量","B":"來自輸入能源的間接溫室氣體排放量","C":"來自組織使用的產品的間接溫室氣體排放量","D":"以上皆是"},"answer":"D","explanation":"報告邊界應該包含直接溫室氣體排放和移除量、來自輸入能源的間接溫室氣體排放量，以及來自組織使用的產品的間接溫室氣體排放量。","idx":333},{"id":"UP-L121-20","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"在溫室氣體盤查中，哪一項不是間接溫室氣體排放與移除的來源之一？","options":{"A":"來自輸入能源的間接溫室氣體排放量","B":"來自組織使用的產品的間接溫室氣體排放量","C":"來自運輸的間接溫室氣體排放量","D":"來自直接排放源的間接溫室氣體排放量"},"answer":"D","explanation":"直接排放源不屬於間接溫室氣體排放的來源之一。","idx":334},{"id":"UP-L121-21","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"下列何種情況下無須重新計算基準年溫室氣體盤查清冊？","options":{"A":"報告邊界改變","B":"與隔壁廠房合併","C":"量化方法改變導致溫室氣體排放量發生很大改變","D":"生產產量發生重大變化"},"answer":"D","explanation":"生產產量發生重大變化無須重新計算基準年。","idx":335},{"id":"UP-L121-22","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"請說明溫室氣體量化方法中，排放係數法的計算公式，何者正確？","options":{"A":"CO2 排放當量 = 活動數據 × 排放係數 × GWP","B":"CO2 排放當量 =活動數據 × 人口數量 × GWP","C":"CO2 排放當量 = 活動數據 × 面積占比 × GWP","D":"CO2 排放當量 = 活動數據 × 重量占比 × GWP"},"answer":"A","explanation":"CO2e 排放當量 = 活動數據 × 排放係數 × GWP。","idx":336},{"id":"UP-L121-23","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"下列哪種類排放係數的不確定性最高？","options":{"A":"國際排放係數","B":"量測/質能平衡係數","C":"區域排放係數","D":"國家排放係數"},"answer":"A","explanation":"國際排放係數。","idx":337},{"id":"UP-L121-24","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"進行溫室氣體排放量計算時所引用的 IPCC 全球暖化潛勢值得選用時，應挑選對環境影響幾年的？","options":{"A":"50 年","B":"100 年","C":"200 年","D":"500 年"},"answer":"B","explanation":"全球暖化潛勢時間界限應為 100 年。","idx":338},{"id":"UP-L121-25","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"當組織進行溫室氣體源與匯的鑑別時，以下哪項做法是必須的？","options":{"A":"僅考慮直接排放源","B":"忽略所有間接排放源","C":"文件化納入所有相關的溫室氣體排放與移除","D":"僅關注能源消耗相關的排放"},"answer":"C","explanation":"組織應鑑別並文件化納入報告邊界內所有相關的溫室氣體源與匯，包括直接排放、能源間接排放以及其他間接排放，以確保溫室氣體盤查的完整性和準確性。","idx":339},{"id":"UP-L121-26","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"直接監測法的特點是下列何者？","options":{"A":"成本低廉且易於實施","B":"準確度較高但少見","C":"常用於計算間接排放","D":"基於估算而非實際測量"},"answer":"B","explanation":"直接監測法雖然提供較高的準確度，但由於成本、技術複雜性等因素，這種方法在實際應用中相對較少見。","idx":340},{"id":"UP-L121-27","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"下列何種量化方法可以直接監測排氣濃度和流率來量測溫室氣體排放量？","options":{"A":"直接監測法","B":"質量平衡法","C":"排放係數法","D":"估算方法"},"answer":"A","explanation":"組織可採用直接測量溫室氣體排放的濃度和流率，提供高準確度的數據，適用於需要精確溫室氣體排放量計算的情況。","idx":341},{"id":"UP-L121-28","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"組織建立基準年溫室氣體排放量與移除量的歷史基準時，應考慮哪些因素？","options":{"A":"選擇公司創立年作為基準年","B":"使用代表性且可驗證的數據","C":"僅基於預算決定","D":"選擇任意一年作為基準年"},"answer":"B","explanation":"選擇基準年時，應使用能代表組織現行報告邊界且可取得查證的數據，這確保了基準年的選擇具有代表性和可靠性。","idx":342},{"id":"UP-L121-29","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"公司今年耗用乙炔(C2H2，分子量 26)共 200 公斤，用於金屬熔接作業。請問依質量平衡法計算，此作業共排放多少公斤的二氧化碳？","options":{"A":"676.9230 公斤","B":"338.4610 公斤","C":"67.6920 公斤","D":"以上皆非"},"answer":"A","explanation":"2C2H2+5O2 →4CO2 +2H2O 每 2kg 的乙炔燃燒會產生 4 kg 的二氧化碳。乙炔的排放係數為 88/26 = 3.3846153846(取到小數點後 10 位)，200kg×3.3846153846=676.9230kg CO2(取到小數點後 4 位)。","idx":343},{"id":"UP-L121-30","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"公司使用含碳量 5%的焊條進行熔接作業，共使用 500 公斤焊條。依質量平衡法計算，請問此作業共排放多少公斤的二氧化碳？假設所有碳均完全轉化為二氧化碳(C 原子量 12，O 原子量 16)。","options":{"A":"91.6667 公斤","B":"100.0000 公斤","C":"183.3333 公斤","D":"19.6667 公斤"},"answer":"A","explanation":"焊條中碳的含量 500kg×5%=25kg 的碳，C+O2 → CO2，每 1kg 的碳燃燒會產生 1kg 的二氧化碳。排放係數為 44/12=3.6666666667(取到小數點後 10 位)，25.0000kg×3. 6666666667=91.6667kg CO2 (取到小數點後 4 位)。","idx":344},{"id":"UP-L122-31","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"碳足跡量化資訊應於碳足跡研究報告中揭露，以下何者可以不包含於報告之中？","options":{"A":"針對電力之處理","B":"選定的分配方法","C":"功能單位或宣告單位","D":"執行時間"},"answer":"D","explanation":"碳足跡研究報告中揭露中無須包含執行時間。","idx":345},{"id":"UP-L122-32","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"碳足跡量化資訊應於碳足跡研究報告中揭露，以下何者應包含於報告之中？","options":{"A":"數據收集資訊，包括數據來源","B":"生產排程","C":"內外部議題","D":"審查會議結論"},"answer":"A","explanation":"數據收集資訊，包括數據來源應包含於碳足跡研究報告中揭露中。","idx":346},{"id":"UP-L122-33","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"產品碳足跡計算中的生命週期評估主要是依據哪份 ISO 標準文件？","options":{"A":"ISO 14040","B":"ISO 50001","C":"ISO 9001","D":"ISO 14064-1"},"answer":"A","explanation":"產品碳足跡計算中的生命週期評估主要是依據 ISO 14040 & ISO 14044。","idx":347},{"id":"UP-L122-34","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在組織邊界外所獲得的數據稱之為？","options":{"A":"初級數據","B":"次級數據","C":"場址特定數據","D":"網路資料庫數據"},"answer":"B","explanation":"非初級數據者皆為次級數據。","idx":348},{"id":"UP-L122-35","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"產品碳足跡(CFP)量化時，為何需要考慮產品/活動的整個生命週期？","options":{"A":"降低成本","B":"簡化分析過程","C":"確保量化結果的全面性和準確性","D":"增加報告的頁數"},"answer":"C","explanation":"生命週期觀點原則，強調考量產品從原物料取得、設計、製造、運輸/配送、使用到生命終結處理階段的整個過程，以確保 CFP 量化結果能全面反映產品對環境影響的真實情況。","idx":349},{"id":"UP-L122-36","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"CFP 研究中，功能單位或宣告單位的主要目的是什麼？","options":{"A":"減少數據量","B":"提供與其相關投入與產出之參考","C":"增加報告的複雜度","D":"僅為了滿足標準要求"},"answer":"B","explanation":"功能單位或宣告單位提供了一個明確的參考點，用於量化和比較產品系統的環境影響，使得 CFP 研究的結果可被合理地評估和比較。","idx":350},{"id":"UP-L122-37","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"CFP 研究中，當需要做出決定時，為什麼應優先參照自然科學方法？","options":{"A":"自然科學方法成本較低","B":"增加研究的創新性","C":"保證結果的客觀性和可靠性","D":"簡化研究過程"},"answer":"C","explanation":"科學方法之優先性原則，強調在 CFP 研究中，應優先採用自然科學(如物理、化學、生物學)的方法來確保決策的客觀性和結果的可靠性。","idx":351},{"id":"UP-L122-38","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"CFP 研究如何確保完整性？","options":{"A":"僅關注主要 GHG 排放源","B":"忽略不重要的 GHG 排放源","C":"納入所有重大 GHG 排放與移除量","D":"僅計算直接排放"},"answer":"C","explanation":"完整性要求研究必須包含對系統中所有重要 GHG 排放與移除的全面考慮，以確保 CFP 的全面性和準確性。","idx":352},{"id":"UP-L122-39","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在 CFP 研究報告中，透明度原則要求什麼？","options":{"A":"僅報告最終結果","B":"不揭露敏感數據","C":"適當揭露假設、方法及數據的使用","D":"避免使用專業術語"},"answer":"C","explanation":"在 CFP 研究報告中應清楚說明所有相關假設、所使用的方法和數據，以便讀者能夠理解研究過程並對結果進行合理評估。","idx":353},{"id":"UP-L122-40","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在 CFP 研究中，如何避免 GHG 排放與移除的重複計算？","options":{"A":"忽略所有間接排放","B":"僅計算一次相同的 GHG 排放與移除","C":"重複計算所有排放源","D":"僅關注直接排放"},"answer":"B","explanation":"在 CFP 研究中，相同的 GHG 排放與移除應僅被分配並計算一次，避免對系統內 GHG 排放與移除的重複計算，確保結果的準確性。","idx":354},{"id":"UP-L122-41","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"碳足跡是針對一項活動或產品整個生命週期過程所直接與間接產生的溫室氣體，下列何者須計算？","options":{"A":"原料取得","B":"製造階段","C":"配送階段","D":"以上皆須計算"},"answer":"D","explanation":"生命週期包含原料取得、製造、配送/零售、使用、廢棄階段。","idx":355},{"id":"UP-L122-42","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"產品碳足跡過程盤查中，繪製製程地圖是一關鍵步驟，針對此一步驟以下描述何者為非？","options":{"A":"列出流程各關卡負責單位與人員","B":"列出流程內的投入與產出","C":"確定繪製標的及其功能/宣告單位","D":"列出製造產品，須經過哪些步驟"},"answer":"A","explanation":"繪製製程地圖須確認標的、功能單位、經過哪些步驟及每個流程的投入與產出。","idx":356},{"id":"UP-L122-43","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"以下何者是需被納入 B2C 產品碳足跡計算，但 B2B 產品不需被納入的生命週期階段","options":{"A":"產品使用階段","B":"原料取得階段","C":"生產製造階段","D":"以上皆須列入計算"},"answer":"A","explanation":"產品使用階段。","idx":357},{"id":"UP-L122-44","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"以下何者為 B2C 產品在生命週期的描述方式？","options":{"A":"從搖籃到大門","B":"從搖籃到墳墓","C":"從搖籃到天堂","D":"以上皆非"},"answer":"B","explanation":"從搖籃到墳墓。","idx":358},{"id":"UP-L122-45","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"以下何者為 B2B 產品在生命週期的描述方式？","options":{"A":"從搖籃到大門","B":"從搖籃到墳墓","C":"從搖籃到天堂","D":"以上皆非"},"answer":"A","explanation":"從搖籃到大門。","idx":359},{"id":"UP-L122-46","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在建構產品生命週期製程流程圖的第一步應該是什麼？","options":{"A":"選擇適當的製程技術","B":"確定繪製的對象與功能單位","C":"蒐集廢棄物處理的數據","D":"計算能源消耗量"},"answer":"B","explanation":"確定繪製的對象與功能單位是建立生命週期製程流程圖的基礎，確保整個分析的焦點和參考點明確，以便進行後續的詳細分析。","idx":360},{"id":"UP-L122-47","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"製造產品時，確保製程流程完整性的方法是什麼？","options":{"A":"僅參考生產/品管用流程圖","B":"僅進行文件審查","C":"直接到現場了解並比對相關文件","D":"假設所有產品製造步驟相同"},"answer":"C","explanation":"直接現場觀察結合文件審查，可以最真實、最全面地理解產品的製造過程，避免漏洞和錯誤。","idx":361},{"id":"UP-L122-48","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"提供服務時，應如何確保製程流程圖的完整性？","options":{"A":"假設所有服務流程相同","B":"僅記錄服務開始和結束","C":"思考被服務對象在系統中的全程體驗","D":"僅考慮服務的主要部分"},"answer":"C","explanation":"完整記錄從服務開始到結束的全過程，包括客戶如何進入系統、接受哪些服務以及如何離開系統，可以確保服務製程的完整性和準確性。","idx":362},{"id":"UP-L122-49","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在考慮未來盤查複雜度時，應如何處理製程流程圖？","options":{"A":"完全不進行簡化","B":"隨意刪除一些看似不重要的步驟","C":"做適度簡化，保留重要信息","D":"僅保留開頭和結尾的步驟"},"answer":"C","explanation":"適度簡化可以減少未來盤查時的複雜度，同時確保重要的製程步驟和信息被完整記錄，平衡了詳細程度和實用性。","idx":363},{"id":"UP-L122-50","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"系統邊界的選擇應基於什麼原則？","options":{"A":"個人喜好","B":"研究目標一致性","C":"最簡單的製程","D":"最低成本"},"answer":"B","explanation":"系統邊界的選擇應與研究目標保持一致，以確保分析的準確性和目標的達成，而不是基於其他非目標導向的因素。","idx":364},{"id":"UP-L122-51","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"產品碳足盤查過程中，針對特定的產品/服務進行環境宣告之生命週期範疇界定的作業程序文件。目的在使相同功能產品/服務就其環境衝擊量化後之環境宣告，具有一致的比較基礎。這份文件稱之為何？","options":{"A":"生命週期評估(LCA)","B":"物質安全資料表(MSDS)","C":"產品類別規則(PCR)","D":"物質流成本分析(MFCA)"},"answer":"C","explanation":"產品類別規則(PCR)。","idx":365},{"id":"UP-L122-52","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"計算產品碳足跡時，須事先找尋符合的產品類別規則嗎？","options":{"A":"需要","B":"不需要","C":"隨心情而定","D":"以上皆可"},"answer":"A","explanation":"若有相關的 PCR 應予採用。","idx":366},{"id":"UP-L122-53","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在產品類別規則(PCR)中，「功能單位」的目的是什麼？","options":{"A":"確定產品的最低銷售價格","B":"為產品系統量化績效提供參照單位","C":"計算產品的生產成本","D":"確定產品的市場定位"},"answer":"B","explanation":"「功能單位」是一個關鍵概念，用於碳足跡和環境影響評估中，它提供了一個標準化的參考點，使得不同產品或服務之間的環境表現可以被公平地比較。","idx":367},{"id":"UP-L122-54","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"PCR 文檔中提到的「系統邊界」是指什麼？","options":{"A":"產品的銷售範圍","B":"產品製造過程中使用的技術類型","C":"決定哪些階段的範疇納入碳足跡計算","D":"產品的利潤邊界"},"answer":"C","explanation":"「系統邊界」確定了碳足跡評估將涵蓋的生命週期階段，包括時間、地域、技術等範疇的考量，是進行準確碳足跡評估的關鍵步驟。","idx":368},{"id":"UP-L122-55","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"PCR 中提及的「切斷規則」主要用於什麼目的？","options":{"A":"確定產品的銷售策略","B":"忽略碳足跡計算中的重要階段","C":"允許忽略對總排放貢獻微小的過程","D":"增加碳足跡計算的準確性"},"answer":"C","explanation":"切斷規則允許在碳足跡評估中忽略對總溫室氣體排放貢獻小於一定百分比的過程，從而簡化評估過程，同時確保評估的準確性不會因此而受到重大影響。","idx":369},{"id":"UP-L122-56","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在 PCR 中，「分配規則」是指？","options":{"A":"決定產品價格的機制","B":"根據物理性質分配投入和產出的方法","C":"選擇產品的銷售地區","D":"計算產品利潤的規則"},"answer":"B","explanation":"分配規則在多產品系統的環境影響評估中尤為重要，它確定了如何根據實際數量、重量等物理性質，將共同過程的環境負荷合理地分配到各個產品上，確保碳足跡評估的公正性和準確性。","idx":370},{"id":"UP-L122-57","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"根據環境部的產品類別規則，對於生命週期各階段數據蒐集的要求，以下哪一項描述是正確的？","options":{"A":"原料取得階段必須收集所有二級活動數據","B":"生產製造階段僅需使用估算數據","C":"優先採用一級活動數據，但不強制要求收集","D":"銷售階段的數據可以完全忽略"},"answer":"C","explanation":"在進行碳足跡評估時，雖然優先考慮使用直接相關的(一級)活動數據，但若無法獲得，也不會強制要求其必須收集。","idx":371},{"id":"UP-L122-58","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在產品類別規則(PCR)文檔中，對於名詞定義的描述主要目的是什麼？","options":{"A":"提供特定產品類別的專業術語解釋","B":"詳述產品的市場定位和銷售策略","C":"計算產品的生產成本和價格","D":"確定產品的銷售地區和目標客戶"},"answer":"A","explanation":"名詞定義在 PCR 文檔中的重要性在於提供清晰的術語解釋，以確保所有參與碳足跡評估的利害關係者對於專業術語有共同的理解，這有助於增加評估的透明度和準確性。","idx":372},{"id":"UP-L122-59","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在進行產品碳足跡評估時，「功能單位」的設定主要用於實現什麼目標？","options":{"A":"確定產品的廣告與推廣策略","B":"作為衡量產品系統性能的基準點","C":"計算產品的製造與銷售成本","D":"確認產品在市場上的競爭力"},"answer":"B","explanation":"「功能單位」提供了一個標準化的參考，使得可以對產品或服務的環境影響進行量化和比較，這有助於在碳足跡評估中公平地衡量不同產品的性能。","idx":373},{"id":"UP-L122-60","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在產品類別規則(PCR)中，設定「系統邊界」的主要目的是為了什麼？","options":{"A":"確認產品的銷售區域和目標市場","B":"計算產品的市場價值和銷售利潤","C":"選擇產品的原材料來源和供應商","D":"定義在碳足跡評估中將考慮哪些生命週期階段"},"answer":"D","explanation":"系統邊界可明確界定在產品碳足跡評估過程中包括的範圍，如哪些生產階段、運輸階段等將被納入考量，這對於保證評估的全面性和準確性至關重要。","idx":374},{"id":"UP-L122-61","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"衝擊評估階段屬於生命週期評估作業 LCA 的第幾階段？","options":{"A":"第一階段","B":"第二階段","C":"第三階段","D":"第四階段"},"answer":"C","explanation":"第三階段。","idx":375},{"id":"UP-L122-62","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"盤查分析階段屬於生命週期評估作業 LCA 的第幾階段？","options":{"A":"第一階段","B":"第二階段","C":"第三階段","D":"第四階段"},"answer":"B","explanation":"第二階段。","idx":376},{"id":"UP-L122-63","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在 LCA 的衝擊評估階段，溫室氣體排放與移除量應選擇何種 GWP 值計算？","options":{"A":"GWP-10 年","B":"GWP-100 年","C":"該 GWP-200 年","D":"GWP-500 年"},"answer":"B","explanation":"GWP-100 年。","idx":377},{"id":"UP-L122-64","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"使用生命週期評估進行產品碳足跡評估不會經歷哪個重要階段？","options":{"A":"盤查分析","B":"目標範疇定義","C":"闡釋","D":"實驗"},"answer":"D","explanation":"依 ISO 14040/14044，生命週期評估包含目標與範疇界定、盤查分析（LCI）、衝擊評估（LCIA）、闡釋四階段，不含「實驗」，故選 D。","idx":378},{"id":"UP-L122-65","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"功能單位是在哪個生命週期階段被定義？","options":{"A":"盤查分析","B":"目標範疇定義","C":"闡釋","D":"生命週期衝擊評估"},"answer":"B","explanation":"功能單位在目標範疇定義階段被定義清楚。","idx":379},{"id":"UP-L122-66","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"生命週期評估(LCA)的目的是什麼？","options":{"A":"僅評估產品的經濟效益","B":"評估產品或服務從原物料取得到最終處置的環境影響","C":"評估員工的工作效率","D":"計算產品的市場價值"},"answer":"B","explanation":"生命週期評估(LCA)的主要目的是全面評估產品或服務在其生命週期中對環境的潛在影響，包括能源使用、資源耗用、污染排放等。","idx":380},{"id":"UP-L122-67","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"在生命週期評估中，目標與範疇界定的重要性是什麼？","options":{"A":"決定產品的價格","B":"界定評估的範圍和目的，確保評估結果的有效應用","C":"選擇適合的廣告平台","D":"計算生產成本"},"answer":"B","explanation":"目標與範疇界定階段是確定 LCA 評估作業的目的與範圍，這有助於使評估流程易於掌握，並確保評估結果能夠有效地應用於決策過程中。","idx":381},{"id":"UP-L122-68","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"生命週期盤查分析(LCI)主要包括哪些內容？","options":{"A":"數據收集與清單計算","B":"員工訓練計畫","C":"銷售策略分析","D":"市場調研"},"answer":"A","explanation":"生命週期盤查分析 (LCI)階段主要涉及系統相關投入與產出的數據收集及計算，其目的是量化產品生命週期中的各類投入與產出。","idx":382},{"id":"UP-L122-69","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"生命週期衝擊評估(LCIA)的主要目標是什麼？","options":{"A":"確定產品的最終銷售價格","B":"評估產品生命週期中的環境衝擊","C":"分析公司的財務狀況","D":"評估市場競爭情況"},"answer":"B","explanation":"生命週期衝擊評估(LCIA)階段的目標是利用生命週期盤查分析的結果，評估產品在其生命週期中對環境造成的潛在衝擊，這有助於識別改善機會。","idx":383},{"id":"UP-L122-70","source":"unit_practice","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"生命週期闡釋的目的是什麼？","options":{"A":"提高產品銷量","B":"合併盤查分析與衝擊評估結果，提供決策支持","C":"選擇供應商","D":"招聘員工"},"answer":"B","explanation":"生命週期闡釋階段旨在整合生命週期盤查分析和生命週期衝擊評估的結果，並與評估的目的和範圍相匹配，最終提供結論和建議，以支持更環境友好的決策制定。","idx":384},{"id":"AU-L111-01","source":"authored","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"《巴黎協定》對全球升溫控制的目標，下列敘述何者最正確？","options":{"A":"將升溫控制在工業化前水準以上 3°C 內","B":"將升溫控制在遠低於 2°C，並努力限制於 1.5°C","C":"僅要求已開發國家將升溫限制在 1°C","D":"不設定具體升溫數值目標"},"answer":"B","explanation":"《巴黎協定》（2015，COP21）揭示將全球平均升溫控制在「遠低於 2°C」，並努力限制於 1.5°C，為全球共同長期目標。","idx":385},{"id":"AU-L111-02","source":"authored","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"《京都議定書》所建立的三項彈性減量機制，不包括下列何者？","options":{"A":"清潔發展機制（CDM）","B":"排放交易（ET）","C":"共同執行（JI）","D":"碳邊境調整機制（CBAM）"},"answer":"D","explanation":"京都議定書三項彈性機制為 CDM、ET、JI；CBAM 為歐盟於近年推動之碳邊境調整機制，與京都機制無關，故選 D。","idx":386},{"id":"AU-L111-03","source":"authored","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"關於「共同但有區別的責任及各自能力（CBDR-RC）」原則，下列何者正確？","options":{"A":"所有國家承擔完全相同的減排義務","B":"開發中國家須率先達成碳中和","C":"已開發國家應率先減排並支援開發中國家","D":"僅依各國人口決定減排責任"},"answer":"C","explanation":"CBDR-RC 原則承認各國歷史責任與能力不同，已開發國家應率先減排，並對開發中國家提供資金與技術支援，故選 C。","idx":387},{"id":"AU-L111-04","source":"authored","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"下列關於「淨零」與「碳中和」的敘述，何者最正確？","options":{"A":"兩者皆指完全不排放任何溫室氣體","B":"淨零僅涵蓋二氧化碳，碳中和涵蓋所有溫室氣體","C":"兩者皆以「先減量、剩餘排放再抵換」為原則","D":"碳中和不允許使用任何抵換"},"answer":"C","explanation":"淨零與碳中和皆遵循先積極減量、剩餘排放再以移除或碳權抵換的原則；一般而言淨零涵蓋所有溫室氣體，碳中和多聚焦二氧化碳，故選 C。","idx":388},{"id":"AU-L111-05","source":"authored","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L111","stem":"COP28（2023 年杜拜）在氣候資金方面的重要成果為何？","options":{"A":"宣布廢止巴黎協定","B":"正式通過設立「損失與損害基金」","C":"取消國家自主貢獻制度","D":"要求開發中國家停止使用再生能源"},"answer":"B","explanation":"COP28 正式通過設立「損失與損害基金」，以協助因氣候變遷遭受重大損失的脆弱國家，故選 B。","idx":389},{"id":"AU-L112-01","source":"authored","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"科學基礎減量目標倡議（SBTi）是由哪些組織共同發起？","options":{"A":"CDP、聯合國全球盟約（UNGC）、世界資源研究所（WRI）、世界自然基金會（WWF）","B":"ISO、IEC、WTO、OECD","C":"僅由歐盟執委會發起","D":"聯合國安全理事會"},"answer":"A","explanation":"SBTi 由 CDP、聯合國全球盟約（UNGC）、世界資源研究所（WRI）與世界自然基金會（WWF）共同發起，協助企業設定符合科學的減量目標，故選 A。","idx":390},{"id":"AU-L112-02","source":"authored","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"氣候相關財務揭露（TCFD）建議的四大核心要素為何？","options":{"A":"生產、行銷、財務、人資","B":"治理、策略、風險管理、指標與目標","C":"範疇一、範疇二、範疇三、範疇四","D":"盤查、登錄、查驗、申報"},"answer":"B","explanation":"TCFD 四大核心要素為治理、策略、風險管理、指標與目標，作為企業揭露氣候相關財務資訊的架構，故選 B。","idx":391},{"id":"AU-L112-03","source":"authored","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"關於歐盟碳邊境調整機制（CBAM），下列敘述何者正確？","options":{"A":"目的是鼓勵碳洩漏","B":"過渡期即須購買憑證","C":"為防止碳洩漏，對進口高碳產品課徵碳成本","D":"僅適用歐盟境內生產之產品"},"answer":"C","explanation":"CBAM 旨在防止碳洩漏，對進口高碳排產品課徵相當於歐盟碳價的成本；過渡期僅需申報、正式期始須購買 CBAM 憑證，故選 C。","idx":392},{"id":"AU-L112-04","source":"authored","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"RE100 倡議的核心訴求為何？","options":{"A":"企業承諾 100% 使用再生能源","B":"政府承諾 100% 興建核電","C":"企業減少 100% 用水","D":"全面禁止碳交易"},"answer":"A","explanation":"RE100 由 The Climate Group 與 CDP 主導，號召企業承諾達成 100% 使用再生能源，故選 A。","idx":393},{"id":"AU-L112-05","source":"authored","subject":"考科一：淨零碳規劃管理基礎概論","subjectId":"s1","exam":null,"unit":"L112","stem":"台灣 2050 淨零排放路徑的「四大轉型」為下列何者？","options":{"A":"能源、產業、生活、社會","B":"土地、海洋、空氣、水","C":"農業、工業、商業、服務業","D":"中央、地方、企業、個人"},"answer":"A","explanation":"台灣 2050 淨零路徑以能源、產業、生活、社會四大轉型為主軸，並輔以科技研發與氣候法制兩大治理基礎及十二項關鍵戰略，故選 A。","idx":394},{"id":"AU-L121-01","source":"authored","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"ISO 14064-1:2018 規範的盤查層級為何？","options":{"A":"產品層級","B":"組織層級","C":"國家層級","D":"專案層級"},"answer":"B","explanation":"ISO 14064-1:2018 規範「組織層級」的溫室氣體盤查、量化與報告原則；產品碳足跡則由 ISO 14067 規範，故選 B。","idx":395},{"id":"AU-L121-02","source":"authored","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"下列何者不屬於溫室氣體盤查所涵蓋的七種溫室氣體？","options":{"A":"甲烷（CH4）","B":"氧化亞氮（N2O）","C":"一氧化碳（CO）","D":"六氟化硫（SF6）"},"answer":"C","explanation":"盤查涵蓋 CO2、CH4、N2O、HFCs、PFCs、SF6、NF3 共七種；一氧化碳（CO）並非列管之溫室氣體，故選 C。","idx":396},{"id":"AU-L121-03","source":"authored","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"ISO 14064-1:2018 以「排放類別（category）」取代舊版何種分類？","options":{"A":"範疇（scope）一／二／三","B":"生命週期階段","C":"行業別","D":"氣體種類"},"answer":"A","explanation":"2018 版以六大「排放類別」取代舊版以範疇（scope）一／二／三的分類方式，類別 1 為直接排放、類別 2 為輸入能源間接排放、類別 3–6 為其他間接排放，故選 A。","idx":397},{"id":"AU-L121-04","source":"authored","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"溫室氣體排放量換算為共同比較單位時，係以何者表示？","options":{"A":"公噸原油當量","B":"二氧化碳當量（CO2e）","C":"千瓦小時","D":"標準大氣壓"},"answer":"B","explanation":"各溫室氣體乘以其全球暖化潛勢（GWP）後，統一以二氧化碳當量（CO2e）表示，以利加總與比較，故選 B。","idx":398},{"id":"AU-L121-05","source":"authored","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L121","stem":"組織設定盤查邊界時，常用的方法為下列何者？","options":{"A":"控制權法（營運／財務控制）或股權比例法","B":"先進先出法","C":"抽樣調查法","D":"線性回歸法"},"answer":"A","explanation":"組織邊界可採控制權法（營運控制或財務控制）或股權比例法設定，以界定納入盤查的排放源範圍，故選 A。","idx":399},{"id":"AU-L122-01","source":"authored","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"產品碳足跡（CFP）量化所依據的方法基礎為何？","options":{"A":"投入產出貨幣分析","B":"生命週期評估（LCA）","C":"問卷調查","D":"財務報表分析"},"answer":"B","explanation":"ISO 14067 以生命週期評估（LCA）為方法基礎，評估產品自原物料取得至生命終結各階段的溫室氣體排放與移除，故選 B。","idx":400},{"id":"AU-L122-02","source":"authored","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"「搖籃到大門（cradle-to-gate）」的系統邊界涵蓋範圍為何？","options":{"A":"自原物料取得至產品出廠（不含使用與廢棄）","B":"自產品使用至最終處置","C":"僅涵蓋製造單一階段","D":"涵蓋完整生命週期直到廢棄"},"answer":"A","explanation":"搖籃到大門涵蓋自原物料取得至產品出廠為止，不含使用與生命終結階段；涵蓋完整生命週期者為搖籃到墳墓（cradle-to-grave），故選 A。","idx":401},{"id":"AU-L122-03","source":"authored","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"關於產品類別規則（PCR），下列敘述何者正確？","options":{"A":"每家企業可自訂且不需一致","B":"為同類產品碳足跡量化與溝通的一致規則，有相關 PCR 時應優先採用","C":"僅適用於服務業","D":"與 ISO 14067 無關"},"answer":"B","explanation":"PCR 為同一產品類別進行碳足跡量化與溝通的一致規則；依 ISO 14067，若有相關 PCR 應優先採用，以確保結果可比較，故選 B。","idx":402},{"id":"AU-L122-04","source":"authored","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"生命週期評估（LCA）的四個階段，正確順序為何？","options":{"A":"盤查分析→目標界定→闡釋→衝擊評估","B":"目標與範疇界定→盤查分析（LCI）→衝擊評估（LCIA）→闡釋","C":"衝擊評估→闡釋→盤查分析→目標界定","D":"目標界定→衝擊評估→盤查分析→闡釋"},"answer":"B","explanation":"依 ISO 14040/14044，LCA 四階段依序為目標與範疇界定、生命週期盤查分析（LCI）、生命週期衝擊評估（LCIA）、生命週期闡釋，故選 B。","idx":403},{"id":"AU-L122-05","source":"authored","subject":"考科二：溫室氣體盤查規範與程序概要","subjectId":"s2","exam":null,"unit":"L122","stem":"ISO 14067 處理共用製程的排放分配時，應優先採行何種作法？","options":{"A":"盡量避免分配（細分製程或擴大系統邊界）","B":"一律依產品重量平均分配","C":"一律依售價分配","D":"忽略共用製程排放"},"answer":"A","explanation":"依 ISO 14067，應盡量避免分配（例如細分單元過程或擴大系統邊界）；無法避免時先依物理關係、再依經濟價值等比例分配，故選 A。","idx":404}]};
